window.BASAIR_QUESTIONS=(window.BASAIR_QUESTIONS||[]).concat([{"id":"s4-191","number":191,"surah":4,"verses":[88,89,90,91],"references":[{"surah":4,"verses":[88,89,90,91]}],"verseLabel":"النساء: 88–91","question":"ما سرّ التعبير في قوله تعالى: ﴿وَاللَّهُ أَرْكَسَهُمْ بِمَا كَسَبُوا﴾، واختار «أركسهم»؟","answer":"أركسهم: ردهم إلى الضلال بسبب كسبهم. وصُوّر رجوعهم من الإيمان إلى الكفر بالارتكاس والانقلاب، لإظهار قبح حالهم وشدّة انغماسهم فيما اختاروه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص543–544، تحت «بلاغة الاستعارة في قوله تعالى: ﴿والله أركسهم بما كسبوا﴾».","url":""}]},{"id":"s4-192","number":192,"surah":4,"verses":[88,89,90,91],"references":[{"surah":4,"verses":[88,89,90,91]}],"verseLabel":"النساء: 88–91","question":"ما سرّ التعبير في قوله تعالى: ﴿أَتُرِيدُونَ أَنْ تَهْدُوا مَنْ أَضَلَّ اللَّهُ﴾، فنسب الإضلال إلى الله؟","answer":"الإضلال خذلان جزائي على الكسب والإعراض بعد الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص544–546، تحت «دلالة الباء في ﴿بما﴾ ونكتة التعبير بالكسب دون الاكتساب في قوله تعالى: ﴿بما كسبوا﴾».","url":""}]},{"id":"s4-193","number":193,"surah":4,"verses":[88,89,90,91],"references":[{"surah":4,"verses":[88,89,90,91]}],"verseLabel":"النساء: 88–91","question":"ما سرّ التعبير في قوله تعالى: ﴿وَدُّوا لَوْ تَكْفُرُونَ كَمَا كَفَرُوا فَتَكُونُونَ سَوَاءً﴾، وحذف جهة التساوي؟","answer":"حُذف متعلق ﴿سَوَاءً﴾ لأن السياق يبينه ويعممه: يريدون أن تتساووا معهم في الكفر وما يتبعه من الموقف والمصير، فلا يبقى بين الفريقين فرق.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص556، تحت «دلالة الإطلاق في قوله تعالى: ﴿فتكونون سواء﴾».","url":""}]},{"id":"s4-194","number":194,"surah":4,"verses":[88,89,90,91],"references":[{"surah":4,"verses":[88,89,90,91]}],"verseLabel":"النساء: 88–91","question":"لماذا صور ضيقهم عن القتال بقوله: ﴿حَصِرَتْ صُدُورُهُمْ﴾؟","answer":"حصرت صدورهم تصور ضيق النفس عن قتال الفريقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص566–567، تحت «نكتة التعبير بـ﴿حصرت﴾ في قوله تعالى: ﴿أو جاءوكم حصرت صدورهم أن يقاتلوكم أو يقاتلوا قومهم﴾».","url":""}]},{"id":"s4-195","number":195,"surah":4,"verses":[88,89,90,91],"references":[{"surah":4,"verses":[88,89,90,91]}],"verseLabel":"النساء: 88–91","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَوْ شَاءَ اللَّهُ لَسَلَّطَهُمْ عَلَيْكُمْ فَلَقَاتَلُوكُمْ﴾، وحذف مفعول المشيئة؟","answer":"حذف مفعول ﴿شَاءَ﴾ لأن جواب الشرط يفسره: لو شاء الله تسليطهم عليكم لسلطهم فقاتلوكم؛ والحذف يوجز ويجعل المشيئة محيطة بكل تفاصيل ذلك التسليط.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص567–568، تحت «بلاغة الحذف في قوله تعالى: ﴿ولو شاء الله لسلطهم عليكم فلقاتلوكم﴾».","url":""}]},{"id":"s4-196","number":196,"surah":4,"verses":[88,89,90,91],"references":[{"surah":4,"verses":[88,89,90,91]}],"verseLabel":"النساء: 88–91","question":"لماذا كرر في وصف الفريق الآخر: ﴿يُرِيدُونَ أَنْ يَأْمَنُوكُمْ وَيَأْمَنُوا قَوْمَهُمْ﴾؟","answer":"كرر ﴿يَأْمَنُوكُمْ وَيَأْمَنُوا قَوْمَهُمْ﴾ لكشف طلبهم أمنين متعارضين: يظهرون لكل فريق ما يرضيه ليأمنوا جانبه، من غير ولاء صادق لأحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص576–577، تحت «نكتة تقديم أمنهم المؤمنين على أمنهم قومهم في قوله تعالى: ﴿ستجدون آخرين يريدون أن يأمنوكم ويأمنوا قومهم﴾».","url":""}]},{"id":"s4-197","number":197,"surah":4,"verses":[88,89,90,91],"references":[{"surah":4,"verses":[88,89,90,91]}],"verseLabel":"النساء: 88–91","question":"ما سرّ التعبير في قوله تعالى: ﴿كُلَّمَا رُدُّوا إِلَى الْفِتْنَةِ أُرْكِسُوا فِيهَا﴾، واختار «أركسوا» مرة أخرى؟","answer":"أركسوا فيها تصور القلب والانغماس المتكرر في الفتنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص577–578، تحت «براعة الاستعارة في قوله تعالى: ﴿أركسوا فيها﴾».","url":""}]},{"id":"s4-198","number":198,"surah":4,"verses":[88,89,90,91],"references":[{"surah":4,"verses":[88,89,90,91]}],"verseLabel":"النساء: 88–91","question":"لماذا ختم الحكم بقوله: ﴿وَأُولَئِكُمْ جَعَلْنَا لَكُمْ عَلَيْهِمْ سُلْطَانًا مُبِينًا﴾؟","answer":"الخاتمة تمنح حجة ظاهرة على من رفض الاعتزال والسلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص580، 582، تحت «دلالة حرف الجر ﴿على﴾ في قوله تعالى: ﴿وأولئكم جعلنا لكم عليهم سلطانًا مبينًا﴾».","url":""}]},{"id":"s4-199","number":199,"surah":4,"verses":[92,93],"references":[{"surah":4,"verses":[92,93]}],"verseLabel":"النساء: 92–93","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَا كَانَ لِمُؤْمِنٍ أَنْ يَقْتُلَ مُؤْمِنًا إِلَّا خَطَأً﴾؛ وكيف استثني الخطأ من القتل المنفي؟","answer":"توجه الموسوعة الاستثناء على الاتصال: فنُفي وقوع القتل من المؤمن في جميع الأحوال إلا حال الخطأ. وهذا استثناء لحالة غير مقصودة، لا ترخيص في قتل المؤمن عمدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص589، تحت «دلالة أسلوب الاستثناء في الكلام».","url":""}]},{"id":"s4-200","number":200,"surah":4,"verses":[92,93],"references":[{"surah":4,"verses":[92,93]}],"verseLabel":"النساء: 92–93","question":"لماذا اختير وصف المؤمن في قوله تعالى: ﴿وما كان لمؤمن أن يقتل مؤمنًا﴾ بدل المسلم؟","answer":"اختير المؤمن لأن الحكم يتعلق بالإيمان الباطن، لا بمجرد المظهر؛ وفي وصف الإيمان ما ينفر صاحبه من قتل أخيه المؤمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص589، تحت «إيثار اختيار (المؤمن) دون (المسلم)».","url":""}]},{"id":"s4-201","number":201,"surah":4,"verses":[92,93],"references":[{"surah":4,"verses":[92,93]}],"verseLabel":"النساء: 92–93","question":"لماذا عبر عن الإنسان كله بـ﴿رَقَبَةٍ﴾؟","answer":"الرقبة مجاز مرسل عن الإنسان كله لأنها موضع الملك والقيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص591، تحت «بديع المجاز المرسل في تحرير الرقبة».","url":""}]},{"id":"s4-202","number":202,"surah":4,"verses":[92,93],"references":[{"surah":4,"verses":[92,93]}],"verseLabel":"النساء: 92–93","question":"ما سرّ التعبير في قوله تعالى: ﴿وَدِيَةٌ مُسَلَّمَةٌ إِلَى أَهْلِهِ﴾ بصيغة اسم المفعول؟","answer":"«مسلّمة» تؤكد إتمام إيصال الدية إلى أهل القتيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص593، تحت «سبب إيثار صيغة اسم المفعول ﴿مسلمة﴾».","url":""}]},{"id":"s4-203","number":203,"surah":4,"verses":[92,93],"references":[{"surah":4,"verses":[92,93]}],"verseLabel":"النساء: 92–93","question":"لماذا سمى عفو أهل القتيل صدقة: ﴿إِلَّا أَنْ يَصَّدَّقُوا﴾؟","answer":"إسقاط أهل القتيل حقهم سمي صدقة لتبرعهم وتقربهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص593–594، تحت «بلاغة الاستعارة في قوله: ﴿إلا أن يصدقوا﴾».","url":""}]},{"id":"s4-204","number":204,"surah":4,"verses":[92,93],"references":[{"surah":4,"verses":[92,93]}],"verseLabel":"النساء: 92–93","question":"لماذا سمى الكفارة ﴿تَوْبَةً مِنَ اللَّهِ﴾؟","answer":"الكفارة توبة مشرعة من الله للرجوع ومحو أثر الخطأ.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص597–598، تحت «تنوع المعنى بتنوع إعراب التوبة».","url":""}]},{"id":"s4-205","number":205,"surah":4,"verses":[92,93],"references":[{"surah":4,"verses":[92,93]}],"verseLabel":"النساء: 92–93","question":"لماذا ذُكر قتل الخطأ قبل القتل العمد مع أن العمد أشد؟","answer":"بعد التنفير من قتل الخطأ، مع قيام العذر فيه، انتقل السياق إلى ما هو أغلظ ولا عذر فيه؛ فترقّى من الخطأ إلى العمد تمهيدًا لتشديد الوعيد على مرتكبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص601، تحت «مناسبة الآية لما قبلها».","url":""}]},{"id":"s4-206","number":206,"surah":4,"verses":[92,93],"references":[{"surah":4,"verses":[92,93]}],"verseLabel":"النساء: 92–93","question":"لماذا توالت هذه الألوان الخمسة من الوعيد للقاتل عمدًا: جهنم، والخلود، والغضب، واللعن، وإعداد العذاب العظيم؟","answer":"في تتابع هذا الوعيد تهويل لشأن قتل المؤمن عمدًا، وبيان لبشاعة الجناية: يجمع العقاب الشديد والطرد من رحمة الله، فيبلغ التحذير من سفك الدم بغير حق غايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص601–602، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s4-207","number":207,"surah":4,"verses":[93],"references":[{"surah":4,"verses":[93]}],"verseLabel":"النساء: 93","question":"لماذا ختم وعيد قاتل المؤمن بـ﴿وَأَعَدَّ لَهُ عَذَابًا عَظِيمًا﴾، بينما قال في المنافقين والمشركين في الفتح: ﴿وَأَعَدَّ لَهُمْ جَهَنَّمَ﴾؟","answer":"في النساء سُردت عقوبات قاتل المؤمن ثم خُتمت بجنس العذاب العظيم ليضم ما ذُكر وغيره؛ وفي الفتح عُيّنت جهنم للمنافقين والمشركين بعد ذكر ظنهم بالله، فناسب التصريح بالدار المعدة لهم.","sources":[{"label":"*مختصر لمسات بيانية*؛ منقول في Quranpedia، ملاحظة 43384","url":""}]},{"id":"s4-208","number":208,"surah":4,"verses":[94,95,96,97,98,99,100],"references":[{"surah":4,"verses":[94,95,96,97,98,99,100]}],"verseLabel":"النساء: 94–100","question":"لماذا عبر عن السفر للجهاد بقوله: ﴿إِذَا ضَرَبْتُمْ فِي سَبِيلِ اللَّهِ﴾؟","answer":"الضرب في سبيل الله كناية عن السير في الأرض بقصد الجهاد؛ إذ قرينة «في سبيل الله» تعين الغاية من السفر، فلا يراد مجرد الانتقال في الأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص610، تحت «بلاغة الكناية في قوله: ﴿ضربتم في سبيل الله﴾».","url":""}]},{"id":"s4-209","number":209,"surah":4,"verses":[94,95,96,97,98,99,100],"references":[{"surah":4,"verses":[94,95,96,97,98,99,100]}],"verseLabel":"النساء: 94–100","question":"ما سرّ التعبير في قوله تعالى: ﴿فَتَبَيَّنُوا﴾، دون أن يقال: فتثبتوا؟","answer":"التبين طلب ظهور الحقيقة بعد الفحص، أخص من مجرد التثبت والتأني.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص611–612، تحت «توجيه القراءات القرآنية في لفظ ﴿فتبينوا﴾».","url":""}]},{"id":"s4-210","number":210,"surah":4,"verses":[94,95,96,97,98,99,100],"references":[{"surah":4,"verses":[94,95,96,97,98,99,100]}],"verseLabel":"النساء: 94–100","question":"ما سرّ التعبير في قوله تعالى: ﴿لِمَنْ أَلْقَى إِلَيْكُمُ السَّلَامَ﴾، فصور السلام شيئًا يلقى؟","answer":"إلقاء السلام يصوره علامة ظاهرة مقدمة إليهم توجب الكف والتحقق.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص613–614، تحت «بلاغة التعبير عن السلام بالإلقاء».","url":""}]},{"id":"s4-211","number":211,"surah":4,"verses":[94,95,96,97,98,99,100],"references":[{"surah":4,"verses":[94,95,96,97,98,99,100]}],"verseLabel":"النساء: 94–100","question":"ما سرّ التعبير في قوله تعالى: ﴿لَسْتَ مُؤْمِنًا﴾، دون أن يقال: لست مسلمًا؟","answer":"نهاهم أن ينفوا عنه الإيمان الذي أظهر علامته، لأن السرائر إلى الله، ولأن الحكم الدنيوي يتعلق بالظاهر؛ فاختيار ﴿مُؤْمِنًا﴾ يغلظ إنكار التسرع في إسقاط حرمة المؤمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص615، تحت «وجه التعبير عن الإيمان باسم الفاعل».","url":""}]},{"id":"s4-212","number":212,"surah":4,"verses":[94,95,96,97,98,99,100],"references":[{"surah":4,"verses":[94,95,96,97,98,99,100]}],"verseLabel":"النساء: 94–100","question":"لماذا سمى متاع الدنيا ﴿عَرَضَ الْحَيَاةِ الدُّنْيَا﴾؟","answer":"العرض متاع عارض زائل غير ثابت، فناسب غنيمة الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص616، تحت «نكتة التعبير بـ﴿عرض﴾».","url":""}]},{"id":"s4-213","number":213,"surah":4,"verses":[94,95,96,97,98,99,100],"references":[{"surah":4,"verses":[94,95,96,97,98,99,100]}],"verseLabel":"النساء: 94–100","question":"لماذا قابل عرض الدنيا بقوله: ﴿فَعِنْدَ اللَّهِ مَغَانِمُ كَثِيرَةٌ﴾؟","answer":"قابل الزائل القليل بمغانم كثيرة ثابتة عند الله لرد باعث الطمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص617–618، تحت «دلالة الفاء في قوله: ﴿فعند الله مغانم كثيرة﴾».","url":""}]},{"id":"s4-214","number":214,"surah":4,"verses":[94,95,96,97,98,99,100],"references":[{"surah":4,"verses":[94,95,96,97,98,99,100]}],"verseLabel":"النساء: 94–100","question":"ما سرّ التعبير في قوله تعالى: ﴿كَذَلِكَ كُنْتُمْ مِنْ قَبْلُ فَمَنَّ اللَّهُ عَلَيْكُمْ﴾، واختار «منَّ» بدل «أنعم»؟","answer":"«منّ» تستحضر نعمة عظيمة بلا استحقاق حين أظهر الله إيمانهم بعد خفائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص619، تحت «نكتة إيثار (من) دون (أنعم)».","url":""}]},{"id":"s4-215","number":215,"surah":4,"verses":[94,95,96,97,98,99,100],"references":[{"surah":4,"verses":[94,95,96,97,98,99,100]}],"verseLabel":"النساء: 94–100","question":"لماذا كرر الأمر: ﴿فَتَبَيَّنُوا﴾ في أول الآية وآخرها؟","answer":"التكرار يؤطر التعليل: أمر قبل التذكير بحالهم وأعيد نتيجة له لتشديد الاحتياط.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص619–620، تحت «تكرار ﴿فتبينوا﴾ بين التأكيد والتأسيس».","url":""}]},{"id":"s4-216","number":216,"surah":4,"verses":[94,95,96,97,98,99,100],"references":[{"surah":4,"verses":[94,95,96,97,98,99,100]}],"verseLabel":"النساء: 94–100","question":"لماذا ختمت الآية بـ﴿إِنَّ اللَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًا﴾، ولم يقل: عليمًا؟","answer":"الخبير يعلم بواطن العمل ودوافع طلب الغنيمة، وهو الأنسب لمقام الاشتباه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص621–622، تحت «سر اقتران وصف الخبير بأعمال المؤمنين».","url":""}]},{"id":"s4-217","number":217,"surah":4,"verses":[94,95,96,97,98,99,100],"references":[{"surah":4,"verses":[94,95,96,97,98,99,100]}],"verseLabel":"النساء: 94–100","question":"لماذا بدأ بالمجاهدين بأموالهم قبل أنفسهم في قوله: ﴿الْمُجَاهِدُونَ فِي سَبِيلِ اللَّهِ بِأَمْوَالِهِمْ وَأَنْفُسِهِمْ﴾؟","answer":"قُدمت الأموال هنا لأن المقام مقام جهاد، والجهاد بالمال أيسر من الجهاد بالنفس؛ فجاء الترتيب من الأدنى إلى الأعلى. أما موضع شراء الله من المؤمنين فناسبه تقديم الأنفس لأنها الأعز والأغلى.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص633، تحت «توجيه التشابه اللفظي في تقديم الأموال على الأنفس والعكس».","url":""}]},{"id":"s4-218","number":218,"surah":4,"verses":[94,95,96,97,98,99,100],"references":[{"surah":4,"verses":[94,95,96,97,98,99,100]}],"verseLabel":"النساء: 94–100","question":"ما سرّ التعبير أولًا بـ﴿دَرَجَةً﴾ ثم بـ﴿دَرَجَاتٍ مِنْهُ﴾ في تفضيل المجاهدين؟","answer":"من توجيهات المصدر أن التفضيل الأول بدرجة ناظر إلى ما في الدنيا من المنزلة، والثاني بدرجات إلى ما في الآخرة. ويذكر وجهًا آخر: أن الأول على القاعدين لعذر، والثاني على القاعدين بلا عذر؛ وجمع الدرجات يفيد سعة الفضل وعظمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص636–638، تحت «نكتة تكرار التفضيل بلفظ ﴿فضل الله﴾ في هذه الآية الكريمة».","url":""}]},{"id":"s4-219","number":219,"surah":4,"verses":[94,95,96,97,98,99,100],"references":[{"surah":4,"verses":[94,95,96,97,98,99,100]}],"verseLabel":"النساء: 94–100","question":"ما سرّ التعبير في قوله تعالى: ﴿وَكُلًّا وَعَدَ اللَّهُ الْحُسْنَى﴾ مع تفضيل المجاهدين؟","answer":"مع تفضيل المجاهدين لم تسلب الآية القاعدين المؤمنين أصل الخير، فقالت ﴿وَكُلًّا وَعَدَ اللَّهُ الْحُسْنَى﴾؛ فجمعت بين إنصاف الفريقين وإظهار مزية الجهاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص635، تحت «فائدة الاعتراض بقوله: ﴿وكلًّا وعد الله الحسنى﴾».","url":""}]},{"id":"s4-220","number":220,"surah":4,"verses":[94,95,96,97,98,99,100],"references":[{"surah":4,"verses":[94,95,96,97,98,99,100]}],"verseLabel":"النساء: 94–100","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّ الَّذِينَ تَوَفَّاهُمُ الْمَلَائِكَةُ﴾، فأظهر الملائكة وأسند إليهم التوفي؟","answer":"أسند التوفي للملائكة لأنهم المباشرون بأمر الله، وإظهارهم يهوّل مشهد المحاسبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص645–646، تحت «نكتة التعبير بـ﴿توفاهم﴾ دون (يموتون) أو (يتوفون)».","url":""}]},{"id":"s4-221","number":221,"surah":4,"verses":[94,95,96,97,98,99,100],"references":[{"surah":4,"verses":[94,95,96,97,98,99,100]}],"verseLabel":"النساء: 94–100","question":"لماذا نُكرت ﴿حيلة﴾ و﴿سبيلًا﴾ في وصف المستضعفين؟","answer":"وقوعهما نكرتين في سياق النفي يفيد العموم؛ فلا يجدون أي حيلة ولا يهتدون إلى أي سبيل للخلاص. بذلك يتبين العجز الحقيقي الذي يُعذر به صاحبه، حين تنسد سبل الهجرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص651، تحت «نكتة التنكير في قوله: ﴿لا يستطيعون حيلة ولا يهتدون سبيلًا﴾».","url":""}]},{"id":"s4-222","number":222,"surah":4,"verses":[94,95,96,97,98,99,100],"references":[{"surah":4,"verses":[94,95,96,97,98,99,100]}],"verseLabel":"النساء: 94–100","question":"ما سرّ التعبير في قوله تعالى في عفو الله عنهم: ﴿فَأُولَئِكَ عَسَى اللَّهُ أَنْ يَعْفُوَ عَنْهُمْ﴾ مع تحقق رحمة الله؟","answer":"«عسى» من الله وعد مع إبقاء العبد بين الرجاء والأدب وعدم الاتكال.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص652، تحت «سر إيراد (عسى) في حق المعذورين حقيقة».","url":""}]},{"id":"s4-223","number":223,"surah":4,"verses":[94,95,96,97,98,99,100],"references":[{"surah":4,"verses":[94,95,96,97,98,99,100]}],"verseLabel":"النساء: 94–100","question":"ما سرّ تقديم ﴿مُرَاغَمًا كَثِيرًا﴾ على ﴿وَسَعَةً﴾ في ثمرات الهجرة؟","answer":"قدم المراغم لأنه أول ثمرة تزيل قهر العدو، ثم أتبعها بسعة الرزق والمقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص660، تحت «نكتة تقديم المراغمة على السعة، في قوله: ﴿مراغمًا كثيرًا وسعة﴾».","url":""}]},{"id":"s4-224","number":224,"surah":4,"verses":[94,95,96,97,98,99,100],"references":[{"surah":4,"verses":[94,95,96,97,98,99,100]}],"verseLabel":"النساء: 94–100","question":"ما سرّ التعبير في قوله تعالى: ﴿مَنْ يَخْرُجْ مِنْ بَيْتِهِ مُهَاجِرًا إِلَى اللَّهِ وَرَسُولِهِ﴾، فنسب الهجرة إلى الله والرسول؟","answer":"نُسبت الهجرة إلى الله ورسوله لبيان أن المقصود بها طاعة الله ورضوانه؛ فالمهاجر يترك وطنه وأهله ابتغاء مرضاته، لا لمجرد غرض من أغراض الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص662، تحت عنوان «سر اختيار لفظ البيت في قوله: ﴿من بيته﴾»","url":""}]},{"id":"s4-225","number":225,"surah":4,"verses":[94,95,96,97,98,99,100],"references":[{"surah":4,"verses":[94,95,96,97,98,99,100]}],"verseLabel":"النساء: 94–100","question":"ما دلالة قوله تعالى فيمن أدركه الموت في طريق الهجرة: ﴿فَقَدْ وَقَعَ أَجْرُهُ عَلَى اللَّهِ﴾؟","answer":"شُبّه الأجر بشيء يقع ويثبت على الاستعارة، للدلالة على تحقق ثوابه ووجوبه بوعد الله وفضله؛ فليس المراد سقوطًا حسيًا، بل تأكيد حصول الأجر.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص663–664، تحت «بلاغة الاستعارة في قول الله سبحانه: ﴿فقد وقع أجره على الله﴾».","url":""}]},{"id":"s4-226","number":226,"surah":4,"verses":[101],"references":[{"surah":4,"verses":[101]}],"verseLabel":"النساء: 101","question":"ما سرّ التعبير في قوله تعالى: ﴿أن تقصروا من الصلاة﴾، دون أن يقال: أن تقصروا الصلاة؟","answer":"«من الصلاة» للتبعيض؛ القصر واقع في بعض هيئتها أو عددها لا إعدام الصلاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص669–670، تحت «دلالة حرف الجر (من) في قوله تعالى: ﴿من الصلاة﴾».","url":""}]},{"id":"s4-227","number":227,"surah":4,"verses":[101],"references":[{"surah":4,"verses":[101]}],"verseLabel":"النساء: 101","question":"لماذا قيل ﴿وإذا ضربتم في الأرض﴾ بـ«إذا»، ثم ﴿إن خفتم أن يفتنكم الذين كفروا﴾ بـ«إن»؟","answer":"السفر أمر متكرر لا يكاد يخلو منه المسلمون، فناسبته «إذا» الدالة على تحقق الوقوع؛ أما خوف فتنة العدو فليس متحققًا في كل سفر، فناسبته «إن» التي لا تجزم بوقوع الشرط.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص671، تحت «الفرق بين تعليق الشرط بـ(إذا) وتعليقه بـ(إن)».","url":""}]},{"id":"s4-228","number":228,"surah":4,"verses":[102],"references":[{"surah":4,"verses":[102]}],"verseLabel":"النساء: 102","question":"ما سرّ التعبير في قوله تعالى: ﴿وإذا كنت فيهم﴾، دون أن يقال: وإذا أقمت فيهم الصلاة؟","answer":"«كنت فيهم» يستحضر حضور النبي وإمامته وتعليمه هيئة الصلاة، وهو أعم من مجرد إقامتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص680، تحت «سر التعبير: ﴿كنت فيهم﴾».","url":""}]},{"id":"s4-229","number":229,"surah":4,"verses":[102],"references":[{"surah":4,"verses":[102]}],"verseLabel":"النساء: 102","question":"ما سرّ التعبير في قوله تعالى: ﴿فلتقم طائفة منهم معك﴾ مع أن النبي ﷺ قائم بينهم أصلًا؟","answer":"القيام معه قيام في الصلاة؛ وتبقى الطائفة الأخرى تجاه العدو للحراسة. وقد حذف ذكر هذه الطائفة أولًا لدلالة تفصيل الطائفة الأخرى بعد ذلك، فلا يجمع الجواب الوظيفتين للطائفة نفسها في الوقت نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص681–683، تحت «بلاغة الاحتباك أو الاكتفاء في قوله: ﴿فلتقم طائفة منهم معك﴾».","url":""}]},{"id":"s4-230","number":230,"surah":4,"verses":[102],"references":[{"surah":4,"verses":[102]}],"verseLabel":"النساء: 102","question":"كيف يُؤخذ الحذر في قوله: ﴿وليأخذوا حذرهم وأسلحتهم﴾، ولمَ عطف السلاح عليه؟","answer":"أخذ الحذر مجاز عن أسبابه، وعطف الأسلحة يخص أهم وسيلة مادية بعد الاستعداد المعنوي.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص684–685، تحت «بلاغة المجاز والكناية في الأمر بأخذ الحذر».","url":""}]},{"id":"s4-231","number":231,"surah":4,"verses":[102],"references":[{"surah":4,"verses":[102]}],"verseLabel":"النساء: 102","question":"لماذا انتقل الكلام من ﴿وليأخذوا حذرهم وأسلحتهم﴾ إلى الخطاب المباشر في ﴿لو تغفلون عن أسلحتكم وأمتعتكم﴾؟","answer":"الانتقال إلى الخطاب إقبالٌ مباشر على المصلين، يزيد تنبيههم وترغيبهم في أخذ الحذر والسلاح؛ فالخطاب أقرب إلى النفوس وأنسب بمقام التحذير من غفلة يترصدها العدو.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص686–687، تحت «سر الالتفات في قوله: ﴿لو تغفلون عن أسلحتكم﴾».","url":""}]},{"id":"s4-232","number":232,"surah":4,"verses":[102],"references":[{"surah":4,"verses":[102]}],"verseLabel":"النساء: 102","question":"ما سرّ التعبير في قوله تعالى: ﴿فيميلون عليكم ميلة واحدة﴾ بالإفراد؟","answer":"«ميلة واحدة» تصور هجمة مجتمعة حاسمة يستغلون بها وضع السلاح، لا جنس الأفراد.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص687–688، تحت «سر التعبير باسم المرة ﴿ميلة﴾».","url":""}]},{"id":"s4-233","number":233,"surah":4,"verses":[102],"references":[{"surah":4,"verses":[102]}],"verseLabel":"النساء: 102","question":"ما سرّ تقديم أذى المطر على المرض في قوله: ﴿إن كان بكم أذى من مطر أو كنتم مرضى﴾؟","answer":"قدم أذى المطر لأنه يعم الطائفتين جميعًا، بخلاف المرض الذي يختص بمن أصابه؛ فمراعاة المصلحة العامة أولى، ثم ذُكر عذر المرض الخاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص689، تحت «بلاغة أسلوب التدلي في تقديم المطر على المرض».","url":""}]},{"id":"s4-234","number":234,"surah":4,"verses":[103],"references":[{"surah":4,"verses":[103]}],"verseLabel":"النساء: 103","question":"لماذا جاء الأمر بذكر الله بعد الفراغ من صلاة الخوف مباشرة؟","answer":"أُمروا بالذكر في القيام والقعود وعلى الجنوب ليستغرق جميع أحوالهم، فيدوم ارتباطهم بالله في حال الخوف ومواجهة العدو.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص698–699، تحت «دلالة أسلوب التقسيم على استيعاب أحوال العبد».","url":""}]},{"id":"s4-235","number":235,"surah":4,"verses":[103],"references":[{"surah":4,"verses":[103]}],"verseLabel":"النساء: 103","question":"لماذا رُتبت أحوال الذكر: ﴿قيامًا وقعودًا وعلى جنوبكم﴾ بهذا الترتيب؟","answer":"الترتيب من أكمل الهيئات وأقواها إلى ما دونها بحسب القدرة: قيام فقعود فاضطجاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص699–700، تحت «بلاغة الترقي في ذكر أحوال العبد».","url":""}]},{"id":"s4-236","number":236,"surah":4,"verses":[103],"references":[{"surah":4,"verses":[103]}],"verseLabel":"النساء: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿فإذا اطمأننتم فأقيموا الصلاة﴾، دون أن يقال: فإذا أمنتم فصلّوا؟","answer":"الاطمئنان أوسع من الأمن، وإقامة الصلاة ردها إلى تمام حدودها وهيئتها لا مجرد أدائها.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص701–702، تحت «أثر تعدد دلالات الإقامة في وفرة المعاني».","url":""}]},{"id":"s4-237","number":237,"surah":4,"verses":[103],"references":[{"surah":4,"verses":[103]}],"verseLabel":"النساء: 103","question":"ما دلالة التعبير عن فرضية الصلاة بلفظ ﴿كتابًا﴾؟","answer":"وُصفت الصلاة بالمصدر «كتابًا» تأكيدًا لفرضيتها؛ فالوصف بالمصدر يزيد المعنى توكيدًا، وينبه إلى عظم شأن الصلاة ووجوب المحافظة عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص703، تحت عنوان «نكتة تأكيد جملة: ﴿إن الصلاة كانت على المؤمنين كتابًا موقوتًا﴾»","url":""}]},{"id":"s4-474","number":474,"surah":4,"verses":[103],"references":[{"surah":4,"verses":[103]}],"verseLabel":"النساء: 103","question":"ما دلالة وصف الصلاة بأنها ﴿موقوتًا﴾؟","answer":"يدل على أن الصلاة فريضة محددة الأوقات، تؤدَّى في أوقاتها المقررة؛ فالتوقيت يضبط زمن أدائها.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص696، تحت عنوان «شرح المفردات»","url":""}]},{"id":"s4-238","number":238,"surah":4,"verses":[104],"references":[{"surah":4,"verses":[104]}],"verseLabel":"النساء: 104","question":"كيف نُهي المؤمنون عن الوهن في قوله: ﴿ولا تهنوا في ابتغاء القوم﴾ مع أن الوهن شعور قد يطرأ على الإنسان؟","answer":"النهي يتوجه إلى وهن القلب وانهيار العزيمة والفتور عن الطلب. وإذا أريد الوهن البدني الناشئ عن التعب، فالمقصود الحث على مقاومته والجد في الطلب، لا نفي ما يعرض للجسد من تعب.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص708، تحت عنوان «سر نهيهم عن الوهن وليس بأيديهم دفعه»","url":""}]},{"id":"s4-239","number":239,"surah":4,"verses":[104],"references":[{"surah":4,"verses":[104]}],"verseLabel":"النساء: 104","question":"لماذا كرر فعل الألم: ﴿إن تكونوا تألمون فإنهم يألمون كما تألمون﴾؟","answer":"تكرار «تألمون/يألمون» يصرح باشتراك الفريقين في جنس الألم ويمنع توهم اختصاص المؤمنين به","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص710، تحت «بلاغة ذكر المسند ﴿يألمون﴾».","url":""}]},{"id":"s4-240","number":240,"surah":4,"verses":[104],"references":[{"surah":4,"verses":[104]}],"verseLabel":"النساء: 104","question":"ما سرّ التعبير في قوله تعالى: ﴿وترجون من الله ما لا يرجون﴾ ولم يذكر الشيء المرجو؟","answer":"أبهم المرجو بـ﴿مَا﴾ ليشمل النصر والأجر والشهادة والرضوان وكل ما عند الله؛ بينما لا يتجاوز رجاء عدوهم غاية الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص710–711، تحت «سر حذف متعلق الفعل ﴿وترجون﴾».","url":""}]},{"id":"s4-241","number":241,"surah":4,"verses":[104],"references":[{"surah":4,"verses":[104]}],"verseLabel":"النساء: 104","question":"لماذا خُتمت الآية بـ﴿وكان الله عليمًا حكيمًا﴾ بعد الحديث عن المطاردة والألم والرجاء؟","answer":"﴿عَلِيمًا﴾ يناسب علم الله بآلامهم ونياتهم ورجائهم، و﴿حَكِيمًا﴾ يناسب ما شرعه من المطاردة والجهاد وما رتبه عليه من مصالح وجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص711، تحت «بلاغة الإطناب بالتذييل في قوله: ﴿وكان الله عليمًا حكيمًا﴾».","url":""}]},{"id":"s4-242","number":242,"surah":4,"verses":[105],"references":[{"surah":4,"verses":[105]}],"verseLabel":"النساء: 105","question":"ما سرّ تقديم ﴿إليك﴾ في قوله: ﴿إنا أنزلنا إليك الكتاب بالحق﴾؟","answer":"قدم ﴿إِلَيْكَ﴾ للعناية بمن أنزل عليه الكتاب وإبراز مسؤوليته في الحكم، ثم ذكر الكتاب وملابسته بالحق الذي يجب أن يقضي به.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص715، تحت «سر تقديم الجار والمجرور في قوله: ﴿أنزلنا إليك﴾».","url":""}]},{"id":"s4-243","number":243,"surah":4,"verses":[105],"references":[{"surah":4,"verses":[105]}],"verseLabel":"النساء: 105","question":"كيف وُجّه النهي ﴿ولا تكن للخائنين خصيمًا﴾ إلى النبي ﷺ مع عصمته؟","answer":"في توجيه الخطاب إليه تعليمٌ للأمة، وحثٌّ وتثبيت على اجتناب نصرة الخائن. فالأمر والنهي قد يوجهان إلى من لا يُتصور منه الفعل المذموم لزيادة الحث على لزوم الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص718–719، تحت «دلالة الخطاب والنهي في قوله: ﴿ولا تكن﴾».","url":""}]},{"id":"s4-244","number":244,"surah":4,"verses":[107],"references":[{"surah":4,"verses":[107]}],"verseLabel":"النساء: 107","question":"ما سرّ التعبير في قوله تعالى: ﴿الذين يختانون أنفسهم﴾، وكيف يخون الإنسان نفسه؟","answer":"يخونون أنفسهم لأن وبال الخيانة وعقوبتها راجع إليهم، ولأن المؤمنين كالنفس الواحدة","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص729–730، تحت «بلاغة التعبير في قوله: ﴿يختانون أنفسهم﴾».","url":""}]},{"id":"s4-245","number":245,"surah":4,"verses":[107],"references":[{"surah":4,"verses":[107]}],"verseLabel":"النساء: 107","question":"لماذا عُدّي الجدال بـ﴿عن﴾ في قوله: ﴿ولا تجادل عن الذين يختانون أنفسهم﴾؟","answer":"تعدية «تجادل» بـ«عن» تجعل المجادلة دفاعًا وذبًّا عن الخائنين","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص728، تحت «نكتة تعدية الفعل ﴿ولا تجادل﴾ بحرف الجر ﴿عن﴾».","url":""}]},{"id":"s4-246","number":246,"surah":4,"verses":[108],"references":[{"surah":4,"verses":[108]}],"verseLabel":"النساء: 108","question":"ما سرّ التعبير في قوله تعالى: ﴿يستخفون من الناس﴾، دون أن يقال: من القوم؟","answer":"«الناس» يعم كل من يخشى انكشاف الخيانة لديه، بخلاف «القوم» الأضيق دلالة","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص735، تحت «مناسبة التعبير بالناس دون القوم».","url":""}]},{"id":"s4-247","number":247,"surah":4,"verses":[108],"references":[{"surah":4,"verses":[108]}],"verseLabel":"النساء: 108","question":"لماذا قابل بين استخفائهم من الناس وعدم استخفائهم من الله؟","answer":"المقابلة تفضح تقديم مراقبة الخلق مع أن الله الأحق بالخشية ولا يخفى عليه تبييتهم","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص735–737، تحت «بلاغة الجمع بين الطباق والمشاكلة في قوله: ﴿يستخفون من الناس ولا يستخفون من الله﴾».","url":""}]},{"id":"s4-248","number":248,"surah":4,"verses":[108],"references":[{"surah":4,"verses":[108]}],"verseLabel":"النساء: 108","question":"لماذا عبّر عن تدبيرهم ليلًا بقوله: ﴿إذ يبيّتون ما لا يرضى من القول﴾؟","answer":"«يبيّتون» يدل على تدبير القول ليلًا في خفاء وإحكام، لا مجرد الاستمرار أو التكرار","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص734، 738، تحت «سر التعبير بالفعل ﴿يبيتون﴾».","url":""}]},{"id":"s4-249","number":249,"surah":4,"verses":[108],"references":[{"surah":4,"verses":[108]}],"verseLabel":"النساء: 108","question":"لماذا خُتمت الآية بـ﴿وكان الله بما يعملون محيطًا﴾؟","answer":"«محيطًا» يصور العلم الشامل الذي لا يفوته ظاهر العمل ولا باطن التبييت، ويلائم الاستخفاء","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص738–739، تحت «حسن التذييل في قوله: ﴿وكان الله بما يعملون محيطًا﴾».","url":""}]},{"id":"s4-250","number":250,"surah":4,"verses":[109],"references":[{"surah":4,"verses":[109]}],"verseLabel":"النساء: 109","question":"ما سر التعبير بقوله: ﴿ها أنتم هؤلاء﴾، ولم لم يقل: أنتم جادلتم عنهم؟","answer":"«ها أنتم هؤلاء» تنبيه واستحضار للمخاطبين قبل تقريعهم على المجادلة، مع التفات يوجب المشافهة","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص742–743، تحت «مناسبة تصدير الكلام بـ(ها) التنبيه في قوله: ﴿هأنتم هؤلاء﴾».","url":""}]},{"id":"s4-251","number":251,"surah":4,"verses":[109],"references":[{"surah":4,"verses":[109]}],"verseLabel":"النساء: 109","question":"ما سرّ التعبير في قوله تعالى: ﴿جادلتم عنهم﴾، دون أن يقال: خاصمتم عنهم؟","answer":"الجدال مراجعة الحجة ومحاولة فتل الخصم عنها، فناسب من سخر قدرته على المحاجة للدفاع عن الخائن؛ أما الخصومة فأعم من هذه الصورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص728، 744، تحت «نكتة إيثار المجادلة على المخاصمة».","url":""}]},{"id":"s4-252","number":252,"surah":4,"verses":[109],"references":[{"surah":4,"verses":[109]}],"verseLabel":"النساء: 109","question":"ما سرّ التعبير في قوله تعالى: ﴿فمن يجادل الله عنهم يوم القيامة﴾، مع أن المجادلة إنما تكون بين يدي الله؟","answer":"المعنى: من يقف مدافعًا عنهم في مواجهة حكم الله وحسابه؟ فعديت المجادلة إلى اسم الله لأن حجتهم الباطلة تصادم قضاءه، لا لأن أحدًا يساويه في مجلس خصومة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص745–746، تحت «مجاز الاستفهام في قوله تعالى: ﴿فمن يجادل الله عنهم يوم القيامة﴾».","url":""}]},{"id":"s4-253","number":253,"surah":4,"verses":[109],"references":[{"surah":4,"verses":[109]}],"verseLabel":"النساء: 109","question":"ما سرّ التعبير في قوله تعالى: ﴿يوم القيامة﴾، دون أن يقال: في الآخرة، في مقابلة ﴿الحياة الدنيا﴾؟","answer":"«يوم القيامة» يحدد يوم قيام الناس للحساب والحكومة بين يدي الله، ويقابل جدالهم في الحياة الدنيا","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص745–746، تحت «نكتة العدول عن المقابل إلى قوله: ﴿يوم القيامة﴾».","url":""}]},{"id":"s4-254","number":254,"surah":4,"verses":[109],"references":[{"surah":4,"verses":[109]}],"verseLabel":"النساء: 109","question":"ما سرّ التعبير في قوله تعالى في مقام التوبيخ: ﴿هَا أَنْتُمْ هَؤُلَاءِ جَادَلْتُمْ﴾، بينما يأتي في مقام التوجيه والمدح: ﴿هَا أَنْتُمْ أُولَاءِ﴾؟","answer":"﴿هؤلاء﴾ أكمل في التنبيه وأشد حضورًا، فناسب مقام التوبيخ على الجدال عن الخائنين؛ أما ﴿أولاء﴾ الأخف فترد حيث لا يحتاج المقام إلى هذا التشديد في التنبيه.","sources":[{"label":"*مختصر لمسات بيانية*؛ منقول في Quranpedia، ملاحظة 44101","url":""}]},{"id":"s4-255","number":255,"surah":4,"verses":[110],"references":[{"surah":4,"verses":[110]}],"verseLabel":"النساء: 110","question":"ما سرّ التعبير في قوله تعالى: ﴿ومن يعمل سوءًا أو يظلم نفسه﴾؛ أليس عمل السوء ظلمًا للنفس؟","answer":"عمل السوء يتناول فعلًا قبيحًا قد يتعدى ضرره إلى غير صاحبه، وظلم النفس يبرز ما يجنيه المرء على نفسه بكل معصية؛ فـ﴿أَوْ﴾ تنوع صور الذنب مع فتح باب الاستغفار للجميع.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص751–752، تحت «نكتة العطف في قوله: ﴿ومن يعمل سوءًا أو يظلم نفسه ثم يستغفر الله يجد الله غفورًا رحيمًا﴾».","url":""}]},{"id":"s4-256","number":256,"surah":4,"verses":[110],"references":[{"surah":4,"verses":[110]}],"verseLabel":"النساء: 110","question":"ما سرّ تقديم عمل السوء على ظلم النفس؟","answer":"قدم عمل السوء لأنه المتعدي إلى الغير والأسبق في السياق، ثم أتبع بظلم النفس ليعم القاصر","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص752، تحت «مناسبة تقديم ﴿يعمل سوءًا﴾ على ﴿يظلم نفسه﴾».","url":""}]},{"id":"s4-257","number":257,"surah":4,"verses":[110],"references":[{"surah":4,"verses":[110]}],"verseLabel":"النساء: 110","question":"ما سرّ التعبير في قوله تعالى: ﴿يجد الله غفورًا رحيمًا﴾، دون أن يقال: يجد مغفرة الله ورحمته؟","answer":"«يجد الله غفورًا رحيمًا» يصور تحقق أثر الصفات في معاملة التائب وقربه، لا مجرد العثور على المغفرة","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص753، تحت «بلاغة الاستعارة في قوله تعالى: ﴿يجد الله غفورًا رحيمًا﴾».","url":""}]},{"id":"s4-258","number":258,"surah":4,"verses":[111],"references":[{"surah":4,"verses":[111]}],"verseLabel":"النساء: 111","question":"لماذا جاء القصر بـ﴿فإنما يكسبه على نفسه﴾؟","answer":"القصر بـ«إنما» يحصر وبال الإثم وكسبه في صاحبه فلا يضر الله ولا يحمل تبعته غيره","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص758–759، تحت «براعة القصر بـ(إنما) في قوله تعالى: ﴿فإنما يكسبه على نفسه﴾».","url":""}]},{"id":"s4-259","number":259,"surah":4,"verses":[112],"references":[{"surah":4,"verses":[112]}],"verseLabel":"النساء: 112","question":"لماذا جمع بين ﴿خطيئة﴾ و﴿إثمًا﴾، وعطف بينهما بـ﴿أو﴾؟","answer":"من وجوه التفريق أن الخطيئة ما وقع من غير عمد والإثم ما وقع عمدًا؛ وقيل: الخطيئة ما اقتصر ضرره على صاحبه والإثم ما تعداه. وجاءت «أو» لاستيعاب وقوع أي واحد من المذكورين في سياق الشرط.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص764، تحت «مناسبة العطف بـ(أو) في قوله: ﴿خطيئة أو إثمًا﴾».","url":""}]},{"id":"s4-260","number":260,"surah":4,"verses":[112],"references":[{"surah":4,"verses":[112]}],"verseLabel":"النساء: 112","question":"لماذا عاد الضمير مفردًا في ﴿ثم يرمِ به بريئًا﴾ بعد ذكر خطيئة وإثم؟","answer":"لأن المذكورين عُطف أحدهما على الآخر بـ«أو» التي تقتضي أحدهما، صح إفراد الضمير. ويجوز عوده إلى الإثم لقربه، أو إلى المصدر المفهوم من «يكسب»، فيشمل ما اكتسبه من الذنب.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص765، تحت «نكتة التعبير بالضمير المفرد في قوله: ﴿ثم يرم به﴾».","url":""}]},{"id":"s4-261","number":261,"surah":4,"verses":[112],"references":[{"surah":4,"verses":[112]}],"verseLabel":"النساء: 112","question":"لماذا صُوّر إلصاق الذنب بالبريء بالرمي: ﴿يرم به بريئًا﴾؟","answer":"استعير الرمي لنسبة الذنب إلى البريء؛ فشبّه إيذاءه بهذه التهمة بإصابته بحجر أو سهم، مبالغة في تصوير ما يلحقه من أذى وبيانًا لجسامة فعل المتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص766، تحت «بلاغة الاستعارة في قوله: ﴿ثم يرم به بريئًا﴾».","url":""}]},{"id":"s4-262","number":262,"surah":4,"verses":[112],"references":[{"surah":4,"verses":[112]}],"verseLabel":"النساء: 112","question":"ما سرّ تقديم ﴿بهتانًا﴾ على ﴿إثمًا مبينًا﴾؟","answer":"قُدم البهتان لأنه الجناية المقابلة لرمي البريء، وهي أشد من مجرد اكتساب الخطيئة أو الإثم الذي سبقها؛ فناسب تقديم الأخطر في تفصيل العقاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص768، تحت «مناسبة تقديم البهتان على الإثم».","url":""}]},{"id":"s4-263","number":263,"surah":4,"verses":[113],"references":[{"surah":4,"verses":[113]}],"verseLabel":"النساء: 113","question":"ما سرّ تقديم فضل الله على رحمته في ﴿ولولا فضل الله عليك ورحمته﴾؟","answer":"الفضل أثر الرحمة؛ فلولا رحمة الله ما تفضل على أحد، ولذلك قدم الفضل الظاهر وذكر أصله الرحمة بعده","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص772، تحت «نكتة تقديم الفضل على الرحمة».","url":""}]},{"id":"s4-264","number":264,"surah":4,"verses":[113],"references":[{"surah":4,"verses":[113]}],"verseLabel":"النساء: 113","question":"ما سرّ التعبير بقوله تعالى: ﴿همت طائفة منهم أن يضلوك﴾ ثم قُصر ضررهم على أنفسهم: ﴿وما يضلون إلا أنفسهم﴾؟","answer":"همّهم متجه إلى تضليل الرسول، لكن الله عصمه؛ فلم يقع ضرر سعيهم إلا عليهم بما اكتسبوا من إثم وافتضاح، فالقصر يقلب مكرهم إلى أصحابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص773–775، تحت «بلاغة القصر في قوله: ﴿وما يضلون إلا أنفسهم﴾».","url":""}]},{"id":"s4-265","number":265,"surah":4,"verses":[113],"references":[{"surah":4,"verses":[113]}],"verseLabel":"النساء: 113","question":"لماذا رُتب الامتنان: ﴿أنزل الله عليك الكتاب والحكمة وعلمك ما لم تكن تعلم﴾ بهذا النسق؟","answer":"رتب الامتنان من إنزال أصل الوحي «الكتاب»، إلى بيانه العملي «الحكمة»، ثم التعليم الأوسع لما لم يكن يعلمه","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص777–778، تحت «مناسبة الترتيب في الامتنان».","url":""}]},{"id":"s4-266","number":266,"surah":4,"verses":[113],"references":[{"surah":4,"verses":[113]}],"verseLabel":"النساء: 113","question":"لماذا خُتم السياق بقوله: ﴿وكان فضل الله عليك عظيمًا﴾ بعد نفي إضرارهم بالنبي ﷺ؟","answer":"الخاتمة تجمع عصمته وإنزال الكتاب والحكمة وتعليمه، فتقرر أن هذا الفضل الخاص المتعدد عظيم","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص778–779، تحت «حسن التذييل في قوله: ﴿وكان فضل الله عليك عظيمًا﴾».","url":""}]},{"id":"s4-267","number":267,"surah":4,"verses":[114],"references":[{"surah":4,"verses":[114]}],"verseLabel":"النساء: 114","question":"ما سرّ التعبير في قوله تعالى: ﴿لا خير في كثير من نجواهم﴾، دون أن يقال: في نجواهم شر؟","answer":"عدل عن التصريح بالشر إلى نفي الخير تلطّفًا في العبارة وكناية عن عدم الاعتداد بكثير من نجواهم. ونفي الخير أوسع من إثبات الشر؛ فقد يتناول كلامًا لا خير فيه ولا شر، ويستوعب غير النافع من أحاديثهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص783–784، تحت «دلالة الكناية في قوله: ﴿لا خير﴾».","url":""}]},{"id":"s4-268","number":268,"surah":4,"verses":[114],"references":[{"surah":4,"verses":[114]}],"verseLabel":"النساء: 114","question":"ما سرّ التعبير في قوله تعالى: ﴿في كثير من نجواهم﴾ ولم ينف الخير عن النجوى كلها؟","answer":"قيد النفي بـ«كثير» لأن بعض النجوى خير، وهو ما فُصل في الاستثناء من الصدقة والمعروف والإصلاح","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص783–785، تحت «سر اختيار لفظ ﴿كثير﴾ دون غيره».","url":""}]},{"id":"s4-269","number":269,"surah":4,"verses":[114],"references":[{"surah":4,"verses":[114]}],"verseLabel":"النساء: 114","question":"لماذا خُصت النجوى بالذكر دون سائر كلامهم؟","answer":"لأن الأصل في المحادثة الصراحة والجهر، أما إخفاؤها من غير حاجة فيجعلها مظنة حديث يُستحيا من إظهاره؛ فجاءت الآية لتقويم هذا السلوك، مع استثناء النجوى النافعة بالصدقة والمعروف والإصلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص785، تحت «دلالة إضافة الضمير إلى النجوى في قوله: ﴿نجواهم﴾».","url":""}]},{"id":"s4-270","number":270,"surah":4,"verses":[114],"references":[{"surah":4,"verses":[114]}],"verseLabel":"النساء: 114","question":"لماذا رُتبت المستثنيات: ﴿بصدقة أو معروف أو إصلاح بين الناس﴾ بهذا الترتيب؟","answer":"الترتيب ينتقل من خاص مالي «صدقة»، إلى عام يشمل وجوه الخير «معروف»، ثم إلى خاص عظيم الأثر «إصلاح بين الناس»","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص789–790، تحت «التناوب في اقتراح أفعال الخير كبيرها وصغيرها، من الدعوة إلى إصلاح العقول والقلوب».","url":""}]},{"id":"s4-271","number":271,"surah":4,"verses":[114],"references":[{"surah":4,"verses":[114]}],"verseLabel":"النساء: 114","question":"ما دلالة الانتقال من قوله تعالى: ﴿إِلَّا مَنْ أَمَرَ﴾ إلى قوله: ﴿وَمَنْ يَفْعَلْ ذَلِكَ﴾؟","answer":"﴿أَمَرَ﴾ يدخل فيه الدال على الخير والداعي إليه وإن لم يباشره، ثم جاء ﴿يَفْعَلْ﴾ عند الوعد ليشمل تنفيذ هذه الخيرات وتحقيقها؛ فانتقل من التوجيه إلى الأثر العملي.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص794–795، تحت «وجه الالتفات الفعلي بين ﴿أمر﴾ و﴿يفعل﴾».","url":""}]},{"id":"s4-272","number":272,"surah":4,"verses":[114],"references":[{"surah":4,"verses":[114]}],"verseLabel":"النساء: 114","question":"ما سرّ التعبير في قوله تعالى: ﴿ابتغاء مرضات الله﴾، ثم عبّر عن الجزاء بـ﴿فسوف نؤتيه﴾؟","answer":"قيد العمل بابتغاء مرضاة الله لأن النية روح استحقاق الأجر، ثم جاء «نؤتيه» بنون العظمة لتعظيم العطاء واستحضار المعطي","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص795–797، تحت «بلاغة الالتفات في القراءات».","url":""}]},{"id":"s4-273","number":273,"surah":4,"verses":[115],"references":[{"surah":4,"verses":[115]}],"verseLabel":"النساء: 115","question":"ما سرّ التعبير في قوله تعالى: ﴿ومن يشاقق الرسول﴾ بصيغة المضارع؟","answer":"المضارع في ﴿ومن يشاقق الرسول﴾ يستحضر الفعل متجددًا أو متكررًا، فيجعل صورته حاضرة ويبين استمرار حكمه أو أثره.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص15، تحت «دلالة التعبير بالفعل المضارع في قوله: ﴿ومن يشاقق﴾».","url":""}]},{"id":"s4-274","number":274,"surah":4,"verses":[115],"references":[{"surah":4,"verses":[115]}],"verseLabel":"النساء: 115","question":"ما سرّ التعبير في قوله تعالى: ﴿من بعد ما تبين له الهدى﴾، دون أن يقال: من بعد ما عرف الحق؟","answer":"«تبيّن» يصور شدة وضوح الحق بعد قيام حجته، و«الهدى» طريق الرشاد الذي ظهر له","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص15–16، تحت «فائدة الإتيان بالفعل ﴿تبين﴾ على وزن تفعل».","url":""}]},{"id":"s4-275","number":275,"surah":4,"verses":[115],"references":[{"surah":4,"verses":[115]}],"verseLabel":"النساء: 115","question":"لماذا جُمع بين مشاقّة الرسول واتباع غير سبيل المؤمنين؟","answer":"مشاقة الرسول رفض مرجعية الوحي، واتباع غير سبيل المؤمنين خروج عن جماعة الحق؛ جمعهما يثبت تلازم المرجع والطريق بعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص17–18، تحت «وجه الجمع بين قوله: ﴿ويتبع غير سبيل المؤمنين﴾ مع مشاقة الرسول».","url":""}]},{"id":"s4-276","number":276,"surah":4,"verses":[115],"references":[{"surah":4,"verses":[115]}],"verseLabel":"النساء: 115","question":"ما سرّ التعبير في قوله تعالى: ﴿غير سبيل المؤمنين﴾، دون أن يقال: غير سبيل الرسول؟","answer":"«سبيل المؤمنين» احتراس يحفظ الجماعة بعد وفاة الرسول ويبين أن مخالفة سبيلهم امتداد لمشاقته، لا معنى لفظيًا عامًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص21–22، تحت «احتراس ثان في قوله: ﴿ويتبع غير سبيل المؤمنين﴾».","url":""}]},{"id":"s4-277","number":277,"surah":4,"verses":[115],"references":[{"surah":4,"verses":[115]}],"verseLabel":"النساء: 115","question":"ما الصورة في قوله: ﴿نوله ما تولى﴾؟","answer":"التعبير كناية عن خذلانه وتركه لما اختاره وإيكاله إلى نفسه بعد إعراضه، لا مجرد تحويل معنى مجرد إلى صورة محسوسة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص22، تحت «دلالة الكناية في قوله: ﴿نوله ما تولى﴾».","url":""}]},{"id":"s4-278","number":278,"surah":4,"verses":[115],"references":[{"surah":4,"verses":[115]}],"verseLabel":"النساء: 115","question":"لماذا خُتمت الآية بـ﴿وساءت مصيرًا﴾؟","answer":"الخاتمة تحكم على جهنم بأنها أسوأ منتهى وآخر مراحل الانحدار بعد المشاقة والخذلان، فتتم صورة العاقبة","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص23، تحت «فائدة الإطناب في قوله: ﴿وساءت مصيرًا﴾».","url":""}]},{"id":"s4-279","number":279,"surah":4,"verses":[116],"references":[{"surah":4,"verses":[116]}],"verseLabel":"النساء: 116","question":"لماذا تكررت آية ﴿إن الله لا يغفر أن يشرك به﴾ بعد ورودها في الآية 48؟","answer":"آية 48 خاطبت أهل الكتاب فناسب افتراء الإثم، وهنا التحذير للمؤمنين بعد مشاقة الرسول وسبيل المؤمنين فناسب الضلال البعيد","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص28–30، تحت «التشابه بين الآيتين».","url":""}]},{"id":"s4-280","number":280,"surah":4,"verses":[116],"references":[{"surah":4,"verses":[116]}],"verseLabel":"النساء: 116","question":"ما سرّ التعبير في قوله تعالى: ﴿ويغفر ما دون ذلك﴾، دون أن يقال: ما سوى ذلك؟","answer":"«دون» تفيد ما هو أدنى من الشرك مرتبة، وفيها مع التبشير بالمغفرة تبشيع للمعاصي وتنزيل للعاصي عن رتبة الطائع","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص30–31، تحت «دلالة اختيار ﴿دون﴾ في قوله: ﴿ويغفر ما دون ذلك﴾».","url":""}]},{"id":"s4-281","number":281,"surah":4,"verses":[116],"references":[{"surah":4,"verses":[116]}],"verseLabel":"النساء: 116","question":"لماذا عبّر عن الشرك بقوله: ﴿أن يشرك به﴾ بالبناء للمجهول؟","answer":"البناء للمجهول يصرف النظر عن شخص المشرك إلى فظاعة وقوع الشرك بالله أيًّا كان فاعله، ويجعل المحور حق الله الذي اتخذ له شريك.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص31–32، تحت «دلالة الالتفات من المبني لما لم يسم فاعله إلى المبني للمعلوم».","url":""}]},{"id":"s4-282","number":282,"surah":4,"verses":[116],"references":[{"surah":4,"verses":[116]}],"verseLabel":"النساء: 116","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿فقد ضل ضلالًا بعيدًا﴾، وفي الآية 48: ﴿افترى إثمًا عظيمًا﴾؟","answer":"في الآية 48 جاء السياق في الافتراء والتزكية الباطلة، فناسب ﴿افْتَرَى إِثْمًا عَظِيمًا﴾؛ وفي الآية 116 جاء بعد مفارقة طريق الهدى، فناسب ﴿ضَلَّ ضَلَالًا بَعِيدًا﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص28–29، تحت «التشابه بين الآيتين».","url":""}]},{"id":"s4-283","number":283,"surah":4,"verses":[117],"references":[{"surah":4,"verses":[117]}],"verseLabel":"النساء: 117","question":"لماذا عبّر عن العبادة بالدعاء في ﴿إن يدعون من دونه﴾؟","answer":"الدعاء أعم من العبادة، وعبادتهم الأصنام غايتها دعاؤها عند الحاجة؛ فذكر العام مستوعبًا الخاص ومبكتًا عجز المعبود","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص36–37، تحت «سر التعبير عن العبادة بالدعاء في قوله: ﴿يدعون﴾».","url":""}]},{"id":"s4-284","number":284,"surah":4,"verses":[117],"references":[{"surah":4,"verses":[117]}],"verseLabel":"النساء: 117","question":"لماذا سمّى المعبودات الباطلة ﴿إناثًا﴾؟","answer":"سميت الأصنام إناثًا لتأنيث أسمائها ودعواهم أنها بنات الله، ولتصوير نقصها وعجزها وانفعالها واحتياجها للحماية","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص37–38، تحت «الكناية ومعنى التبكيت في قوله: ﴿إلا إناثًا﴾».","url":""}]},{"id":"s4-285","number":285,"surah":4,"verses":[117],"references":[{"surah":4,"verses":[117]}],"verseLabel":"النساء: 117","question":"لماذا كرر ﴿إن يدعون﴾ في الآية نفسها؟","answer":"الدعاء الأول عبادة الأصنام، والثاني طاعة الشيطان الذي أغرى بها؛ فالحصران يكشفان الظاهر وأصله الحقيقي، لا مجرد تكرار للتنبيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص39–40، تحت «وجه تكرار أسلوب الحصر مرتين في ﴿إن يدعون﴾».","url":""}]},{"id":"s4-286","number":286,"surah":4,"verses":[117],"references":[{"surah":4,"verses":[117]}],"verseLabel":"النساء: 117","question":"لماذا أُخر ذكر الشيطان بعد ذكر الإناث: ﴿وإن يدعون إلا شيطانًا مريدًا﴾؟","answer":"أُخر الشيطان لأن عبادته وطاعته هي الأصل الذي أغراهم بعبادة الأصنام، فانتقل من المظهر إلى المحرك الحقيقي","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص39، تحت «علة تأخر ذكر الشيطان وعبادته عن عبادة الأصنام».","url":""}]},{"id":"s4-287","number":287,"surah":4,"verses":[118],"references":[{"surah":4,"verses":[118]}],"verseLabel":"النساء: 118","question":"ما دلالة قول إبليس: ﴿لَأَتَّخِذَنَّ مِنْ عِبَادِكَ نَصِيبًا مَفْرُوضًا﴾؟","answer":"النصيب حصة من العباد يسعى الشيطان إلى إغوائها، ووصفه بالمفروض أي المقطوع المعين؛ ففي كلامه إظهار عزمه على اتخاذ هذا النصيب وإضلاله.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص47–48، تحت «وجه وصف النصيب بقوله: ﴿مفروضًا﴾».","url":""}]},{"id":"s4-288","number":288,"surah":4,"verses":[118],"references":[{"surah":4,"verses":[118]}],"verseLabel":"النساء: 118","question":"لماذا اختار فعل ﴿لأتخذن﴾ بدل لأضلّن عددًا من عبادك؟","answer":"«لأتخذن» يصور استيلاء الشيطان عليهم وجعلهم حصة خاصة وأتباعًا له، وهو أبلغ من مجرد وقوع الإضلال في عدد منهم","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص47، تحت «دلالة التعبير بالفعل ﴿لأتخذن﴾».","url":""}]},{"id":"s4-289","number":289,"surah":4,"verses":[119],"references":[{"surah":4,"verses":[119]}],"verseLabel":"النساء: 119","question":"لماذا كرر إبليس ﴿ولآمرنهم﴾ في تعداد خطوات الإضلال؟","answer":"تكرر «ولآمرنهم» للفصل والتوكيد بين أمرين لهما أثران: تبتيك الآذان وتغيير خلق الله، وإبراز تسلط الأمر الشيطاني","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص56، تحت «دلالة تكرار قوله: ﴿ولآمرنهم﴾».","url":""}]},{"id":"s4-290","number":290,"surah":4,"verses":[119],"references":[{"surah":4,"verses":[119]}],"verseLabel":"النساء: 119","question":"لماذا خُصّ تبتيك آذان الأنعام بالذكر قبل تغيير خلق الله؟","answer":"قدم تبتيك الآذان مثالًا خاصًا مشهورًا من فعل الجاهلية ثم رقّي إلى عموم تغيير خلق الله، مع التنبيه على شناعة الخاص","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص54–55، تحت «دلالة ذكر العام بعد الخاص».","url":""}]},{"id":"s4-291","number":291,"surah":4,"verses":[119],"references":[{"surah":4,"verses":[119]}],"verseLabel":"النساء: 119","question":"ما سرّ التعبير في قوله تعالى: ﴿فليغيرن خلق الله﴾، دون أن يقال: فطرة الله؟","answer":"«خلق الله» أوسع من الفطرة، فيشمل تغيير الدين والهيئة التي خلقها الله والتصرفات الداخلة فيهما","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص57، تحت «دلالة اختيار التعبير ﴿خلق الله﴾ دون فطرة الله».","url":""}]},{"id":"s4-292","number":292,"surah":4,"verses":[119],"references":[{"surah":4,"verses":[119]}],"verseLabel":"النساء: 119","question":"ما دلالة الحذف في قوله تعالى: ﴿ولآمرنهم فليبتكن آذان الأنعام﴾؟","answer":"حُذف متعلق الأمر لدلالة ما بعده عليه؛ فالتقدير: لآمرنهم بالتبتيك فليبتكن. وفي تعقيب الأمر بفعله تصوير لسرعة استجابتهم لإغواء الشيطان.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص56، تحت «دلالة حذف مفعول الفعل ﴿ولآمرنهم﴾».","url":""}]},{"id":"s4-293","number":293,"surah":4,"verses":[119],"references":[{"surah":4,"verses":[119]}],"verseLabel":"النساء: 119","question":"ما سرّ التعبير في قوله تعالى: ﴿ومن يتخذ الشيطان وليًا من دون الله فقد خسر خسرانًا مبينًا﴾، دون أن يقال: ضل ضلالًا مبينًا؟","answer":"اتخاذ الشيطان وليًا مبادلة لولاية الله تفوّت خير الدنيا والآخرة، فناسب الخسران الذي يعني فقدان رأس المال والنجاة، لا مجرد ضلال الطريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص59–60، تحت «دلالة التعبير بالخسران دون غيره».","url":""}]},{"id":"s4-294","number":294,"surah":4,"verses":[120],"references":[{"surah":4,"verses":[120]}],"verseLabel":"النساء: 120","question":"لماذا جمع بين ﴿يعدهم﴾ و﴿يمنيهم﴾؟","answer":"لا يكتفي الشيطان بالوعد، بل يفتح لهم باب الأماني، فيثير الحرص ويطيل الأمل ويشغل النفس بما تتخيله من محبوب؛ فالتمنية تقوي تعلقهم بما يعدهم به.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص63، تحت «دلالة التعبير بالأماني بعد الوعد في قوله: ﴿يعدهم ويمنيهم﴾».","url":""}]},{"id":"s4-295","number":295,"surah":4,"verses":[120],"references":[{"surah":4,"verses":[120]}],"verseLabel":"النساء: 120","question":"لماذا قصر وعد الشيطان على الغرور: ﴿وما يعدهم الشيطان إلا غرورًا﴾؟","answer":"القصر يبطل حقيقة وعود الشيطان كلها ويحصرها في الزخرف المخادع الذي لا ينجز، فلا يبقى منها وعد صادق","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص64، تحت «بلاغة الاستثناء والحصر في قوله: ﴿وما يعدهم الشيطان إلا غرورًا﴾».","url":""}]},{"id":"s4-296","number":296,"surah":4,"verses":[121],"references":[{"surah":4,"verses":[121]}],"verseLabel":"النساء: 121","question":"ما سرّ التعبير في قوله تعالى عن جهنم: ﴿مأواهم﴾، دون أن يقال: مستقرهم؟","answer":"المأوى موضع يلجأ إليه للسكينة والراحة، وفي وصف جهنم به تهكم ومفارقة؛ كلما طلبوا مأوى وجدوا فيه أشد العذاب، بخلاف «مستقر».","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص67، تحت «التعبير بقوله: ﴿مأواهم﴾ دون (مستقرهم أو مقامهم)».","url":""}]},{"id":"s4-297","number":297,"surah":4,"verses":[122],"references":[{"surah":4,"verses":[122]}],"verseLabel":"النساء: 122","question":"لماذا قُرن الإيمان بالعمل الصالح مرة أخرى قبل وعد الجنة؟","answer":"الإيمان أصل باطن يحدد الوجهة، والعمل الصالح برهانه وثمرته؛ فاقترانهما يمنع الاتكال على الدعوى المجردة أو العمل المنفصل عن الإيمان قبل وعد الجنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص71–72، تحت «إيجاز الحذف في قوله: ﴿والذين آمنوا وعملوا الصالحات﴾».","url":""}]},{"id":"s4-298","number":298,"surah":4,"verses":[122],"references":[{"surah":4,"verses":[122]}],"verseLabel":"النساء: 122","question":"لماذا جُمعت الجنات في ﴿سندخلهم جنات﴾ ونُكّرت؟","answer":"جمع «جنات» لتعددها وتنوع مراتبها ونعيمها، ونُكرت للتعظيم","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص74، تحت «سر التنكير والجمع لقوله: ﴿جنات﴾».","url":""}]},{"id":"s4-299","number":299,"surah":4,"verses":[122],"references":[{"surah":4,"verses":[122]}],"verseLabel":"النساء: 122","question":"ما سرّ التعبير في قوله تعالى في النساء: ﴿وَعْدَ اللَّهِ حَقًّا﴾، بينما تنوع التعبير في مواضع أخرى إلى ﴿وَعْدَهُ مَأْتِيًّا﴾ و﴿وَعْدَ الصِّدْقِ﴾ و﴿لَا يُخْلِفُ اللَّهُ الْمِيعَادَ﴾؟","answer":"«حقًا» مصدر مؤكد يثبت الوعد وينفي عنه الوهم بعد ذكر أماني الشيطان وأماني أهل الكتاب","sources":[{"label":"فاضل السامرائي، *قبسات من البيان القرآني*، ص268–271؛ منقول في Quranpedia، ملاحظة 49250","url":""}]},{"id":"s4-300","number":300,"surah":4,"verses":[123],"references":[{"surah":4,"verses":[123]}],"verseLabel":"النساء: 123","question":"ما سرّ افتتاح الحكم بقوله تعالى: ﴿ليس بأمانيكم ولا أماني أهل الكتاب﴾؟","answer":"افتتح بنفي الأماني لأن النجاة والثواب لا ينالان بمجرد الدعوى والتمني، بل بالإيمان والعمل، فجاء الحكم قاطعًا لوهم الفريقين","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص80، 82–84، تحت «بلاغة الاستئناف الابتدائي».","url":""}]},{"id":"s4-301","number":301,"surah":4,"verses":[123],"references":[{"surah":4,"verses":[123]}],"verseLabel":"النساء: 123","question":"لماذا لم يُذكر الجزاء صراحة في ﴿ليس بأمانيكم ولا أماني أهل الكتاب﴾، ثم قيل ﴿من يعمل سوءًا يُجز به﴾؟","answer":"على تفسير الضمير بالجزاء، أُضمر أولًا ثم بيّنته الجملة التالية؛ فيتوجه الاهتمام إلى نفي تعلقه بالأماني، ثم يأتي بيانه مرتبطًا بالعمل. وهذا إبهام يتلوه بيان يقوّي المعنى في النفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص82–83، تحت عنوان «بلاغة الاستئناف الابتدائي»","url":""}]},{"id":"s4-302","number":302,"surah":4,"verses":[123],"references":[{"surah":4,"verses":[123]}],"verseLabel":"النساء: 123","question":"ما دلالة الجمع بين الولي والنصير في قوله تعالى: ﴿ولا يجد له من دون الله وليًا ولا نصيرًا﴾؟","answer":"الولي يتولى أمره ويدفع عنه بالنصرة، والنصير يعينه عند وقوع الضر؛ جمعهما ينفي أصل الحماية والمعونة من دون الله، لا مجرد الترادف العام.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص87–88، تحت «التناسب في قوله: ﴿وليًا ولا نصيرًا﴾».","url":""}]},{"id":"s4-303","number":303,"surah":4,"verses":[124],"references":[{"surah":4,"verses":[124]}],"verseLabel":"النساء: 124","question":"ما سرّ التعبير بقوله تعالى: ﴿ومن يعمل من الصالحات﴾، دون: ومن يعمل الصالحات؟","answer":"«من» تبعيضية: لا يطيق الإنسان استيعاب الصالحات كلها، فعلق الجزاء بما يعمل منها، وفي ذلك تيسير وحث","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص93، تحت «دلالة (من) في موضعيها في الآية الكريمة».","url":""}]},{"id":"s4-304","number":304,"surah":4,"verses":[124],"references":[{"surah":4,"verses":[124]}],"verseLabel":"النساء: 124","question":"ما دلالة التصريح بقوله تعالى: ﴿من ذكر أو أنثى﴾ مع أن اسم الشرط ﴿من﴾ يشملهما؟","answer":"صُرّح بالذكر والأنثى لرفع توهم اختصاص الوعد بأحدهما وتقرير تساويهما في أصل الجزاء، مع أن «من» تشمل الجنسين","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص95–96، تحت «دلالة الطباق في قوله: ﴿من ذكر أو أنثى﴾».","url":""}]},{"id":"s4-305","number":305,"surah":4,"verses":[124],"references":[{"surah":4,"verses":[124]}],"verseLabel":"النساء: 124","question":"ما دلالة القيد ﴿وهو مؤمن﴾ بعد العمل الصالح؟","answer":"الإيمان شرط قبول العمل واستحقاق ثوابه، فقيد العمل الصالح به حتى لا يوهم أن صورته وحدها كافية","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص95–96، تحت «الحمل على اللفظ في قوله: ﴿وهو مؤمن﴾».","url":""}]},{"id":"s4-306","number":306,"surah":4,"verses":[124],"references":[{"surah":4,"verses":[124]}],"verseLabel":"النساء: 124","question":"ما سرّ ضرب المثل بالنقير في قوله تعالى: ﴿ولا يظلمون نقيرًا﴾؟","answer":"«النقير» نقرة صغيرة في نواة التمر تضرب مثلًا لأدنى شيء","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص98، 100، تحت «بلاغة الاستعارة في قوله: ﴿نقيرًا﴾».","url":""}]},{"id":"s4-308","number":308,"surah":4,"verses":[125],"references":[{"surah":4,"verses":[125]}],"verseLabel":"النساء: 125","question":"ما دلالة الاستفهام في قوله تعالى: ﴿ومن أحسن دينًا ممن أسلم وجهه لله﴾؟","answer":"الاستفهام إنكاري يفيد نفي أن يكون أحد أحسن دينًا ممن جمع إخلاص الوجه لله والإحسان واتباع ملة إبراهيم؛ فيحمل السامع على الإقرار بهذه الحقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص106، تحت «الاستفهام الإنكاري في قوله: ﴿ومن أحسن دينًا﴾».","url":""}]},{"id":"s4-309","number":309,"surah":4,"verses":[125],"references":[{"surah":4,"verses":[125]}],"verseLabel":"النساء: 125","question":"ما الصورة في قوله تعالى: ﴿أسلم وجهه لله﴾، وما دلالة تخصيص الوجه؟","answer":"«أسلم وجهه لله» كناية عن تسليم الذات والقصد كله لله؛ وخص الوجه لأنه أشرف الأعضاء وأظهرها ودال على التوجه، لا لمجرد صنع صورة حسية.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص106–107، تحت «الكناية في قوله: ﴿أسلم وجهه﴾».","url":""}]},{"id":"s4-310","number":310,"surah":4,"verses":[125],"references":[{"surah":4,"verses":[125]}],"verseLabel":"النساء: 125","question":"ما دلالة الجمع بين ﴿أسلم وجهه لله﴾ و﴿وهو محسن﴾؟","answer":"جمع بين إخلاص التوجه لله في «أسلم وجهه» وإحسان العمل وموافقته في «وهو محسن»، فاجتمع إخلاص القصد وصواب الفعل","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص105، 108، تحت «الإيجاز بالقصر في الآية الكريمة».","url":""}]},{"id":"s4-311","number":311,"surah":4,"verses":[125],"references":[{"surah":4,"verses":[125]}],"verseLabel":"النساء: 125","question":"ما سرّ وصف اتباع ملة إبراهيم بقوله تعالى: ﴿حنيفًا﴾؟","answer":"«حنيفًا» لا يقتصر على الاستقامة؛ بل يدل على الميل المتعمد عن الشرك والباطل إلى التوحيد والحق، وفيه معنى المفارقة الذي لا تؤديه «مستقيمًا» وحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص103، 108–109، تحت «العدول عن (مستقيمًا) إلى ﴿حنيفًا﴾».","url":""}]},{"id":"s4-312","number":312,"surah":4,"verses":[125],"references":[{"surah":4,"verses":[125]}],"verseLabel":"النساء: 125","question":"ما مناسبة ختم الثناء بقوله تعالى: ﴿واتخذ الله إبراهيم خليلًا﴾؟","answer":"الخلة أخص المحبة التي تتخلل النفس، وفي ذكرها غاية تشريف إبراهيم بعد بيان اتباع ملته، مع بقاء معنى عبوديته لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص104، 110–111، تحت «مناسبة التذييل في الآية الكريمة».","url":""}]},{"id":"s4-313","number":313,"surah":4,"verses":[126],"references":[{"surah":4,"verses":[126]}],"verseLabel":"النساء: 126","question":"ما دلالة ﴿ما﴾ في قوله تعالى: ﴿ولله ما في السماوات وما في الأرض﴾؟","answer":"«ما» تستوعب ما في السماوات والأرض من الموجودات، وغلب استعمالها في غير العقلاء، فجاء اللفظ شاملًا للملك كله","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص113–114، تحت «سر التعبير بـ(ما) في قوله تعالى: ﴿ولله ما في السماوات وما في الأرض﴾».","url":""}]},{"id":"s4-314","number":314,"surah":4,"verses":[126],"references":[{"surah":4,"verses":[126]}],"verseLabel":"النساء: 126","question":"ما مناسبة قوله تعالى: ﴿وكان الله بكل شيء محيطًا﴾ بعد تقرير ملكه للسماوات والأرض؟","answer":"بعد إثبات الملك العام ختم بالإحاطة لإثبات شمول علم الله وقدرته وتدبيره، وأن شيئًا من ملكه لا يخرج عنه","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص115، تحت «التذييل في قوله: ﴿وكان الله بكل شيء محيطًا﴾».","url":""}]},{"id":"s4-315","number":315,"surah":4,"verses":[127],"references":[{"surah":4,"verses":[127]}],"verseLabel":"النساء: 127","question":"ما سرّ تكرار مادة الفتوى والتصريح باسم الله في قوله تعالى: ﴿ويستفتونك في النساء قل الله يفتيكم فيهن﴾؟","answer":"إعادة مادة الفتوى في الجواب تطابق طلبهم وتبين أن المبين هو الحكم المطلوب، والتصريح باسم الله يعظم مصدره ويقطع تبعيته للعرف","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص120–121، تحت «تقديم المسند إليه في قوله: ﴿قل الله يفتيكم فيهن﴾».","url":""}]},{"id":"s4-316","number":316,"surah":4,"verses":[127],"references":[{"surah":4,"verses":[127]}],"verseLabel":"النساء: 127","question":"ما موقع قوله تعالى: ﴿وما يتلى عليكم في الكتاب﴾ من جواب الاستفتاء؟","answer":"«وما يتلى عليكم» معطوف على اسم الله في «الله يفتيكم»، أي يفتيكم الله ويفتيكم أيضًا ما يتلى في الكتاب من الأحكام السابقة","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص121–122، تحت «دلالات إعراب (وما) في قوله تعالى: ﴿وما يتلى عليكم في الكتاب﴾».","url":""}]},{"id":"s4-317","number":317,"surah":4,"verses":[127],"references":[{"surah":4,"verses":[127]}],"verseLabel":"النساء: 127","question":"ما سرّ حذف حرف الجر في قوله تعالى: ﴿وترغبون أن تنكحوهن﴾؛ أهو رغبة فيهن أم رغبة عنهن؟","answer":"حذف حرف الجر يحتمل الرغبة في نكاح اليتيمة لجمالها ومالها، والرغبة عن نكاحها لقلة مالها أو جمالها؛ فجمعت العبارة الحالين، وفي الإبهام ستر على اليتيمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص124–125، تحت «بلاغة إيجاز الحذف في قوله: ﴿وترغبون أن تنكحوهن﴾».","url":""}]},{"id":"s4-318","number":318,"surah":4,"verses":[127],"references":[{"surah":4,"verses":[127]}],"verseLabel":"النساء: 127","question":"ما سرّ التعبير بقوله تعالى: ﴿وأن تقوموا لليتامى بالقسط﴾، دون: وأن تقسطوا في اليتامى؟","answer":"«تقوموا لليتامى بالقسط» يصور ملازمة رعاية حقوقهم وإظهار العدل لهم حتى يعرفوا استيفاءها، ويربط القسط بالقيام المستمر","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص125–126، 129، تحت «الاستعارة في قوله: ﴿وأن تقوموا﴾».","url":""}]},{"id":"s4-319","number":319,"surah":4,"verses":[127],"references":[{"surah":4,"verses":[127]}],"verseLabel":"النساء: 127","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿فإن الله كان به عليمًا﴾؟","answer":"عمّم قوله ﴿مِنْ خَيْرٍ﴾ كل إحسان إلى الضعفاء، ثم أكد أن الله يعلمه؛ ترغيبًا في الخير الخفي والظاهر وضمانًا لعدم ضياع جزائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص126–127، تحت «دلالة الاقتصار على فعل الخير في قوله: ﴿وما تفعلوا من خير فإن الله كان به عليمًا﴾».","url":""}]},{"id":"s4-320","number":320,"surah":4,"verses":[128],"references":[{"surah":4,"verses":[128]}],"verseLabel":"النساء: 128","question":"ما سرّ التعبير بقوله تعالى: ﴿من بعلها﴾، دون: من زوجها؟","answer":"«البعل» يلحظ قوة الرجل وقيامه على المرأة وتهيؤه للمعاشرة، فيناسب نشوزه الذي يعطل رابطة الزوجية، بخلاف «الزوج» الأعم في مطلق الاقتران","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص133، 140–141، تحت «سر التعبير بـ(البعل) بدل الزوج».","url":""}]},{"id":"s4-321","number":321,"surah":4,"verses":[128],"references":[{"surah":4,"verses":[128]}],"verseLabel":"النساء: 128","question":"ما دلالة ترتيب ﴿نشوزًا أو إعراضًا﴾؟","answer":"النشوز ترفع واستعلاء تظهر آثاره في المعاملة، والإعراض انصراف عنها وترك لمؤانستها؛ فجمع التعبير الصورتين اللتين تخشى المرأة وقوعهما من زوجها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص130–131، 134، تحت «مناسبة العطف بين النشوز والإعراض في قوله: ﴿وإن امرأة خافت من بعلها نشوزًا أو إعراضًا﴾».","url":""}]},{"id":"s4-322","number":322,"surah":4,"verses":[128],"references":[{"surah":4,"verses":[128]}],"verseLabel":"النساء: 128","question":"ما سرّ نفي الجناح في قوله تعالى: ﴿فلا جناح عليهما أن يصلحا بينهما صلحًا﴾ مع أن الصلح مطلوب؟","answer":"نفي الجناح يرفع توهم الإثم في تنازل أحد الزوجين عن بعض حقه طلبًا لبقاء العشرة، ويقرر أن هذا ليس رشوة ولا ظلمًا","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص135، 141، تحت «نكتة النفي بلا النافية للجنس في قوله: ﴿فلا جناح﴾».","url":""}]},{"id":"s4-323","number":323,"surah":4,"verses":[128],"references":[{"surah":4,"verses":[128]}],"verseLabel":"النساء: 128","question":"ما دلالة مجيء قوله تعالى: ﴿والصلح خير﴾ جملة اعتراضية مطلقة؟","answer":"أكد الاعتراض الترغيب في المصالحة، وجاءت الجملة اسمية لتثبيت خيريتها. وإطلاقها يجعلها كالمثل العام: كل صلح مشروع يزيل الخصومة خير.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص136–137، تحت «براعة الإطناب بالاعتراض في قوله: ﴿والصلح خير﴾».","url":""}]},{"id":"s4-324","number":324,"surah":4,"verses":[128],"references":[{"surah":4,"verses":[128]}],"verseLabel":"النساء: 128","question":"ما الصورة في قوله تعالى: ﴿وأحضرت الأنفس الشح﴾؟","answer":"صوّر الشح كأنه شيء أُحضر عند النفس ولزمها، للدلالة على تمكنه منها واستعداده للحضور عند قسمة الحقوق؛ وفي ذلك تنبيه للزوجين إلى مجاهدة هذا الطبع.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص138، تحت «براعة الإطناب بالاعتراض في قوله: ﴿وأحضرت الأنفس الشح﴾».","url":""}]},{"id":"s4-325","number":325,"surah":4,"verses":[128,129],"references":[{"surah":4,"verses":[128,129]}],"verseLabel":"النساء: 128؛ 129","question":"ما سرّ اختلاف الخاتمة بين قوله تعالى: ﴿وَإِنْ تُحْسِنُوا وَتَتَّقُوا... خَبِيرًا﴾، وقوله: ﴿وَإِنْ تُصْلِحُوا وَتَتَّقُوا... غَفُورًا رَحِيمًا﴾؟","answer":"الأولى تحث على إحسان العشرة، وخفايا الإحسان يعلمها الخبير. والثانية تعالج تقصيرًا في العدل يحتاج إلى إصلاح، فناسبها الوعد بالمغفرة والرحمة لمن أصلح واتقى.","sources":[{"label":"ابن جماعة، كشف المعاني في المتشابه من المثاني، ص141؛ إسلام ويب، باب النساء: 128–129","url":""}]},{"id":"s4-326","number":326,"surah":4,"verses":[129],"references":[{"surah":4,"verses":[129]}],"verseLabel":"النساء: 129","question":"كيف يُفهم قوله تعالى: ﴿ولن تستطيعوا أن تعدلوا بين النساء﴾ مع الأمر بالعدل؟","answer":"المنفي هو تمام التسوية في ميل القلب والمحبة، وهو غير مقدور، أما العدل الواجب في القسم والنفقة والمعاملة فمقدور ومأمور به","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص144–146، تحت «نكتة التعبير بنفي الاستطاعة في قوله تعالى: ﴿ولن تستطيعوا أن تعدلوا﴾».","url":""}]},{"id":"s4-327","number":327,"surah":4,"verses":[129],"references":[{"surah":4,"verses":[129]}],"verseLabel":"النساء: 129","question":"ما دلالة زيادة قوله تعالى: ﴿ولو حرصتم﴾ بعد نفي استطاعة العدل التام؟","answer":"يدخل قوله ﴿ولو حرصتم﴾ أشد أحوال السعي والاجتهاد في نفي استطاعة العدل التام؛ فالتسوية في ميل القلب لا تتحقق ولو بلغ الحرص غايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص145–146، تحت «براعة التعبير بـ﴿ولو حرصتم﴾».","url":""}]},{"id":"s4-328","number":328,"surah":4,"verses":[129],"references":[{"surah":4,"verses":[129]}],"verseLabel":"النساء: 129","question":"ما سرّ النهي عن ﴿كل الميل﴾ دون النهي عن أصل الميل؟","answer":"لم ينه عن أصل الميل لأنه قلبي غير مقدور، وإنما نهى عن استرساله حتى يصير ميلًا كليًا يظهر في الحقوق والمعاملة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص146، تحت عنوان «دلالة النهي الوارد بعد النفي»","url":""}]},{"id":"s4-329","number":329,"surah":4,"verses":[129],"references":[{"surah":4,"verses":[129]}],"verseLabel":"النساء: 129","question":"ما الصورة في قوله تعالى: ﴿فتذروها كالمعلقة﴾؟","answer":"شبه المرأة التي لا تنال حقوق الزوجة ولا تُطلق فتستقل بالمعلقة التي لا تستقر في جهة؛ فالتشبيه يجسم ألم إبقائها بين حالين.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص148، تحت «بلاغة التشبيه في قوله تعالى: ﴿فتذروها كالمعلقة﴾».","url":""}]},{"id":"s4-330","number":330,"surah":4,"verses":[130],"references":[{"surah":4,"verses":[130]}],"verseLabel":"النساء: 130","question":"ما سرّ التعبير بقوله تعالى: ﴿وإن يتفرقا﴾، دون: وإن يتطلقا؟","answer":"«يتفرقا» أعم من خصوص لفظ الطلاق، ويصور انفصال كل واحد عن صاحبه بعد تعذر الصلح، فيقابل اجتماعهما السابق","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص153–154، تحت «دلالة التعبير بلفظ ﴿يتفرقا﴾ بدل (يتطلقا)».","url":""}]},{"id":"s4-331","number":331,"surah":4,"verses":[130],"references":[{"surah":4,"verses":[130]}],"verseLabel":"النساء: 130","question":"ما دلالة قوله تعالى: ﴿يغن الله كلًا من سعته﴾ بعد ذكر افتراق الزوجين؟","answer":"الوعد يبدد خوف الحاجة بعد الفراق: يغني الله كل واحد على حدة من فضل واسع، بعوض أو رزق أو زوج أصلح","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص153، تحت «دلالة الحذف والتنكير في قوله: ﴿يغن الله كلًّا﴾».","url":""}]},{"id":"s4-332","number":332,"surah":4,"verses":[131],"references":[{"surah":4,"verses":[131]}],"verseLabel":"النساء: 131","question":"ما سرّ تكرار قوله تعالى: ﴿ولله ما في السماوات وما في الأرض﴾ في هذا السياق؟","answer":"تكرر إثبات الملك لأن كل موضع يبني عليه غرضًا: سعة إغناء الزوجين، والغنى عن طاعة الخلق، والقدرة على الاستبدال","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص155، 160، 162–166، تحت «نكتة تكرار جملة: ﴿ولله ما في السماوات وما في الأرض﴾».","url":""}]},{"id":"s4-333","number":333,"surah":4,"verses":[131],"references":[{"surah":4,"verses":[131]}],"verseLabel":"النساء: 131","question":"ما سرّ التعبير عن الأمر بالتقوى بقوله تعالى: ﴿ولقد وصينا﴾؟","answer":"«وصينا» تدل على شدة العناية بالتقوى وتأكيد حفظها والعمل بها، ثم قوِّيت باللام و«قد» وعموم الوصية للأمم","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص157–158، تحت «سر التعبير بالوصية بدل الأمر بالتقوى».","url":""}]},{"id":"s4-334","number":334,"surah":4,"verses":[131],"references":[{"surah":4,"verses":[131]}],"verseLabel":"النساء: 131","question":"ما دلالة تقديم الذين أوتوا الكتاب على المخاطبين في الوصية بالتقوى؟","answer":"قدم أهل الكتاب لإلهاب همة المسلمين إلى التقوى بالتأسي بالأمم السابقة وألا يفضلهم من قبلهم في الامتثال","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص158، تحت «دلالة تقديم ذكر أهل الكتاب السابقين بالوصية».","url":""}]},{"id":"s4-335","number":335,"surah":4,"verses":[131,132],"references":[{"surah":4,"verses":[131,132]}],"verseLabel":"النساء: 131؛ 132","question":"ما سرّ اختلاف خاتمة تكرار قوله تعالى: ﴿وَلِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ﴾ بين ﴿غَنِيًّا حَمِيدًا﴾ و﴿وَكَفَى بِاللَّهِ وَكِيلًا﴾؟","answer":"الأولى جاءت بعد الوعد بأن يغني الله الزوجين من سعته، فناسبها غناه المحمود. والثانية جاءت مع بيان قدرته على الاستبدال، فناسبها أنه الكافي في حفظ الأمر وتدبيره.","sources":[{"label":"ابن جماعة، كشف المعاني في المتشابه من المثاني، ص142؛ إسلام ويب، باب النساء: 131–132","url":""}]},{"id":"s4-336","number":336,"surah":4,"verses":[133],"references":[{"surah":4,"verses":[133]}],"verseLabel":"النساء: 133","question":"على من يدل لفظ ﴿آخرين﴾ في قوله تعالى: ﴿إن يشأ يذهبكم أيها الناس ويأت بآخرين﴾، وما قرينة ذلك؟","answer":"لفظ «آخر» يقتضي مماثلة المذكور في جنسه. ولما تقدم خطاب ﴿أيها الناس﴾، دل «آخرين» على أناس غير المخاطبين، من جنسهم، يأتي الله بهم بدلًا منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص169–170، تحت «نكتة التعبير بقوله: ﴿آخرين﴾».","url":""}]},{"id":"s4-337","number":337,"surah":4,"verses":[134],"references":[{"surah":4,"verses":[134]}],"verseLabel":"النساء: 134","question":"ما مناسبة تقديم ثواب الدنيا في قوله تعالى: ﴿فعند الله ثواب الدنيا والآخرة﴾؟","answer":"قدم ثواب الدنيا لأنها مطلوب من قصر إرادته عليها في صدر الشرط، ثم ضم إليها الآخرة لتوبيخه على طلب الأدنى وحده ودعوته إلى الجمع بين الخيرين","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص171–172، تحت «بلاغة قوله تعالى: ﴿فعند الله ثواب الدنيا والآخرة﴾».","url":""}]},{"id":"s4-338","number":338,"surah":4,"verses":[135],"references":[{"surah":4,"verses":[135]}],"verseLabel":"النساء: 135","question":"ما دلالة صيغة المبالغة في قوله تعالى: ﴿كونوا قوامين بالقسط﴾؟","answer":"تفيد صيغة «قوامين» المبالغة في ملازمة العدل والقيام به في الأحوال المختلفة، حتى في الشهادة على النفس والوالدين والأقربين؛ فهو خلق ثابت يتكرر العمل به، لا موقف عارض.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص179، تحت «سر التعبير بصيغة المبالغة ﴿قوامين﴾».","url":""}]},{"id":"s4-339","number":339,"surah":4,"verses":[135],"references":[{"surah":4,"verses":[135]}],"verseLabel":"النساء: 135","question":"ما سرّ تقديم القيام بالقسط على الشهادة لله في آية النساء؟","answer":"قُدم القيام بالقسط لأنه الأصل الجامع للعدل قولًا وفعلًا، ثم خُصت الشهادة بوصفها مظهرًا قوليًا لا يكمل إلا بالإخلاص لله","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص180، تحت «سر تقديم الأمر بالقسط على جعل الشهادة لله تعالى في قوله تعالى: ﴿كونوا قوامين بالقسط شهداء لله﴾».","url":""}]},{"id":"s4-340","number":340,"surah":4,"verses":[135],"references":[{"surah":4,"verses":[135]}],"verseLabel":"النساء: 135","question":"ما دلالة قوله تعالى: ﴿شهداء لله﴾، دون: شاهدين بالحق؟","answer":"«شهداء لله» يجعل الشهادة خالصة لوجه الله وتحت رقابته، فيعظم شأنها ويمنع محاباة النفس والقرابة","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص180، تحت «نكتة تقييد الشهادة بكونها لله سبحانه في قوله تعالى: ﴿شهداء لله﴾».","url":""}]},{"id":"s4-341","number":341,"surah":4,"verses":[135],"references":[{"surah":4,"verses":[135]}],"verseLabel":"النساء: 135","question":"ما دلالة البدء بالنفس في قوله تعالى: ﴿ولو على أنفسكم أو الوالدين والأقربين﴾؟","answer":"بدأ بالنفس لأنها أشد مواضع المحاباة وأصعبها، فمن أقام الحق عليها كان على إقامته على الوالدين والأقربين أقدر","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص182، 184، تحت «نكتة التدلي في ترتيب المشهود عليهم في قوله تعالى: ﴿ولو على أنفسكم أو الوالدين والأقربين﴾».","url":""}]},{"id":"s4-342","number":342,"surah":4,"verses":[135],"references":[{"surah":4,"verses":[135]}],"verseLabel":"النساء: 135","question":"ما دلالة الجمع بين الغني والفقير في قوله تعالى: ﴿إن يكن غنيًا أو فقيرًا فالله أولى بهما﴾؟","answer":"جمع الغني والفقير لاستيعاب ما قد يدعو إلى الجور في الشهادة: خوف الغني أو رجاء نفعه، والشفقة على الفقير. فلا يُترك الحق لأحدهما؛ فالله أعلم بمصلحتهما وأولى برعايتهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص186–188، تحت «دلالة الطباق في قوله تعالى: ﴿غنيًا أو فقيرًا﴾».","url":""}]},{"id":"s4-343","number":343,"surah":4,"verses":[135],"references":[{"surah":4,"verses":[135]}],"verseLabel":"النساء: 135","question":"ما مناسبة النهي عن اتباع الهوى قبل ذكر لَيّ الشهادة والإعراض عنها؟","answer":"قُدم النهي عن الهوى لأنه الدافع الباطن الذي ينشأ عنه ليّ الشهادة أو الإعراض عنها، فبدأ بالسبب ثم ذكر صورتي أثره","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص188–190، تحت «دلالة النهي عن اتباع الهوى بعد الأمر بالعدل».","url":""}]},{"id":"s4-344","number":344,"surah":4,"verses":[135],"references":[{"surah":4,"verses":[135]},{"surah":5,"verses":[8]}],"verseLabel":"النساء: 135؛ المائدة: 8","question":"ما سرّ اختلاف الترتيب بين قوله تعالى في النساء: ﴿قَوَّامِينَ بِالْقِسْطِ شُهَدَاءَ لِلَّهِ﴾، وفي المائدة: ﴿قَوَّامِينَ لِلَّهِ شُهَدَاءَ بِالْقِسْطِ﴾؟","answer":"في النساء: 135: في النساء مقام الشهادة على النفس والأقربين، فقدم القسط مقصدًا ولو خالف الهوى، ثم جعل الشهادة لله. وفي المائدة مقام الوفاء بعهد الله، فقدم القيام لله ثم بين أن الشهادة تكون بالقسط.\n\nفي المائدة: 8: في المائدة المقام وفاء بعهد الله وعدل مع قوم مبغضين، فقدم القيام لله وجعل القسط وصف الشهادة. وفي النساء المقام شهادة على النفس والأقربين، فقدم القسط لمقاومة المحاباة.","sources":[{"label":"[النساء: 135] ابن جماعة، *كشف المعاني*؛ منقول في Quranpedia، ملاحظة 40886","url":""},{"label":"[المائدة: 8] موسوعة التفسير البلاغي، ج8، ص634، تحت «السر في تقدم القوامة بالقسط على الشهادة في النساء، وتأخرها في المائدة».","url":""}]},{"id":"s4-345","number":345,"surah":4,"verses":[136],"references":[{"surah":4,"verses":[136]}],"verseLabel":"النساء: 136","question":"ما سرّ توجيه الخطاب إلى المؤمنين بقوله تعالى: ﴿يا أيها الذين آمنوا آمنوا﴾؟","answer":"من توجيهات الأمر أن يُطلب من المؤمنين الثبات والدوام على الإيمان، أو تكميله والإخلاص فيه والتصديق التفصيلي بما يجب الإيمان به؛ فليس المراد مجرد تحصيل إيمان حاصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص197–198، تحت «دلالة الأمر في قوله تعالى: ﴿آمنوا بالله ورسوله﴾».","url":""}]},{"id":"s4-346","number":346,"surah":4,"verses":[136],"references":[{"surah":4,"verses":[136]}],"verseLabel":"النساء: 136","question":"لماذا قُدّم الرسول على الكتاب في الأمر بالإيمان، ثم قُدمت الكتب على الرسل في الوعيد بالكفر في الآية نفسها؟","answer":"اختلف الترتيب باختلاف الاعتبار: ففي تلقي الناس الإيمان يتقدم الرسول الذي يبلّغهم الكتاب، وفي نزول الوحي من الله يتقدم الكتاب على الرسول المبلِّغ؛ فناسب كل ترتيب جهة النظر إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص200، تحت «نكتة تغاير الترتيب بين الرسول والكتاب في قوله تعالى: ﴿آمنوا بالله ورسوله والكتاب﴾، وقوله سبحانه: ﴿وكتبه ورسله﴾».","url":""}]},{"id":"s4-347","number":347,"surah":4,"verses":[136],"references":[{"surah":4,"verses":[136]}],"verseLabel":"النساء: 136","question":"ما سرّ التعبير عن القرآن بقوله تعالى: ﴿الْكِتَابِ الَّذِي نَزَّلَ عَلَى رَسُولِهِ﴾، وعن الكتب السابقة بقوله: ﴿وَالْكِتَابِ الَّذِي أَنْزَلَ مِنْ قَبْلُ﴾؟","answer":"التنزيل بالتشديد يلحظ نزول القرآن مفرقًا متتابعًا، والإنزال في الكتب السابقة يلحظ أصل إيتائها؛ فاختلاف الصيغة يطابق جهة العرض في كل موضع.","sources":[{"label":"فاضل السامرائي، *لمسات بيانية*؛ منقول في Quranpedia، ملاحظة 44579","url":""}]},{"id":"s4-348","number":348,"surah":4,"verses":[136],"references":[{"surah":4,"verses":[136]}],"verseLabel":"النساء: 136","question":"ما سرّ تأخير ﴿اليوم الآخر﴾ في النساء بعد الملائكة والكتب والرسل؟","answer":"سياق النساء في وجوب الإيمان بالوحي ورسله، فجمع وسائط الوحي أولًا ثم ختم باليوم الآخر الذي يظهر فيه جزاء التكذيب؛ فجاء الترتيب تابعًا لغرض السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص757، تحت «توجيه متشابه اللفظ»","url":""}]},{"id":"s4-349","number":349,"surah":4,"verses":[137],"references":[{"surah":4,"verses":[137]}],"verseLabel":"النساء: 137","question":"ما دلالة تكرار ﴿ثم﴾ في قوله تعالى: ﴿آمنوا ثم كفروا ثم آمنوا ثم كفروا﴾؟","answer":"تكرار «ثم» يرسم انتقالات متراخية متعاقبة بين الإيمان والكفر، ويكشف تكرر النقض بعد تجدد الحجة لا مجرد إعادة لفظية","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص203–204، تحت «سر عطف الجمل بـ﴿ثم﴾ في قوله تعالى: ﴿إن الذين آمنوا ثم كفروا ثم آمنوا ثم كفروا ثم ازدادوا كفرًا﴾».","url":""}]},{"id":"s4-350","number":350,"surah":4,"verses":[137],"references":[{"surah":4,"verses":[137]}],"verseLabel":"النساء: 137","question":"ما دلالة قوله تعالى: ﴿ثم ازدادوا كفرًا﴾، دون الاكتفاء باستمرارهم عليه؟","answer":"«ازدادوا كفرًا» يدل على نمو الكفر وترسخه بإضافة كفر إلى كفر بعد التقلب، وهو أبلغ من مجرد البقاء على درجة واحدة","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص204–205، تحت «نكتة إيثار التعبير بالفعل ﴿ازدادوا﴾ دون (زادوا)».","url":""}]},{"id":"s4-351","number":351,"surah":4,"verses":[138],"references":[{"surah":4,"verses":[138]}],"verseLabel":"النساء: 138","question":"ما سرّ التعبير بالبشارة في قوله تعالى: ﴿بشر المنافقين بأن لهم عذابًا أليمًا﴾؟","answer":"استعير لفظ البشارة، الذي يستعمل في الخبر السار، للإخبار بالعذاب الأليم تهكمًا بالمنافقين؛ فالمفارقة بين البشارة والعذاب تزيد التقريع والوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص208–209، تحت «بلاغة الاستعارة التهكمية في قوله تعالى: ﴿بشر المنافقين﴾».","url":""}]},{"id":"s4-352","number":352,"surah":4,"verses":[139],"references":[{"surah":4,"verses":[139]}],"verseLabel":"النساء: 139","question":"ما سرّ اختيار ﴿العزة﴾ في قوله تعالى: ﴿أيبتغون عندهم العزة﴾؟","answer":"العزة هي المنعة والرفعة التي تمنع الذل، وهي الغاية التي توهم المنافقون طلبها بموالاة الكافرين؛ فرد السياق بأن العزة كلها لله، وهو أدق من القوة أو النصرة وحدهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص211، 213–214، تحت «بلاغة الاستفهام التوبيخي في قوله تعالى: ﴿أيبتغون عندهم العزة﴾».","url":""}]},{"id":"s4-353","number":353,"surah":4,"verses":[140],"references":[{"surah":4,"verses":[140]}],"verseLabel":"النساء: 140","question":"لماذا جاء النهي عن القعود مع المستهزئين بآيات الله، ولم يُكتفَ بالنهي عن الرضا بقولهم؟","answer":"لأن الرضا أمر باطن، أما ترك القعود فيُظهر إنكار صنيعهم والغضب لله؛ فالنهي عن المجلس أبلغ في قطع المشاركة وإعلان رفض الاستهزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص220–221، تحت «بلاغة الكناية في قوله تعالى: ﴿فلا تقعدوا معهم﴾».","url":""}]},{"id":"s4-354","number":354,"surah":4,"verses":[140],"references":[{"surah":4,"verses":[140]}],"verseLabel":"النساء: 140","question":"ما دلالة قوله تعالى: ﴿إنكم إذًا مثلهم﴾، دون: فإنكم منهم؟","answer":"«مثلهم» يقرر المساواة في إثم الرضا والاستهزاء مع بقاء تمييز الأشخاص، بخلاف «منهم» التي قد تفيد اندراجًا مطلقًا في جماعتهم","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص222–223، تحت «بلاغة التشبيه في قوله تعالى: ﴿إنكم إذًا مثلهم﴾».","url":""}]},{"id":"s4-355","number":355,"surah":4,"verses":[140],"references":[{"surah":4,"verses":[140]}],"verseLabel":"النساء: 140","question":"ما مناسبة جمع المنافقين والكافرين في جهنم جميعًا بعد النهي عن مجالس الاستهزاء؟","answer":"جمع المنافقين والكافرين في جهنم لأن المنافقين جالسوهم ورضوا بخوضهم ووالوهم فصاروا مثلهم في الجرم، فناسب اتحاد المصير اتحاد السلوك","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص223–225، تحت «علة فصل قوله تعالى: ﴿إن الله جامع المنافقين والكافرين في جهنم جميعًا﴾ عما قبله».","url":""}]},{"id":"s4-356","number":356,"surah":4,"verses":[141],"references":[{"surah":4,"verses":[141]}],"verseLabel":"النساء: 141","question":"ما سرّ وصف المنافقين بقوله تعالى: ﴿الذين يتربصون بكم﴾؟","answer":"التربص انتظار مترقب مع مراقبة تحول الأحوال؛ وهو يصور المنافقين واقفين على النتائج ليظهروا لكل فريق أنهم معه طلبًا للغنيمة والنجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص226، 229–230، تحت «سر العدول عن الفعل (ينتظرون) إلى ﴿يتربصون﴾».","url":""}]},{"id":"s4-357","number":357,"surah":4,"verses":[141],"references":[{"surah":4,"verses":[141]}],"verseLabel":"النساء: 141","question":"ما دلالة اختلاف خطاب المنافقين عند فتح المؤمنين: ﴿ألم نكن معكم﴾، وعند نصيب الكافرين: ﴿ألم نستحوذ عليكم ونمنعكم من المؤمنين﴾؟","answer":"مع المؤمنين ادعوا المعية الظاهرة لأنهم عاشوا بينهم وحضروا القتال طلبًا للغنيمة، ومع الكافرين ادعوا الاستحواذ والمنع سرًا؛ أي التمكن منهم وحمايتهم بتخذيل المؤمنين","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص234، 236–238، تحت «دلالة الإخبار بالمعية مع المؤمنين دون الكافرين».","url":""}]},{"id":"s4-358","number":358,"surah":4,"verses":[141],"references":[{"surah":4,"verses":[141]}],"verseLabel":"النساء: 141","question":"ما سرّ التعبير عن نصر المؤمنين بقوله تعالى: ﴿فتح من الله﴾؟","answer":"«الفتح» أوسع أثرًا من مجرد النصر؛ فهو إزالة للإغلاق وفتح للبلاد وما يتبعه من غنائم وفيء، وذلك أدعى لطمع المنافقين في سهم منها","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص233، تحت «دلالة التعبير بالفتح دون النصر».","url":""}]},{"id":"s4-359","number":359,"surah":4,"verses":[141],"references":[{"surah":4,"verses":[141]}],"verseLabel":"النساء: 141","question":"ما سرّ التعبير عما يناله الكافرون بقوله تعالى: ﴿نصيب﴾، دون: فتح أو نصر؟","answer":"سمى ما يقع للكافرين ﴿نَصِيبٌ﴾، أي حظًا عارضًا، ولم يشرفه باسم الفتح المسند إلى الله كما فعل مع المؤمنين؛ ففي اختلاف اللفظ اختلاف في تقويم النتيجتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص232–233، 236، تحت «علة تسمية ظفر المسلمين فتحًا وظفر الكافرين نصيبًا».","url":""}]},{"id":"s4-360","number":360,"surah":4,"verses":[141],"references":[{"surah":4,"verses":[141]}],"verseLabel":"النساء: 141","question":"كيف يُفهم قوله تعالى: ﴿ولن يجعل الله للكافرين على المؤمنين سبيلًا﴾ مع وقوع غلبة للكافرين أحيانًا؟","answer":"ذكرت الموسوعة وجوهًا: نفي حجة الكافرين على المؤمنين يوم القيامة، أو نفي أن تكون حجتهم أقوى من حجة المسلمين. وذكرت أن ما يقع من ظهور عارض لا ينقض أصل الوعد بنصرة المؤمنين؛ فلا يُفهم النفي على أنه امتناع كل غلبة مؤقتة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص242–244، تحت «توجيه نفي ظهور الكافرين على المؤمنين».","url":""}]},{"id":"s4-361","number":361,"surah":4,"verses":[142],"references":[{"surah":4,"verses":[142]}],"verseLabel":"النساء: 142","question":"ما سرّ التعبير بقوله تعالى: ﴿إن المنافقين يخادعون الله﴾ بصيغة المفاعلة؟","answer":"صيغة المفاعلة في «يخادعون» تصور محاولة المغالبة وتكرار إظهار الإيمان وإبطان الكفر، مع توهمهم أن خداعهم ينجح؛ وهي أبلغ من فعل الخداع المجرد","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص249–250، تحت «دلالة اختيار صيغة يخادعون دون يخدعون».","url":""}]},{"id":"s4-362","number":362,"surah":4,"verses":[142],"references":[{"surah":4,"verses":[142]}],"verseLabel":"النساء: 142","question":"ما دلالة مجيء فعل المنافقين مضارعًا في ﴿يخادعون﴾، وجواب الله جملة اسمية في ﴿وهو خادعهم﴾؟","answer":"المضارع في «يخادعون» لتجدد محاولتهم وحدوثها، والاسم في «خادعهم» لثبوت تدبير الله المحيط ودوامه وغلبته","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص252، تحت «دلالة التعبير بصيغة الفعل مع المنافقين، وبالاسم مع الله تعالى».","url":""}]},{"id":"s4-363","number":363,"surah":4,"verses":[142],"references":[{"surah":4,"verses":[142]}],"verseLabel":"النساء: 142","question":"ما سرّ التعبير بقوله تعالى: ﴿قاموا إلى الصلاة﴾، دون: أقاموا الصلاة؟","answer":"«قاموا إلى الصلاة» يصور مجرد النهوض إليها متثاقلين لأجل الناس، لا إقامتها بحدودها وخشوعها كما يفعل المؤمن","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص253–254، تحت «سر العدول عن (أقاموا الصلاة) إلى ﴿قاموا إلى الصلاة﴾».","url":""}]},{"id":"s4-364","number":364,"surah":4,"verses":[142],"references":[{"surah":4,"verses":[142]}],"verseLabel":"النساء: 142","question":"ما دلالة وصف المنافقين بـ﴿كسالى﴾ بصيغة الاسم؟","answer":"جاء «كسالى» اسمًا وحالًا لازمة لإفادة ثبوت الكسل وتمكنه منهم عند الصلاة، بخلاف «يتكاسلون» الذي قد يوحي بتجدد عارض","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص255، تحت «إيثار التعبير بالاسم ﴿كسالى﴾ دون يتكاسلون في قوله: ﴿قاموا كسالى﴾».","url":""}]},{"id":"s4-365","number":365,"surah":4,"verses":[142],"references":[{"surah":4,"verses":[142]}],"verseLabel":"النساء: 142","question":"ما مناسبة ذكر الرياء بعد الكسل في الصلاة؟","answer":"الكسل يكشف فقد الدافع الباطن إلى الصلاة، ثم جاء الرياء ليبين الدافع البديل الظاهر: رؤية الناس؛ فالثاني يعلل الأول ويفضح المقصد","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص255–256، تحت «فائدة الفصل والاستئناف في جملة: ﴿يراءون الناس﴾».","url":""}]},{"id":"s4-366","number":366,"surah":4,"verses":[142],"references":[{"surah":4,"verses":[142]}],"verseLabel":"النساء: 142","question":"كيف يجتمع إظهار المنافقين الصلاة مع قوله تعالى: ﴿ولا يذكرون الله إلا قليلًا﴾؟","answer":"صلاتهم للناس لا لله، فلا يذكرونه إلا ذكرًا قليلًا عند حضور المؤمنين، أما الخلوة فتفضح خلو القلب من الذكر؛ إظهار صورة الصلاة لا يساوي ذكر الله الحقيقي","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص258–259، تحت «سر وصف ذكرهم لله تعالى بالقلة».","url":""}]},{"id":"s4-367","number":367,"surah":4,"verses":[143],"references":[{"surah":4,"verses":[143]}],"verseLabel":"النساء: 143","question":"ما الصورة في قوله تعالى: ﴿مذبذبين بين ذلك﴾، دون: مترددين؟","answer":"«مذبذبين» تصور حركة متكررة قلقة تدفعهم بين الفريقين من غير استقرار، وكأن قوة خارجية تذبذبهم؛ وهي أبلغ من تردد ذهني اختياري","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص263–265، تحت «إيثار هذه المادة ﴿مذبذبين﴾ دون مترددين».","url":""}]},{"id":"s4-368","number":368,"surah":4,"verses":[143],"references":[{"surah":4,"verses":[143]}],"verseLabel":"النساء: 143","question":"ما دلالة إفراد اسم الإشارة في قوله تعالى: ﴿مذبذبين بين ذلك﴾ مع ذكر فريقين؟","answer":"أُفرد اسم الإشارة باعتبار مجموع ما تقدم كأنه مذكور واحد، أو لأن «ذا» يصلح في أصل وضعه للإشارة إلى الواحد والاثنين والجمع؛ فالمراد تذبذبهم بين الإيمان والكفر، وليس الإفراد نفيًا لوجود طرفين.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص265–266، تحت «السر في توحيد اسم الإشارة، مع أن المشار إليه أمران».","url":""}]},{"id":"s4-369","number":369,"surah":4,"verses":[143],"references":[{"surah":4,"verses":[143]}],"verseLabel":"النساء: 143","question":"ما دلالة تكرار النفي في قوله تعالى: ﴿لا إلى هؤلاء ولا إلى هؤلاء﴾؟","answer":"تكرار «لا» ينفي انتماءهم إلى كل فريق استقلالًا ويؤكد استغراق النفي من الجهتين، فيرسخ صورة الضياع الكامل بينهما","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص267، تحت «السر في تكرار النفي في قوله سبحانه: ﴿لا إلى هؤلاء ولا إلى هؤلاء﴾».","url":""}]},{"id":"s4-370","number":370,"surah":4,"verses":[144],"references":[{"surah":4,"verses":[144]}],"verseLabel":"النساء: 144","question":"ما سرّ اختيار الأولياء في قوله تعالى: ﴿لا تتخذوا الكافرين أولياء﴾، دون: أنصارًا؟","answer":"الولاية أوسع من النصرة؛ تشمل القرب والمودة والطاعة والتدبير والتحالف، فنهى عن أصل الرابطة التي تفضي إلى النصرة لا عن صورة واحدة منها","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص273، تحت «سر التعبير بالأولياء دون نصراء».","url":""}]},{"id":"s4-371","number":371,"surah":4,"verses":[144],"references":[{"surah":4,"verses":[144]}],"verseLabel":"النساء: 144","question":"ما دلالة قوله تعالى: ﴿من دون المؤمنين﴾، ثم قوله: ﴿أتريدون أن تجعلوا لله عليكم سلطانًا مبينًا﴾؟","answer":"«من دون المؤمنين» يكشف استبدال رابطة الإيمان بموالاة الكافرين، والاستفهام يوبخهم لأن هذا الاختيار يصنع لله عليهم حجة ظاهرة تستوجب إلحاقهم بالمنافقين","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص272–275، تحت «سر ذكر السلطان في سياق النهي عن الموالاة».","url":""}]},{"id":"s4-372","number":372,"surah":4,"verses":[144],"references":[{"surah":4,"verses":[144]}],"verseLabel":"النساء: 144","question":"ما سرّ مجيء النهي في النساء خطابًا مباشرًا: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَتَّخِذُوا…﴾، وفي آل عمران بصيغة الغائب: ﴿لَا يَتَّخِذِ الْمُؤْمِنُونَ…﴾؟","answer":"آية النساء تواجه المؤمنين في سياق كشف المنافقين والتحذير من مسلكهم، فناسب النداء والنهي المباشر. وآل عمران تقرر أصلًا عامًا في سياق محاجة أهل الكتاب، فناسبها أسلوب الغائب.","sources":[{"label":"*مختصر لمسات بيانية*؛ منقول في Quranpedia، ملاحظة 44131","url":""}]},{"id":"s4-373","number":373,"surah":4,"verses":[145],"references":[{"surah":4,"verses":[145]}],"verseLabel":"النساء: 145","question":"ما سرّ إظهار اسم المنافقين في قوله تعالى: ﴿إن المنافقين في الدرك الأسفل﴾، دون: إنهم؟","answer":"أظهر اسم «المنافقين» بدل الضمير لتسجيل الوصف سببًا للحكم، وللدلالة الاسمية على ثبوت النفاق فيمن مات عليه، مع تحذير المؤمنين من صفته","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص278–279، تحت «نكتة العدول عن تعريف المنافقين بالموصولية إلى الاسم الصريح».","url":""}]},{"id":"s4-374","number":374,"surah":4,"verses":[145],"references":[{"surah":4,"verses":[145]}],"verseLabel":"النساء: 145","question":"ما سرّ التعبير بقوله تعالى: ﴿الدرك الأسفل﴾، دون: الطبقة السفلى؟","answer":"الدرك يقال للمراتب الهابطة، في مقابل الدرجات الصاعدة، وجعل المنافقين في أسفله يصور تناهي هبوطهم بسبب جمعهم الكفر والخداع والإفساد.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص277، 280–281، تحت «السر في اختيار الدرك الأسفل في عقاب المنافقين».","url":""}]},{"id":"s4-375","number":375,"surah":4,"verses":[145],"references":[{"surah":4,"verses":[145]}],"verseLabel":"النساء: 145","question":"ما مناسبة الاقتصار على النصير في قوله تعالى: ﴿ولن تجد لهم نصيرًا﴾؟","answer":"المقام مقام إنقاذ من العذاب، فناسب «النصير» الأعم في دفع الضرر","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص284–285، تحت «دلالة اختيار (نصير) بدلًا من (الولي)».","url":""}]},{"id":"s4-376","number":376,"surah":4,"verses":[146],"references":[{"surah":4,"verses":[146]}],"verseLabel":"النساء: 146","question":"ما دلالة جمع التوبة والإصلاح والاعتصام والإخلاص في شروط رجوع المنافقين؟","answer":"قوبلت أوصاف النفاق بما يرفعها: التوبة من الكفر، وإصلاح ما أفسدوه، والاعتصام بالله بدل التذبذب بين المؤمنين والكافرين، وإخلاص الدين بدل الرياء. فتجمع الآية تصحيح الظاهر والباطن.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص287–289، تحت «وجه اشتراط التوبة والإصلاح والاعتصام والإخلاص على المنافقين».","url":""}]},{"id":"s4-377","number":377,"surah":4,"verses":[146],"references":[{"surah":4,"verses":[146]}],"verseLabel":"النساء: 146","question":"ما مناسبة ذكر الاعتصام بالله بعد الإصلاح؟","answer":"بعد إصلاح الفساد جاء الاعتصام بالله ليعالج تذبذب المنافقين بين المؤمنين والكافرين؛ فهو تمسك بالله وثبات على الإيمان، ويكمل إصلاح الأعمال بإصلاح جهة الاعتماد والولاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص288–289، تحت «وجه اشتراط التوبة والإصلاح والاعتصام والإخلاص على المنافقين».","url":""}]},{"id":"s4-378","number":378,"surah":4,"verses":[146],"references":[{"surah":4,"verses":[146]}],"verseLabel":"النساء: 146","question":"ما سرّ التعبير بقوله تعالى: ﴿فأولئك مع المؤمنين﴾، دون: من المؤمنين؟","answer":"ناسبت المعية حال من كان منفصلًا عن جماعة المؤمنين بنفاقه ثم عاد بالتوبة والإصلاح؛ فهي تبشر بإلحاقه بصحبتهم وحكمهم وجزائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص291، تحت «سر التعبير بمعيتهم للمؤمنين دون وصفهم بالمؤمنين».","url":""}]},{"id":"s4-379","number":379,"surah":4,"verses":[147],"references":[{"surah":4,"verses":[147]}],"verseLabel":"النساء: 147","question":"ما دلالة الاستفهام في قوله تعالى: ﴿ما يفعل الله بعذابكم إن شكرتم وآمنتم﴾؟","answer":"الاستفهام للتقرير والنفي الإنكاري، وهو أبلغ من الخبر في نفي كل غرض أو نفع لله في تعذيب من شكر وآمن","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص295، تحت «دلالة الاستفهام».","url":""}]},{"id":"s4-380","number":380,"surah":4,"verses":[147],"references":[{"surah":4,"verses":[147]}],"verseLabel":"النساء: 147","question":"ما دلالة الجمع بين الشكر والإيمان في قوله تعالى: ﴿إن شكرتم وآمنتم﴾؟","answer":"قُدم الشكر لأن النظر في النعم ومعرفتها يقود إلى معرفة المنعم والإيمان به، فهو سبب متقدم على مسببه، ثم عطف الإيمان عليه عطف الخاص على العام أو المسبب على السبب","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص296–297، تحت «دلالة تقديم الشكر على الإيمان».","url":""}]},{"id":"s4-381","number":381,"surah":4,"verses":[147],"references":[{"surah":4,"verses":[147]}],"verseLabel":"النساء: 147","question":"ما دلالة وصف الله تعالى بقوله: ﴿شاكرًا عليمًا﴾؟","answer":"وصفه تعالى بالشكر يفيد قبول القليل من الطاعة والمجازاة عليه بالأجر الكثير، ووصفه بالعلم يطمئن إلى أنه يعلم إيمانهم وشكرهم ونياتهم فلا يضيع جزاؤهم؛ فالخاتمة وعد مناسب لما قبلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص297–299، تحت «السر في وصف الله تعالى بالشكر، والشكر من صفات العباد».","url":""}]},{"id":"s4-382","number":382,"surah":4,"verses":[148],"references":[{"surah":4,"verses":[148]}],"verseLabel":"النساء: 148","question":"ما دلالة تقييد النهي بالجهر في قوله تعالى: ﴿لا يحب الله الجهر بالسوء من القول﴾؟","answer":"خُص الجهر لأنه يذيع الإساءة بين السامعين فيشتد ضررها، والتقييد بالسوء لا يقتضي منع كل جهر. وذكر القول، وهو أخف من الفعل، ينبه إلى قبح ما فوقه من الأذى.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص304، تحت «التقييد بالجهر بالسوء وبالقول».","url":""}]},{"id":"s4-383","number":383,"surah":4,"verses":[148],"references":[{"surah":4,"verses":[148]}],"verseLabel":"النساء: 148","question":"ما دلالة استثناء ﴿إلا من ظلم﴾ من النهي عن الجهر بالسوء؟","answer":"الاستثناء يرخص للمظلوم أن يجهر بشكايته ويذكر ظلامته أو يدعو على ظالمه في حدود حقه، ولا يبيح له العدوان أو مطلق السباب","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص304–305، تحت «دلالة الاستثناء في الآية».","url":""}]},{"id":"s4-384","number":384,"surah":4,"verses":[148],"references":[{"surah":4,"verses":[148]}],"verseLabel":"النساء: 148","question":"ما مناسبة ترتيب ﴿سميعًا عليمًا﴾ في ختام آية الجهر بالسوء؟","answer":"قُدم «سميعًا» لمناسبة الجهر والقول المسموع في صدر الآية، ثم «عليمًا» لإحاطة العلم بالنيات وحقيقة الظلم وما خفي من الحال","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص305–306، تحت «فاصلة الآية ومفاد ما أوحت به».","url":""}]},{"id":"s4-385","number":385,"surah":4,"verses":[149],"references":[{"surah":4,"verses":[149]}],"verseLabel":"النساء: 149","question":"ما دلالة مقابلة إبداء الخير بإخفائه، ثم إفراد العفو عن السوء؟","answer":"الخير صالح للإبداء والإخفاء، ثم خُص العفو لأنه الخلق الأعلى المقابل لرخصة الجهر للمظلوم في السياق السابق، وفيه حث على ترك المؤاخذة مع القدرة","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص310–311، تحت «بلاغة الترقي في الخطاب».","url":""}]},{"id":"s4-386","number":386,"surah":4,"verses":[149],"references":[{"surah":4,"verses":[149]}],"verseLabel":"النساء: 149","question":"ما مناسبة الجمع بين العفو والقدرة في قوله تعالى: ﴿فإن الله كان عفوًا قديرًا﴾؟","answer":"العفو مع القدرة هو الكمال؛ لأن العاجز قد يترك الانتقام لعجزه، أما الله فيعفو وهو قادر، وفي ذلك حث للمؤمن على العفو حين يقدر.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص311–312، تحت «سر الختام بصفتي العفو والقدرة».","url":""}]},{"id":"s4-387","number":387,"surah":4,"verses":[149],"references":[{"surah":4,"verses":[149]}],"verseLabel":"النساء: 149","question":"ما سرّ اختلاف التعبير بين قوله تعالى في النساء: ﴿إِنْ تُبْدُوا خَيْرًا أَوْ تُخْفُوهُ﴾، وفي الأحزاب: ﴿إِنْ تُبْدُوا شَيْئًا أَوْ تُخْفُوهُ﴾؟","answer":"في النساء قُيد الإبداء والإخفاء بالخير لأن المقام في العفو وحسن المعاملة، وفي الأحزاب عُمم بـ﴿شيئًا﴾ لأن علم الله هناك متعلق بكل ما يظهر أو يخفى، خيرًا كان أو غيره.","sources":[{"label":"*مختصر لمسات بيانية*؛ منقول في Quranpedia، ملاحظة 44146","url":""}]},{"id":"s4-388","number":388,"surah":4,"verses":[150,151],"references":[{"surah":4,"verses":[150,151]}],"verseLabel":"النساء: 150–151","question":"ما دلالة تكرار ذكر الرسل في قوله تعالى: ﴿يكفرون بالله ورسله ويريدون أن يفرقوا بين الله ورسله﴾؟","answer":"لو جيء بالضمير بعد ذكر الله ورسله، لأمكن أن يوهم أن المراد التفريق بين بعض الرسل فحسب؛ فأعيد ذكر الله والرسل للتصريح بالتفريق بين الإيمان بالله والإيمان برسله، ودفع إبهام مرجع الضمير.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص320–321، تحت «نكتة إعادة لفظ الرسل».","url":""}]},{"id":"s4-389","number":389,"surah":4,"verses":[150,151],"references":[{"surah":4,"verses":[150,151]}],"verseLabel":"النساء: 150–151","question":"ما دلالة تقديم قولهم ﴿نؤمن ببعض﴾ على ﴿ونكفر ببعض﴾؟","answer":"قدموا دعوى الإيمان ببعض لتزيين موقفهم وستر أصل الكفر، ثم صرح السياق بما يهدمها؛ فليست الأولوية ترتيبًا زمنيًا ولا مجرد عناية","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص319–322","url":""}]},{"id":"s4-390","number":390,"surah":4,"verses":[150,151],"references":[{"surah":4,"verses":[150,151]}],"verseLabel":"النساء: 150–151","question":"ما دلالة قوله تعالى: ﴿ويريدون أن يتخذوا بين ذلك سبيلًا﴾ مع أنه لا منزلة بين الإيمان والكفر؟","answer":"«بين ذلك سبيلًا» يحكي إرادتهم اتخاذ طريق موهوم بين الإيمان والكفر","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص321، تحت «نكتة التعبير بالتركيب ﴿بين ذلك﴾».","url":""}]},{"id":"s4-391","number":391,"surah":4,"verses":[150,151],"references":[{"surah":4,"verses":[150,151]}],"verseLabel":"النساء: 150–151","question":"ما دلالة القصر في قوله تعالى: ﴿أولئك هم الكافرون حقًا﴾؟","answer":"ضمير الفصل و﴿حقًا﴾ يقطعان توهم منزلة وسطى بين الإيمان والكفر؛ فرفض رسول واحد نقض لأصل الإيمان بالرسل كلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص322–323، تحت «بلاغة حشد المؤكدات على حكم الكفر».","url":""}]},{"id":"s4-392","number":392,"surah":4,"verses":[152],"references":[{"surah":4,"verses":[152]}],"verseLabel":"النساء: 152","question":"ما دلالة ﴿أحد﴾ في قوله تعالى: ﴿ولم يفرقوا بين أحد منهم﴾؟","answer":"«أحد» في سياق النفي يعم كل فرد من الرسل، فيفيد انتفاء أي تفريق بينهم مع وجوب الإيمان بالجميع","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص328، تحت «علة دخول ﴿بين﴾ على ﴿أحد﴾».","url":""}]},{"id":"s4-393","number":393,"surah":4,"verses":[152],"references":[{"surah":4,"verses":[152]}],"verseLabel":"النساء: 152","question":"ما دلالة قوله تعالى: ﴿أولئك سوف يؤتيهم أجورهم﴾ بعد وصف المؤمنين بالرسل جميعًا؟","answer":"يؤكد الوعد استحقاق المؤمنين بالله وجميع رسله للأجر، ويفيد التعبير بـ«سوف» تحقق الجزاء في الاستقبال. و«أجورهم» تدل على توفية ما استحقوه من الأجر، والله هو المتكفل بإيتائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص328–330، تحت «نكتة التعبير بـ(سوف)».","url":""}]},{"id":"s4-394","number":394,"surah":4,"verses":[153],"references":[{"surah":4,"verses":[153]}],"verseLabel":"النساء: 153","question":"لماذا عُبّر بالمضارع ﴿يسألك﴾ في حكاية طلب أهل الكتاب إنزال كتاب من السماء؟","answer":"يستحضر المضارع مشهد سؤالهم العجيب كأنه يقع أمام السامع، ويحتمل أيضًا الدلالة على تجدد الطلب وإلحاحهم فيه؛ وكلا الوجهين يُبرز التعجب من تعنت السائلين.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص334–335، تحت «نكتة التعبير عن السؤال بالمضارع».","url":""}]},{"id":"s4-395","number":395,"surah":4,"verses":[153],"references":[{"surah":4,"verses":[153]}],"verseLabel":"النساء: 153","question":"ما مناسبة الانتقال من طلب إنزال كتاب إلى التذكير بقولهم لموسى: ﴿أرنا الله جهرة﴾؟","answer":"ذُكر طلب رؤية الله عقب طلب تنزيل الكتاب لبيان أن تعنتهم مع النبي امتداد لتعنت أسلافهم مع موسى، وأنهم سبق أن طلبوا ما هو أعظم وأشد، فلا يدل الطلب الحالي على طلب هداية صادق","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص334–335، تحت «دلالة الفاء في الجواب».","url":""}]},{"id":"s4-396","number":396,"surah":4,"verses":[153],"references":[{"surah":4,"verses":[153]}],"verseLabel":"النساء: 153","question":"ما دلالة قوله تعالى في الصاعقة: ﴿بظلمهم﴾، ثم في اتخاذ العجل: ﴿من بعد ما جاءتهم البينات﴾؟","answer":"«بظلمهم» يصرح بسبب أخذ الصاعقة في طلب الرؤية، ثم «من بعد ما جاءتهم البينات» يغلظ جريمة اتخاذ العجل بوقوعها بعد وضوح الآيات","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص334، 336، تحت «نكتة العطف بـ﴿ثم﴾».","url":""}]},{"id":"s4-397","number":397,"surah":4,"verses":[153],"references":[{"surah":2,"verses":[51,92]},{"surah":4,"verses":[153]},{"surah":7,"verses":[148,152]}],"verseLabel":"النساء: 153؛ البقرة: 51، 92؛ الأعراف: 148؛ الأعراف: 152","question":"ما سرّ حذف المفعول الثاني في قوله تعالى: ﴿ثم اتخذوا العجل﴾، وما تقديره؟","answer":"في النساء: 153؛ البقرة: 51، 92؛ الأعراف: 148: ﴿اتَّخَذَ﴾ هنا بمعنى صيّر، ولذلك يتعدى إلى مفعولين؛ والمفعول الثاني محذوف تقديره: اتخذوا العجل إلهًا أو معبودًا. دل على المحذوف تصريحهم في موضع آخر: ﴿هذا إلهكم وإله موسى﴾، فحذفه إيجاز للعلم به من القصة.\n\nفي الأعراف: 152: حذف المفعول الثاني، أي «إلهًا»، للعلم به من السياق، وللاستهجان حتى كأن ذكره مما ينزه عنه اللسان.","sources":[{"label":"[النساء: 153؛ البقرة: 51، 92؛ الأعراف: 148] الواحدي، *التفسير البسيط*، تحت الأعراف: 152؛ نقلًا عن الطبري 9/70، والزجاج 2/379، والنحاس 3/84، النص المحقق","url":"https://tafsir.app/albaseet/7/152"},{"label":"[الأعراف: 152] موسوعة التفسير البلاغي، ج14، ص598–606","url":""}]},{"id":"s4-398","number":398,"surah":4,"verses":[154],"references":[{"surah":4,"verses":[154]}],"verseLabel":"النساء: 154","question":"ما سرّ اختلاف التعبير بين قوله تعالى في النساء والبقرة: ﴿رَفَعْنَا فَوْقَهُمُ الطُّورَ﴾، وفي الأعراف: ﴿نَتَقْنَا الْجَبَلَ فَوْقَهُمْ﴾؟","answer":"«نتقنا» يدل على اقتلاع الجبل ورفعه مع تقديم الفعل وإبراز عظم الحدث، فناسب تفصيل الأعراف المكي، أما «رفعنا فوقهم الطور» فجرى في السورتين المدنيتين وناسب فعل الرفع اسم «الطور» الدال على الارتفاع","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص550، تحت «سر ذكر ﴿الطور﴾ هنا و﴿الجبل﴾ في الأعراف»، في المقارنة بالبقرة والنساء والأعراف.","url":""}]},{"id":"s4-399","number":399,"surah":4,"verses":[155,156],"references":[{"surah":4,"verses":[155,156]}],"verseLabel":"النساء: 155–156","question":"ما دلالة تراكم الجرائم في نسق واحد: نقض الميثاق، والكفر بالآيات، وقتل الأنبياء، وقولهم: قلوبنا غلف؟","answer":"عطف الجرائم بالواو يجعل كل واحدة منها وصفًا مستقلًا مستوجبًا للعقاب؛ فإذا اجتمعت اشتد استحقاق الوعيد، فظهر عظم الجناية من أفرادها ومن اجتماعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص346–347، تحت «دلالة العطف بالواو في قوله: ﴿وكفرهم﴾».","url":""}]},{"id":"s4-400","number":400,"surah":4,"verses":[155],"references":[{"surah":4,"verses":[155]}],"verseLabel":"النساء: 155","question":"ما دلالة قوله تعالى: ﴿وقتلهم الأنبياء بغير حق﴾ مع أن قتل الأنبياء لا يكون بحق؟","answer":"«بغير حق» ليست قيدًا يوهم إمكان قتل الأنبياء بحق، بل زيادة في تشنيع فعلهم وبلوغهم غاية الظلم؛ والتنـكير ينفي أي وجه من وجوه الحق كبيرًا أو صغيرًا","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص348–349، تحت «فائدة قوله: ﴿بغير حق﴾، ونفي مفهوم المخالفة».","url":""}]},{"id":"s4-401","number":401,"surah":4,"verses":[155],"references":[{"surah":4,"verses":[155]}],"verseLabel":"النساء: 155","question":"ما دلالة الإضراب بقوله تعالى: ﴿بل طبع الله عليها بكفرهم﴾ بعد قولهم: ﴿قلوبنا غلف﴾؟","answer":"«بل» ترد اعتذارهم بأن قلوبهم خُلقت مغلقة أو مستغنية بالعلم، وتثبت أن الطبع جزاء اختيارهم الكفر بعد أن خلق الله القلوب قابلة للحق","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص349–351، تحت «دلالة الإضراب، وبلاغة الرد».","url":""}]},{"id":"s4-402","number":402,"surah":4,"verses":[156],"references":[{"surah":4,"verses":[156]}],"verseLabel":"النساء: 156","question":"ما سرّ وصف قولهم على مريم بأنه ﴿بهتانًا عظيمًا﴾؟","answer":"البهتان كذب يحيّر من شدة افترائه، ووصفه بالعظيم يوافق فظاعة الطعن في مريم الطاهرة مع ما ظهر من آيات براءتها؛ فالجريمة عظيمة في موضوعها ودليل بطلانها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص353، تحت «سر تسمية الرمي بالزنى بهتانًا».","url":""}]},{"id":"s4-403","number":403,"surah":4,"verses":[157],"references":[{"surah":4,"verses":[157]}],"verseLabel":"النساء: 157","question":"ما دلالة تكرار النفي في قوله تعالى: ﴿وما قتلوه وما صلبوه﴾؟","answer":"كرر النفي لإبطال كل دعوى على استقلال: لا تحقق قتل عيسى عليه السلام، ولا تحقق صلبه؛ ثم كشف أن منشأ خبرهم هو الشبه لا العلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص355–356، تحت «بلاغة الرد على مزاعم اليهود في قتل عيسى ﷺ وصلبه».","url":""}]},{"id":"s4-404","number":404,"surah":4,"verses":[157],"references":[{"surah":4,"verses":[157]}],"verseLabel":"النساء: 157","question":"ما سرّ بناء قوله تعالى: ﴿ولكن شبه لهم﴾ للمجهول؟","answer":"البناء للمفعول في «شُبّه» يثبت وقوع الاشتباه دون تعيين الفاعل، وتذكر الصفحة احتمال إسناده إلى الجار والمجرور أو إلى ضمير المشبَّه","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص356، تحت «تعيين المسند إلى المبني للمفعول ودلالته».","url":""}]},{"id":"s4-405","number":405,"surah":4,"verses":[157],"references":[{"surah":4,"verses":[157]}],"verseLabel":"النساء: 157","question":"ما سرّ جعل ﴿اتباع الظن﴾ استثناءً في قوله تعالى: ﴿ما لهم به من علم إلا اتباع الظن﴾؟","answer":"على توجيه الاستثناء المنقطع، نُفي عنهم العلم، ثم بيّن أنهم يتبعون الظن؛ لأن الظن غير العلم. وتذكر الموسوعة أيضًا توجيه الاتصال بالنظر إلى شمول الاسم لهما على سبيل التجوز.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص357–358، تحت «دلالة النفي والاستثناء في قوله: ﴿ما لهم به من علم إلا اتباع الظن﴾».","url":""}]},{"id":"s4-406","number":406,"surah":4,"verses":[158],"references":[{"surah":4,"verses":[158]}],"verseLabel":"النساء: 158","question":"ما دلالة الإضراب في قوله تعالى: ﴿بل رفعه الله إليه﴾ بعد نفي القتل والصلب؟","answer":"انتقل الإضراب من إبطال روايتهم إلى إثبات الحقيقة المقابلة المشرفة: لم يظفروا به، بل رفعه الله إليه؛ وإظهار اسم الله يقرر أن النجاة والرفع بقدرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص359–360، تحت «بلاغة الإضراب في رفع عيسى».","url":""}]},{"id":"s4-407","number":407,"surah":4,"verses":[159],"references":[{"surah":4,"verses":[159]}],"verseLabel":"النساء: 159","question":"ما دلالة بناء التوكيد في قوله تعالى: ﴿وإن من أهل الكتاب إلا ليؤمنن به قبل موته﴾؟","answer":"البناء يجمع النفي والاستثناء والقسم ولامه ونون التوكيد، فيحصر ويؤكد أن كل واحد من أهل الكتاب سيؤمن بعيسى قبل الموت، مع تحريضهم على الإيمان النافع قبل الاضطرار إليه","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص360–361، تحت «بلاغة القصر بالنفي والاستثناء».","url":""}]},{"id":"s4-408","number":408,"surah":4,"verses":[159],"references":[{"surah":4,"verses":[159]}],"verseLabel":"النساء: 159","question":"ما دلالة عدم ذكر المشهود به في قوله تعالى: ﴿ويوم القيامة يكون عليهم شهيدًا﴾؟","answer":"حذف معمول «شهيدًا» يعمم شهادته عليهم في صغير أعمالهم وكبيرها، مع تقديم «يوم القيامة» و«عليهم» للتخصيص","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص362، تحت «بلاغة التقديم في قوله: ﴿ويوم القيامة يكون عليهم شهيدًا﴾».","url":""}]},{"id":"s4-409","number":409,"surah":4,"verses":[160],"references":[{"surah":4,"verses":[160]}],"verseLabel":"النساء: 160","question":"ما سرّ تقديم سبب التحريم في قوله تعالى: ﴿فبظلم من الذين هادوا حرمنا عليهم طيبات﴾؟","answer":"قدم سبب العقوبة «فبظلم» على مسببها «حرمنا» للتنبيه إلى فحش الظلم وتقبيحه والتحذير منه، ويفيد التركيب حصر سبب التحريم في ظلمهم","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص366، تحت «نكتة تقديم الجار والمجرور في قوله: ﴿فبظلم﴾».","url":""}]},{"id":"s4-410","number":410,"surah":4,"verses":[160],"references":[{"surah":4,"verses":[160]}],"verseLabel":"النساء: 160","question":"ما دلالة وصف المحرمات بأنها ﴿طيبات أحلت لهم﴾؟","answer":"وصفها بأنها «طيبات أُحلت لهم» يقرر أنها كانت حلالًا طيبة في أصلها ثم حُرمت عليهم عقوبةً لظلمهم، لا لخبث ذاتي فيها؛ وفي ذلك تغليظ للحرمان وكشف لافترائهم","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص365، 367–368، تحت «سر ذكر الطيبات هنا مجملة وفي سورة الأنعام مفصلة».","url":""}]},{"id":"s4-411","number":411,"surah":4,"verses":[161],"references":[{"surah":4,"verses":[161]}],"verseLabel":"النساء: 161","question":"ما دلالة الجمع بين أخذ الربا وأكل أموال الناس بالباطل؟","answer":"أخذ الربا صورة مخصوصة من المال المحرم مع سبق النهي عنها، ثم «أكل أموال الناس بالباطل» يعم الرشوة والنصب والاحتيال والغش؛ والجمع ينتقل من بعض المال إلى أبلغ الاعتداء المالي، لا مجرد استيعاب مترادفات.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص365، 369، تحت «سر الترتيب في أنواع الظلم المذكور».","url":""}]},{"id":"s4-412","number":412,"surah":4,"verses":[162],"references":[{"surah":4,"verses":[162]}],"verseLabel":"النساء: 162","question":"ما دلالة الاستدراك بقوله تعالى: ﴿لكن الراسخون في العلم منهم﴾ بعد ذم أهل الكتاب؟","answer":"الاستدراك يرفع توهم شمول الذم والعذاب كل أهل الكتاب، فيستثني الراسخين المؤمنين منهم، ويقابل بين الكفر وعذابه والإيمان وأجره","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص371، تحت «حسن الاستدراك في قوله: ﴿لكن الراسخون في العلم﴾».","url":""}]},{"id":"s4-413","number":413,"surah":4,"verses":[162],"references":[{"surah":4,"verses":[162]}],"verseLabel":"النساء: 162","question":"لماذا خُصت إقامة الصلاة وإيتاء الزكاة بالذكر بين أوصاف المؤمنين في هذه الآية؟","answer":"لأن الصلاة أشرف الطاعات البدنية، والزكاة أشرف الطاعات المالية؛ فجمعهما يبرز الإخلاص لله والإحسان إلى عباده، ويصل الإيمان بأثره في العبادة والبذل.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص372، تحت «علة تخصيص عبادتي الصلاة والزكاة بالذكر».","url":""}]},{"id":"s4-414","number":414,"surah":4,"verses":[162],"references":[{"surah":4,"verses":[162]}],"verseLabel":"النساء: 162","question":"ما سرّ نصب ﴿والمقيمين الصلاة﴾ في قراءة المصحف مع عطف الصفات قبلها وبعدها؟","answer":"النصب على المدح والاختصاص يقطع النسق ليلفت إلى منزلة الصلاة؛ كأن المعنى: وأخص بالمدح المقيمين الصلاة، وليس في التركيب خطأ نحوي.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص372، تحت «نكتة تخصيص المقيمين الصلاة بالذكر».","url":""}]},{"id":"s4-415","number":415,"surah":4,"verses":[162],"references":[{"surah":3,"verses":[7]},{"surah":4,"verses":[162]}],"verseLabel":"النساء: 162؛ آل عمران: 7","question":"ما الفرق السياقي بين ﴿الرَّاسِخُونَ فِي الْعِلْمِ﴾ في النساء، و﴿الرَّاسِخُونَ فِي الْعِلْمِ﴾ في آل عمران؟","answer":"ذكرت آل عمران الراسخين في العلم إجمالًا بوصف إيمانهم بالكتاب محكمه ومتشابهه: ﴿آمنا به كل من عند ربنا﴾. ثم فصلت النساء صفاتهم، فذكرت إيمانهم بما أُنزل إلى النبي وما أُنزل من قبله، وإقامة الصلاة وإيتاء الزكاة والإيمان بالله واليوم الآخر. فبين الموضعين إجمال ثم تفصيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص554–555، تحت عنوان «المناسبات بين سورة النساء والسور المجاورة والمشابهة لها»","url":""}]},{"id":"s4-416","number":416,"surah":4,"verses":[163],"references":[{"surah":4,"verses":[163]}],"verseLabel":"النساء: 163","question":"ما سرّ التعبير بقوله تعالى: ﴿إنا أوحينا إليك﴾، دون: أرسلناك؟","answer":"اختير «أوحينا» لأن الوحي إعلام إلهي خفي سريع وهو أعم من الإرسال، ولأن المقام يرد على مطالبتهم بكتاب من السماء بإثبات أن محمدًا تلقى الوحي كسائر النبيين","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص374، 376–377، تحت «إيثار استعمال الفعل ﴿أوحينا﴾ عوضًا عن الفعل (أرسلنا)».","url":""}]},{"id":"s4-417","number":417,"surah":4,"verses":[163],"references":[{"surah":4,"verses":[163]}],"verseLabel":"النساء: 163","question":"ما دلالة تشبيه الوحي إلى محمد ﷺ بالوحي إلى نوح والنبيين من بعده؟","answer":"التشبيه يثبت أن وحي محمد ﷺ من جنس الوحي إلى نوح والنبيين، مع اختلاف صوره والمُوحى به، فيرد إنكار أهل الكتاب ويقيم الدليل على نبوته","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص378–379، تحت «بلاغة التشبيه للوحي إليه، بالوحي للنبيين مع اختلاف أزمانهم».","url":""}]},{"id":"s4-418","number":418,"surah":4,"verses":[163],"references":[{"surah":4,"verses":[163]}],"verseLabel":"النساء: 163","question":"ما مناسبة البدء بنوح عليه السلام في سلسلة الأنبياء هنا؟","answer":"تذكر الموسوعة في تقديم نوح أنه أول أنبياء الشريعة وأول أولي العزم، وأنه أبو البشرية الثاني؛ كما تذكّر بطول صبره على أذى قومه وما انتهى إليه أمر المكذبين، تسلية للنبي ﷺ وتهديدًا للمعاندين.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص378–379، تحت «سر البدء بنوح ﷺ قبل سائر الأنبياء العظام».","url":""}]},{"id":"s4-419","number":419,"surah":4,"verses":[163],"references":[{"surah":4,"verses":[163]}],"verseLabel":"النساء: 163","question":"ما دلالة التعبير بقوله تعالى: ﴿كما أوحينا﴾؟","answer":"شبّه الوحي إلى النبي ﷺ بالوحي إلى الأنبياء قبله لإثبات اشتراكه معهم في أصل الوحي والرسالة ورد إنكار المنكرين. ولا تقتضي الكاف اتحاد صور الوحي وكيفياته في جميع الوجوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص378–379، تحت «دلالة اختيار حرف (الكاف) في قوله: ﴿كما أوحينا﴾ دون لفظ (مثل)».","url":""}]},{"id":"s4-420","number":420,"surah":4,"verses":[163],"references":[{"surah":4,"verses":[163]}],"verseLabel":"النساء: 163","question":"ما دلالة إجمال ﴿النبيين من بعده﴾ ثم تفصيل أسماء عدد منهم؟","answer":"أجمل النبيين أولًا لاستيعاب الجنس، ثم خص بعض المشهورين العالي المقام عند أهل الكتاب بأسمائهم تسليةً للنبي وعطفًا للخاص على العام، مع تقرير شرف وحيهم","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص381، تحت «سر ذكر بعض الأنبياء بأسمائهم بعد ذكرهم إجمالًا».","url":""}]},{"id":"s4-421","number":421,"surah":4,"verses":[163],"references":[{"surah":4,"verses":[163]}],"verseLabel":"النساء: 163","question":"ما سرّ تقديم عيسى على أيوب عليهما السلام مع تقدم أيوب زمنًا؟","answer":"قدم عيسى ردًا على اليهود الذين كفروا به وتحقيقًا لنبوته، ولأنه محور جدل واسع وأشهر وأعظم أتباعًا من أيوب ومن بعده، لا لمجرد العناية العامة أو ترتيب زمني","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص382، تحت «دلالة تقديم (عيسى) على (أيوب)، مع تقدمه في الزمان عليه».","url":""}]},{"id":"s4-422","number":422,"surah":4,"verses":[163],"references":[{"surah":4,"verses":[163]}],"verseLabel":"النساء: 163","question":"ما سرّ العدول من ﴿أوحينا﴾ إلى ﴿وآتينا داود زبورًا﴾؟","answer":"«آتينا داود زبورًا» تخصص بعد عموم الإيحاء بإيتاء الكتاب، وتجعل إيتاء الزبور نظير إيتاء القرآن مع دخولها في حكم الوحي السابق","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص383، تحت «دلالة التعبير بقوله: ﴿وآتينا﴾ دون قوله: (أوحينا)».","url":""}]},{"id":"s4-423","number":423,"surah":4,"verses":[163],"references":[{"surah":4,"verses":[163]},{"surah":6,"verses":[84,85,86]}],"verseLabel":"النساء: 163؛ الأنعام: 84–86","question":"ما سرّ اختلاف ترتيب أسماء الأنبياء في النساء: 163 عن ترتيبهم في الأنعام: 84–86؟","answer":"في النساء رتب الأنبياء بحسب تنوع الوحي والكتب والصحف ووجوه التكريم ردًا على طالبي كتاب من السماء، وفي الأنعام جاءوا في سياق نعم الله على إبراهيم وجُمعت أزواجهم بحسب صفات مشتركة","sources":[{"label":"ابن جماعة، كشف المعاني في المتشابه من المثاني، ص144؛ إسلام ويب، باب النساء: 163","url":""}]},{"id":"s4-424","number":424,"surah":4,"verses":[164],"references":[{"surah":4,"verses":[164]}],"verseLabel":"النساء: 164","question":"ما دلالة تكرار ﴿رسلًا﴾ في قوله تعالى: ﴿ورسلًا قد قصصناهم عليك من قبل ورسلًا لم نقصصهم عليك﴾؟","answer":"تكرار «رسلًا» يقابل فريقين مستقلين: من قصهم الله ومن لم يقصصهم، ويؤكد أن المذكورين سابقًا ليسوا العدد الكلي؛ كما يصنع طباق السلب بين الإثبات والنفي","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص386، 391، تحت «سر الجمع بين الإثبات والنفي فيما قص وما لم يقصص».","url":""}]},{"id":"s4-425","number":425,"surah":4,"verses":[164],"references":[{"surah":4,"verses":[164]}],"verseLabel":"النساء: 164","question":"ما دلالة ﴿لم﴾ في قوله تعالى: ﴿ورسلاً لم نقصصهم عليك﴾؟","answer":"«لم» تنفي القص في الزمن الماضي ولا تستلزم نفيه مطلقًا أو مؤبدًا، فيمكن أن يقصهم بعد ذلك أو يعلّم عددهم","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص391–392، تحت «دلالة التعبير بـ(لم) دون (لن) في قوله: ﴿لم نقصصهم عليك﴾».","url":""}]},{"id":"s4-426","number":426,"surah":4,"verses":[164],"references":[{"surah":4,"verses":[164]}],"verseLabel":"النساء: 164","question":"ما سرّ الجمع بين الفعل والمصدر في قوله تعالى: ﴿وكلم الله موسى تكليمًا﴾؟","answer":"المصدر المؤكد يثبت حقيقة التكليم وينفي حمل الفعل على مجرد الإلهام أو المجاز، فخص موسى بهذه المنقبة في سياق تنوع صور الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص392–393، تحت «دلالة الإتيان بالمصدر في قوله تعالى: ﴿وكلم الله موسى تكليمًا﴾».","url":""}]},{"id":"s4-427","number":427,"surah":4,"verses":[165],"references":[{"surah":4,"verses":[165]}],"verseLabel":"النساء: 165","question":"ما مناسبة تقديم التبشير على الإنذار في قوله تعالى: ﴿رسلًا مبشرين ومنذرين﴾؟","answer":"قُدمت البشارة لأنها أقرب إلى فتح القلب ودعوته إلى القبول، ثم جاء الإنذار لمن أعرض؛ فجمع إرسالهم الترغيب والترهيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص395، تحت «دلالة تقديم مبشرين على منذرين في قوله: ﴿رسلًا مبشرين ومنذرين﴾».","url":""}]},{"id":"s4-429","number":429,"surah":4,"verses":[165],"references":[{"surah":4,"verses":[165]}],"verseLabel":"النساء: 165","question":"ما سرّ التعبير بقوله تعالى: ﴿لئلا يكون للناس على الله حجة﴾، دون: احتجاج؟","answer":"الحجة هي الدليل الذي يثبت المقصود، أما الاحتجاج فقد يكون بحجة أو بمغالطة؛ فإرسال الرسل يقطع الحجة والعذر عن الناس، وإن ظل المبطل يجادل ويحتج بما لا يصح.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص396–397، تحت «دلالة التعبير بلفظ ﴿حجة﴾ دون لفظ (احتجاج)».","url":""}]},{"id":"s4-430","number":430,"surah":4,"verses":[165],"references":[{"surah":4,"verses":[165]}],"verseLabel":"النساء: 165","question":"ما دلالة قوله تعالى: ﴿بعد الرسل﴾ من غير ﴿من﴾؟","answer":"حذف «من» واختيار الظرف «بعد الرسل» يستغرق نفي الحجة في جميع الزمن اللاحق لإرسال الرسل وتبليغهم، لا مجرد ابتداء زمن بعدها","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص398، تحت «سر التعبير بالظرف (بعد)، دون الجار في (من بعد)».","url":""}]},{"id":"s4-431","number":431,"surah":4,"verses":[166],"references":[{"surah":4,"verses":[166]}],"verseLabel":"النساء: 166","question":"ما دلالة الاستدراك بقوله تعالى: ﴿لكن الله يشهد بما أنزل إليك﴾؟","answer":"«لكن» تستدرك على إنكار أهل الكتاب نزول القرآن ورفض شهادتهم للنبي: إن كذبوا فالله يشهد بإنزاله، وإظهار اسم الجلالة يزجر المعاندين ويثبت المؤمنين","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص401–402، تحت «دلالة الابتداء بالاستدراك في قوله: ﴿لكن الله يشهد بما أنزل إليك﴾».","url":""}]},{"id":"s4-432","number":432,"surah":4,"verses":[166],"references":[{"surah":4,"verses":[166]}],"verseLabel":"النساء: 166","question":"ما سرّ التعبير بقوله تعالى: ﴿بما أنزل إليك﴾، دون: بما أوحى إليك؟","answer":"اختير الإنزال لأن المقام مقام الرد على من طلبوا كتابًا من السماء؛ فناسب التصريح بأن القرآن كتاب أنزله الله إلى رسوله، أما الوحي فأعم من إنزال الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص404، تحت «دلالة العدول من الإيحاء إلى الإنزال في قوله: ﴿بما أنزل إليك﴾».","url":""}]},{"id":"s4-433","number":433,"surah":4,"verses":[166],"references":[{"surah":4,"verses":[166]}],"verseLabel":"النساء: 166","question":"ما دلالة قوله تعالى: ﴿أنزله بعلمه﴾؟","answer":"«أنزله بعلمه» أي أنزله بعلم تام وحكمة بالغة، عالمًا بأهلية الرسول وبحاجة البشر، وجعل كمال علمه آلة لإحكام القرآن وبلوغه غاية الإعجاز مع حفظه من الخلل والزيادة والنقص","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص404–406، تحت «دلالة اقتران إنزال القرآن بالعلم، في قوله: ﴿أنزله بعلمه﴾».","url":""}]},{"id":"s4-434","number":434,"surah":4,"verses":[166],"references":[{"surah":4,"verses":[166]}],"verseLabel":"النساء: 166","question":"ما دلالة إفراد شهادة الله ثم عطف قوله تعالى: ﴿والملائكة يشهدون﴾؟","answer":"أفرد شهادة الله لأنها الأصل الكافي، ثم عطف شهادة الملائكة لزيادة التقرير بتعدد الشهود وبيان عظم المشهود عليه؛ وشهادتهم تبع لشهادته لا تزكية لها","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص406–407، 409، تحت «دلالة عطف شهادة الملائكة على شهادة الله في قوله: ﴿والملائكة يشهدون﴾».","url":""}]},{"id":"s4-435","number":435,"surah":4,"verses":[166],"references":[{"surah":4,"verses":[166]}],"verseLabel":"النساء: 166","question":"ما سرّ التعبير بقوله تعالى: ﴿وكفى بالله شهيدًا﴾، دون: شاهدًا؟","answer":"﴿شهيد﴾ صيغة مبالغة تدل على كمال العلم والحضور وإقامة الحجة، والباء في هذا الأسلوب تؤكد كفاية شهادة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص400، 408–409، تحت «سر التعبير بـ﴿شهيدًا﴾ دون شاهد في قوله: ﴿وكفى بالله شهيدًا﴾».","url":""}]},{"id":"s4-436","number":436,"surah":4,"verses":[167],"references":[{"surah":4,"verses":[167]}],"verseLabel":"النساء: 167","question":"ما دلالة الجمع بين الكفر والصد عن سبيل الله؟","answer":"لم يقتصروا على الكفر في أنفسهم، بل ضموا إليه منع غيرهم من الإيمان وصرفه عن سبيل الله؛ فجمع الوصفين يبين اجتماع الضلال والإضلال فيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص413–414، تحت «دلالة الجمع بين الكفر والصد في الآية الكريمة».","url":""}]},{"id":"s4-437","number":437,"surah":4,"verses":[167],"references":[{"surah":4,"verses":[167]}],"verseLabel":"النساء: 167","question":"ما سرّ التعبير بقوله تعالى: ﴿وصدوا عن سبيل الله﴾، دون: ومنعوا الناس؟","answer":"الصد يجمع إعراضهم بأنفسهم وصرفهم غيرهم، و﴿سبيل الله﴾ تصور الدين طريقًا موصلًا إليه؛ فجريمتهم ليست منع أشخاص فحسب، بل إقامة العوائق في طريق الهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص411، 413، 415، تحت «دلالة التعبير بالصد دون المنع في قوله: ﴿وصدوا عن سبيل الله﴾».","url":""}]},{"id":"s4-438","number":438,"surah":4,"verses":[167],"references":[{"surah":4,"verses":[167]}],"verseLabel":"النساء: 167","question":"ما دلالة قوله تعالى: ﴿قد ضلوا ضلالًا بعيدًا﴾ بعد الكفر والصد؟","answer":"حققت ﴿قد﴾ وقوع الضلال، وأكده المصدر، ووصفه بالبعد لأنهم لم يكتفوا بالانحراف بل صدوا غيرهم؛ فصار الرجوع أبعد مع تراكم الجريمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص414–416، تحت «دلالة الضلال البعيد في قوله: ﴿قد ضلوا ضلالًا بعيدًا﴾».","url":""}]},{"id":"s4-439","number":439,"surah":4,"verses":[168,169],"references":[{"surah":4,"verses":[168,169]}],"verseLabel":"النساء: 168–169","question":"ما دلالة الجمع بين ﴿كفروا وظلموا﴾ مع أن الكفر أعظم الظلم؟","answer":"الكفر يحدد فساد الاعتقاد، والظلم يشمل ما انضم إليه من تعد على الرسل والناس وصد عن الحق؛ فذكر الظلم لإظهار الجرائم العملية المترتبة على كفرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص418–419، تحت «دلالة الجمع بين الكفر والظلم في قوله تعالى: ﴿إن الذين كفروا وظلموا﴾».","url":""}]},{"id":"s4-440","number":440,"surah":4,"verses":[168],"references":[{"surah":4,"verses":[168]}],"verseLabel":"النساء: 168","question":"ما سرّ التعبير بقوله تعالى: ﴿لم يكن الله ليغفر لهم﴾، دون: لن يغفر لهم؟","answer":"لام الجحود بعد ﴿لم يكن﴾ تنفي ملاءمة المغفرة لحال من استقر على الكفر والظلم، فهي أبلغ من خبر مستقبل مجرد؛ والتوبة تخرجه من هذا الوصف.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص419–420، تحت «دلالة صيغة الجحود في قوله: ﴿لم يكن الله ليغفر لهم﴾».","url":""}]},{"id":"s4-441","number":441,"surah":4,"verses":[168,169],"references":[{"surah":4,"verses":[168,169]}],"verseLabel":"النساء: 168–169","question":"كيف تُفهم الهداية في قوله تعالى: ﴿ولا ليهديهم طريقًا إلا طريق جهنم﴾؟","answer":"استُعملت الهداية مع طريق جهنم على المشاكلة والتهكم؛ فهي ليست هداية إلى الخير، بل تعبير عن إفضاء سوء اختيارهم إلى طريق جهنم","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص423، تحت «دلالة اختيار الفعل المنفي ﴿ولا ليهديهم طريقًا﴾».","url":""}]},{"id":"s4-442","number":442,"surah":4,"verses":[169],"references":[{"surah":4,"verses":[169]},{"surah":5,"verses":[119]},{"surah":9,"verses":[22]}],"verseLabel":"النساء: 169؛ المائدة: 119؛ التوبة: 22","question":"ما دلالة الجمع بين ﴿خالدين فيها﴾ و﴿أبدًا﴾؟","answer":"في النساء: 169: الخلود يدل على طول المكث أو دوامه بحسب السياق، وجاءت ﴿أبدًا﴾ لتقطع احتمال النهاية وتؤكد أن بقاءهم في جهنم لا ينقضي.\n\nفي المائدة: 119: ﴿خالدين فيها﴾ تثبت دوام إقامتهم في الجنات، و﴿أبدًا﴾ تؤكد امتداد هذا الخلود بلا نهاية ولا انقطاع؛ فدفعت كل توهم لمفارقة المكان أو انتهاء الزمن.\n\nفي التوبة: 22: ﴿خالدين﴾ تثبت طول الإقامة، و﴿أبدًا﴾ تنفي أن يكون لها نهاية مهما امتد الزمن؛ فالثاني يقطع كل احتمال للانقطاع.","sources":[{"label":"[النساء: 169] موسوعة التفسير البلاغي، ج8، ص423، تحت «دلالة ذكر لفظ ﴿أبدًا﴾ في قوله: ﴿خالدين فيها أبدًا﴾».","url":""},{"label":"[المائدة: 119] موسوعة التفسير البلاغي، ج10، ص160–175","url":""},{"label":"[التوبة: 22] موسوعة التفسير البلاغي، ج16، ص792–795","url":""}]},{"id":"s4-443","number":443,"surah":4,"verses":[169],"references":[{"surah":4,"verses":[169]}],"verseLabel":"النساء: 169","question":"ما دلالة تنكير ﴿طريقًا﴾ ثم استثناء ﴿طريق جهنم﴾ في قوله تعالى: ﴿ولا ليهديهم طريقًا إلا طريق جهنم﴾؟","answer":"نُكّر الطريق أولًا لنفي هدايتهم إلى طريق خير، ثم عُيّن طريق جهنم في الاستثناء فقُصر مصيرهم عليه؛ وانتقل اللفظ من العموم في النفي إلى تعيين الطريق المستثنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص422، تحت «بلاغة القصر في الآية في قوله تعالى: ﴿إلا طريق جهنم﴾».","url":""}]},{"id":"s4-444","number":444,"surah":4,"verses":[170],"references":[{"surah":4,"verses":[170]}],"verseLabel":"النساء: 170","question":"ما سرّ افتتاح الدعوة بقوله تعالى: ﴿يا أيها الناس﴾، دون تخصيص أهل الكتاب أو المؤمنين؟","answer":"النداء بالناس يعمم الدعوة إلى الإيمان بالرسول بعد قيام الحجة؛ فلا تختص بأهل الكتاب، بل تشملهم وتشمل غيرهم، بما يناسب عموم الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص427–428، تحت «دلالة التعبير بلفظ ﴿الناس﴾ في قوله: ﴿يا أيها الناس﴾».","url":""}]},{"id":"s4-445","number":445,"surah":4,"verses":[170],"references":[{"surah":4,"verses":[170]}],"verseLabel":"النساء: 170","question":"ما دلالة تعريف الرسول في قوله تعالى: ﴿قد جاءكم الرسول بالحق﴾؟","answer":"التعريف للعهد والعلم بالرسول؛ فقد بُشر به أهل الكتاب وكانوا ينتظرون بعثته. وفي اختياره بهذا الوصف تأكيد وجوب طاعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص428، تحت «دلالة التعريف في لفظ ﴿الرسول﴾ في قوله: ﴿قد جاءكم الرسول﴾».","url":""}]},{"id":"s4-446","number":446,"surah":4,"verses":[170],"references":[{"surah":4,"verses":[170]}],"verseLabel":"النساء: 170","question":"ما دلالة تقييد الحق بقوله تعالى: ﴿من ربكم﴾؟","answer":"وصف الحق بأنه «من ربكم» يستحضر الربوبية والتربية، ويرغب المخاطبين في التصديق بما جاء به الرسول","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص429، تحت «دلالة التعبير بلفظ الربوبية في قوله ﴿من ربكم﴾»","url":""}]},{"id":"s4-447","number":447,"surah":4,"verses":[170],"references":[{"surah":4,"verses":[170]}],"verseLabel":"النساء: 170","question":"ما سرّ نصب ﴿خيرًا﴾ في قوله تعالى: ﴿فآمنوا خيرًا لكم﴾ من غير فعل ظاهر؟","answer":"أوجز الحذف وكثّر المعنى؛ فمن توجيهاته: فآمنوا يكن الإيمان خيرًا لكم، أو ائتوا إيمانًا خيرًا لكم. وفي كل وجه حث على الإيمان وبيان عاقبته النافعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص430، تحت «ثمرة تنوع الأوجه الإعرابية في السياق الواحد».","url":""}]},{"id":"s4-448","number":448,"surah":4,"verses":[170],"references":[{"surah":4,"verses":[170]}],"verseLabel":"النساء: 170","question":"ما دلالة حذف جواب الشرط في قوله تعالى: ﴿وإن تكفروا فإن لله ما في السماوات والأرض﴾؟","answer":"دل تقرير الملك على الجواب المحذوف: فإن تكفروا فالله غني عنكم وعن إيمانكم وقادر على جزائكم؛ فتركه ليستنبط السامع من عموم الملك تهديدًا أوسع.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص430، تحت «دلالة حذف جواب الشرط في قوله تعالى: ﴿وإن تكفروا﴾».","url":""}]},{"id":"s4-449","number":449,"surah":4,"verses":[171],"references":[{"surah":4,"verses":[171]}],"verseLabel":"النساء: 171","question":"ما مناسبة الانتقال من خطاب الناس جميعًا إلى قوله تعالى: ﴿يا أهل الكتاب﴾؟","answer":"انتقل السياق إلى معالجة غلو النصارى في عيسى، بعد عرض انحراف اليهود في شأنه؛ والمراد بأهل الكتاب هنا النصارى بقرينة النهي عن قول ثلاثة. ففي الخطاب رد على هذه المقالة وتذكير لهم بكتابهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص433، 435، تحت «إطلاق العام وإرادة الخاص في الآية».","url":""}]},{"id":"s4-450","number":450,"surah":4,"verses":[171],"references":[{"surah":4,"verses":[171]}],"verseLabel":"النساء: 171","question":"ما الصورة في النهي بقوله تعالى: ﴿لا تغلوا في دينكم﴾؟","answer":"استعير الغلو، وهو مجاوزة الحد والارتفاع، للزيادة في الدين على ما شرعه الله؛ فصور الإفراط خروجًا عن الحد المرسوم، كما يرتفع الماء في غليانه أو يتجاوز السهم غايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص433، 435، تحت «دلالة الاستعارة في قوله: ﴿لا تغلوا في دينكم﴾».","url":""}]},{"id":"s4-451","number":451,"surah":4,"verses":[171],"references":[{"surah":4,"verses":[171]}],"verseLabel":"النساء: 171","question":"ما دلالة الجمع بين النهي عن الغلو والنهي عن القول على الله بغير الحق؟","answer":"الغلو أصل عام لكثير من الضلال، ثم خُص القول على الله بالباطل لعظم جريمة الافتراء التي نتج عنها تأليه المسيح؛ فهو عطف خاص على عام للاهتمام.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص435، تحت «دلالة الاستعارة في قوله: ﴿لا تغلوا في دينكم﴾».","url":""}]},{"id":"s4-452","number":452,"surah":4,"verses":[171],"references":[{"surah":4,"verses":[171]}],"verseLabel":"النساء: 171","question":"ما دلالة وصف عيسى عليه السلام بأنه ﴿كلمته ألقاها إلى مريم وروح منه﴾؟","answer":"هو كلمة الله بمعنى أنه خُلق بكلمة ﴿كن﴾ من غير أب، وروح مخلوقة صادرة من عنده تشريفًا، لا جزءًا من ذاته؛ فالعبارتان تثبتان معجزة خلقه ولا تدلان على ألوهيته.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص438–440، تحت «الدلالة البلاغية لتعدد الصفات لعيسى بن مريم هنا».","url":""}]},{"id":"s4-453","number":453,"surah":4,"verses":[171],"references":[{"surah":4,"verses":[171]}],"verseLabel":"النساء: 171","question":"ما معنى إلقاء الكلمة إلى مريم في قوله تعالى: ﴿وكلمته ألقاها إلى مريم﴾؟","answer":"فسرت الموسوعة إلقاء الكلمة إلى مريم بإعلامها بها وإخبارها أو إنزالها إليها؛ فالمعنى تبليغها أمر الله الذي خُلق به عيسى، لا إلقاء شيء حسي.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص438، تحت «إضافة (الكلمة) إلى الله، وتأخرها عن وصف الرسالة، في قوله: ﴿رسول الله وكلمته﴾».","url":""}]},{"id":"s4-454","number":454,"surah":4,"verses":[171],"references":[{"surah":4,"verses":[171]}],"verseLabel":"النساء: 171","question":"ما سرّ الإيجاز في قوله تعالى: ﴿ولا تقولوا ثلاثة﴾، دون تفصيل صورة التثليث؟","answer":"في «ثلاثة» إيجاز بحذف المبتدأ؛ فالنهي يتناول مقالتهم في التثليث مع اختلافهم في تفسيرها. وعدم تعيين المبتدأ يتيح حمل الكلام على تقديرات تناسب صور زعمهم المختلفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص440–441، تحت «الفاء الفصيحة وأسلوب الاحتراس يجليان الأمر بالإيمان النقي من كل زعم فاسد».","url":""}]},{"id":"s4-455","number":455,"surah":4,"verses":[171],"references":[{"surah":4,"verses":[171]}],"verseLabel":"النساء: 171","question":"ما سرّ نصب ﴿خيرًا﴾ في قوله تعالى: ﴿انتهوا خيرًا لكم﴾؟","answer":"التقدير: انتهوا يكن الانتهاء خيرًا لكم، أو ائتوا أمرًا خيرًا لكم؛ فحذف العامل للإيجاز، وجعل النهي عن التثليث موصولًا مباشرة بعاقبته النافعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص430، 441، تحت «ثمرة تنوع الأوجه الإعرابية في السياق الواحد».","url":""}]},{"id":"s4-456","number":456,"surah":4,"verses":[172],"references":[{"surah":4,"verses":[172]}],"verseLabel":"النساء: 172","question":"ما سرّ التعبير بقوله تعالى: ﴿لن يستنكف المسيح أن يكون عبدًا لله﴾، دون: لن يستكبر؟","answer":"الاستنكاف امتناع ناشئ من أنفة؛ فهو أدق في نفي أن يأنف المسيح من العبودية، ثم ذكر الاستكبار بعده لوعيد من يتعالى عن الطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص443–444، 450–451، تحت «الاستنكاف والاستكبار».","url":""}]},{"id":"s4-457","number":457,"surah":4,"verses":[172],"references":[{"surah":4,"verses":[172]}],"verseLabel":"النساء: 172","question":"ما مناسبة عطف الملائكة المقربين على المسيح في مقام نفي الاستنكاف؟","answer":"ذُكر المسيح والملائكة ممن غلا فيهم بعض البشر؛ فإذا لم يأنف هؤلاء المقربون من عبودية الله فغيرهم أولى، وفي الجمع إبطال لتأليه المسيح والملائكة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص445–446، تحت عنوان «عطف الملائكة على المسيح؛ لأنهم قيل عنهم أبناء الله، وكذلك المسيح»","url":""}]},{"id":"s4-458","number":458,"surah":4,"verses":[172],"references":[{"surah":4,"verses":[172]}],"verseLabel":"النساء: 172","question":"ما دلالة وصف الملائكة بـ﴿المقربين﴾ في هذا السياق؟","answer":"خُص المقربون لعلو درجتهم ومنزلتهم؛ ومع هذه الرفعة لا يستنكفون عن عبادة الله. فالقرب منه لا يُخرج المخلوق عن العبودية له.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص445–446، تحت عنوان «عطف الملائكة على المسيح؛ لأنهم قيل عنهم أبناء الله، وكذلك المسيح»","url":""}]},{"id":"s4-459","number":459,"surah":4,"verses":[172,173],"references":[{"surah":4,"verses":[172,173]}],"verseLabel":"النساء: 172–173","question":"ما دلالة الجمع بين الاستنكاف والاستكبار في الوعيد؟","answer":"الاستنكاف امتناع ناشئ عن أنفة وتصور نقص، أما الاستكبار فطلب الكبر والترفع، والجمع يستوعب صور الامتناع عن عبادة الله","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص450، تحت «الاستنكاف والاستكبار»","url":""}]},{"id":"s4-460","number":460,"surah":4,"verses":[174],"references":[{"surah":4,"verses":[174]}],"verseLabel":"النساء: 174","question":"ما دلالة إضافة البرهان إلى الرب في قوله تعالى: ﴿قد جاءكم برهان من ربكم﴾؟","answer":"إضافته إلى الرب تقوي دلالته؛ فما جاء من عند الله برهان صادق مقنع لطالب الحق. وفي إضافة الرب إلى المخاطبين تذكير بتربيته لهم وتبليغهم كمالهم اللائق بهم، وترغيب في امتثال أمره.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص454–455، تحت عنوان «ذكر الربوبية في قوله تعالى: ﴿من ربكم﴾ فيه تقوية لمعنى البرهان»","url":""}]},{"id":"s4-475","number":475,"surah":4,"verses":[174],"references":[{"surah":4,"verses":[174]}],"verseLabel":"النساء: 174","question":"لماذا سُمّي القرآن ﴿نورًا مبينًا﴾؟","answer":"سُمّي نورًا لأن الأحكام تتبين به كما تتبين الأشياء بالنور، ولأنه سبب لوقوع نور الإيمان في القلب؛ ووصفه بأنه مبين يدل على وضوحه وإيضاحه لغيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص455، تحت عنوان «من أسرار القرآن أن برهانه يؤثر في السامع، ولو كان لا يجيد العربية»","url":""}]},{"id":"s4-461","number":461,"surah":4,"verses":[175],"references":[{"surah":4,"verses":[175]}],"verseLabel":"النساء: 175","question":"ما دلالة الجمع بين الإيمان بالله والاعتصام به؟","answer":"جمع بين الإيمان بالله والتمسك بدينه؛ فالاعتصام يتضمن طلب ما يحفظ صاحبه، وصيغته تدل على الاجتهاد في ذلك. فليس المقصود التصديق وحده، بل ملازمة الدين والاجتهاد في الالتزام به.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص455–456، تحت عنوان «الاعتصام بالله استعارة للالتزام بدينه»","url":""}]},{"id":"s4-462","number":462,"surah":4,"verses":[175],"references":[{"surah":4,"verses":[175]}],"verseLabel":"النساء: 175","question":"ما دلالة ترتيب قوله تعالى: ﴿فسيدخلهم في رحمة منه وفضل ويهديهم إليه صراطًا مستقيمًا﴾؟","answer":"وعدهم بالرحمة وهي الجنة، ثم بالفضل وهو الزيادة في الثواب، ثم بالهداية إلى الصراط المستقيم؛ وقد قُدّم الوعد بدخول الجنة على الهداية إليها للمسارعة إلى التبشير بالمقصد الأصلي","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص457–458، تحت «الضمير في قوله ﴿إليه﴾ عائد على الله تعالى، وذلك على حذف مضاف».","url":""}]},{"id":"s4-463","number":463,"surah":4,"verses":[176],"references":[{"surah":4,"verses":[176]}],"verseLabel":"النساء: 176","question":"ما مناسبة ختم السورة بمسألة الكلالة بعد افتتاحها بأحكام الأسرة والمواريث؟","answer":"خُتمت السورة بأحكام الأموال والميراث كما افتُتحت بها، فتحقق التوافق بين البداية والخاتمة. وفي توزيع أحكام الفرائض على أول السورة وأثنائها وآخرها إظهار لشدة الاهتمام بها وتدرج في عرضها يعين على قبولها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص473، تحت عنوان «حكمة تأخير آية الكلالة إلى نهاية السورة؛ لتعلقها بتمام ما سلف»","url":""}]},{"id":"s4-464","number":464,"surah":4,"verses":[176],"references":[{"surah":4,"verses":[176]}],"verseLabel":"النساء: 176","question":"ما سرّ حذف متعلق الاستفتاء أولًا ثم إظهاره في قوله تعالى: ﴿يستفتونك قل الله يفتيكم في الكلالة﴾؟","answer":"حُذف متعلق ﴿يستفتونك﴾ لدلالة ﴿يفتيكم في الكلالة﴾ عليه وتجنب التكرار، وأُظهر في جواب الفتوى للعناية بأمر الكلالة وكثرة السؤال عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص463–464، تحت «أثر الإيجاز بالحذف في قوله تعالى: ﴿يستفتونك﴾».","url":""}]},{"id":"s4-465","number":465,"surah":4,"verses":[176],"references":[{"surah":4,"verses":[176]}],"verseLabel":"النساء: 176","question":"ما دلالة التصريح باسم الله في قوله تعالى: ﴿قل الله يفتيكم في الكلالة﴾؟","answer":"صُرّح باسم الله لئلا يُتوهم أن الرسول مصدر الفتوى؛ فالله هو المفتي والمشرع، والرسول مبلّغ حكمه، وفي ذلك توكيد لثبوت الحكم ودوامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص465–466، تحت «سر ورود لفظ الجلالة ﴿الله﴾ في قوله: ﴿قل الله يفتيكم﴾».","url":""}]},{"id":"s4-466","number":466,"surah":4,"verses":[176],"references":[{"surah":4,"verses":[176]}],"verseLabel":"النساء: 176","question":"ما سرّ التعبير بقوله تعالى: ﴿إن امرؤ هلك﴾، دون: مات؟","answer":"اختير ﴿هلك﴾ لما فيه من معنى الفناء وانقطاع الأثر؛ فناسب حال الكلالة التي تنقطع فيها ذرية الميت ولا يكون له ولد، بخلاف مجرد الإخبار بالموت","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص467، تحت «سر التعبير بلفظ الهالك في قوله: ﴿إن امرؤ هلك﴾»","url":""}]},{"id":"s4-467","number":467,"surah":4,"verses":[176],"references":[{"surah":4,"verses":[176]}],"verseLabel":"النساء: 176","question":"ما سرّ عدم التصريح بالوالد في قوله تعالى: ﴿ليس له ولد وله أخت﴾ مع أن الكلالة تكون بغير والد ولا ولد؟","answer":"اكتفى بانتفاء الولد لأن حكم الأخت المذكور واسم الكلالة يدلان على انتفاء الوالد؛ فلو وجد الأب لم ترث الأخت هذا الفرض، فحذفه إيجاز لدلالة الحكم عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص467–468، تحت «سر الاقتصار على نفي الولد، مع أن نفي الوالد معتبر في الكلالة».","url":""}]},{"id":"s4-468","number":468,"surah":4,"verses":[176],"references":[{"surah":4,"verses":[176]}],"verseLabel":"النساء: 176","question":"ما سرّ زيادة ﴿اثنتين﴾ في قوله تعالى: ﴿فإن كانتا اثنتين﴾ مع دلالة ألف الاثنين عليها؟","answer":"من توجيهات المصدر أن ألف التثنية قد تدل على اثنين موصوفين بصفة، فجاء العدد «اثنتين» مجردًا من الصفة لتعيين العدد المقصود. ويعرض المصدر كذلك اعتراضًا بأن ضمير التثنية نفسه يدل على العدد، فلا يُذكر التوجيه كأنه خالٍ من الخلاف.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص469–470، تحت «ما فائدة قوله: ﴿اثنتين﴾ مع أن لفظ ﴿كانتا﴾ لا يفسر إلا بهذا العدد؟».","url":""}]},{"id":"s4-469","number":469,"surah":4,"verses":[176],"references":[{"surah":4,"verses":[176]}],"verseLabel":"النساء: 176","question":"ما سرّ التعبير بقوله تعالى: ﴿يبين الله لكم أن تضلوا﴾، دون: لئلا تضلوا؟","answer":"التقدير: يبين الله لكم كراهة أن تضلوا، أو يبين لكم لئلا تضلوا؛ فحذف ما دل عليه مقام البيان، وجاء المصدر المؤول موجزًا في بيان غاية الفتوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص471، تحت «الإيجاز بالحذف، وتعدد تقدير المحذوف، وأثره في المعنى».","url":""}]},{"id":"s4-470","number":470,"surah":4,"verses":[176],"references":[{"surah":4,"verses":[176]}],"verseLabel":"النساء: 176","question":"ما مناسبة ختم السورة بقوله تعالى: ﴿والله بكل شيء عليم﴾؟","answer":"تفاصيل المواريث مبنية على علم محيط بالقرابات والمصالح والعواقب، فتعَلّل الخاتمة الأحكام بعلم الله وتدعو إلى التسليم، كما تستقل بعموم علمه بكل شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص471–472، تحت «التذييل لتعليل الأحكام بقوله تعالى: ﴿والله بكل شيء عليم﴾».","url":""}]},{"id":"s4-471","number":471,"surah":4,"verses":[176],"references":[{"surah":4,"verses":[176]}],"verseLabel":"النساء: 176","question":"ما سرّ بدء فتوى الكلالة بقوله تعالى: ﴿يَسْتَفْتُونَكَ﴾ بلا واو، مع مجيء فتوى النساء قبلها: ﴿وَيَسْتَفْتُونَكَ فِي النِّسَاءِ﴾ بالواو؟","answer":"فتوى الكلالة استئناف مستقل في خاتمة السورة بعد انقضاء السياق السابق، أما فتوى النساء فعُطفت بالواو على أحكام النساء المتصلة قبلها؛ فالحرف يكشف صلة كل سؤال بسياقه.","sources":[{"label":"*مختصر لمسات بيانية*؛ منقول في Quranpedia، ملاحظة 44175","url":""}]},{"id":"s5-1","number":1,"surah":5,"verses":[1],"references":[{"surah":5,"verses":[1]}],"verseLabel":"المائدة: السورة","question":"ما سرّ تسمية السورة بـ﴿المائدة﴾؟","answer":"سُمّيت سورة المائدة لاختصاصها بذكر المائدة التي طلب الحواريون من عيسى عليه السلام أن يسأل ربه إنزالها، ولم ترد قصتها في سورة أخرى. وسُمّيت أيضًا سورة العقود لافتتاحها بالأمر بالوفاء بالعقود.","sources":[{"label":"ابن عاشور، *التحرير والتنوير*، مقدمة سورة المائدة؛ النص المنشور","url":"https://quran.com/ar/al-maidah/info"}]},{"id":"s5-2","number":2,"surah":5,"verses":[1],"references":[{"surah":5,"verses":[1]}],"verseLabel":"المائدة: 1","question":"ما مناسبة افتتاح سورة المائدة بالأمر: ﴿أوفوا بالعقود﴾؟","answer":"افتتحت بالوفاء لأن السورة تشتمل على عقود ومواثيق كثيرة مع الله وبين الناس، وعلى أحكام الحلال والحرام والشهادة؛ فجاء المطلع براعة استهلال لمقاصدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص493–494، تحت «براعة الاستهلال في افتتاح السورة بالأمر بالإيفاء بالعقود»","url":""}]},{"id":"s5-3","number":3,"surah":5,"verses":[1],"references":[{"surah":5,"verses":[1]}],"verseLabel":"المائدة: 1","question":"لماذا جاء الأمر بالوفاء بـ﴿العقود﴾ معرفًا من غير تقييد بنوع منها؟","answer":"التعريف للاستغراق؛ فيشمل ما أوجبه الله على عباده وما يعقده الناس بينهم من التزامات صحيحة، فلا يختص بعقد معين. وفي هذا العموم جمع لوجوه الوفاء التي تفصلها السورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص495، تحت «التعريف في العقود للاستغراق، في قوله: ﴿أوفوا بالعقود﴾»","url":""}]},{"id":"s5-4","number":4,"surah":5,"verses":[1],"references":[{"surah":5,"verses":[1]}],"verseLabel":"المائدة: 1","question":"ما الصورة في التعبير عن العهود بـ﴿العقود﴾؟","answer":"العقد في الأصل ربط طرفين ربطًا محكمًا، فاستعير للعهد الذي يلزم صاحبه ولا يحله بالهوى؛ وفي الصورة معنى التوثيق والقوة واللزوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص496، تحت «دلالة الاستعارة التصريحية في قوله تعالى: ﴿أوفوا بالعقود﴾»","url":""}]},{"id":"s5-5","number":5,"surah":5,"verses":[1],"references":[{"surah":5,"verses":[1]}],"verseLabel":"المائدة: 1","question":"ما مناسبة ذكر تحليل بهيمة الأنعام عقب الأمر بالوفاء بالعقود؟","answer":"بعد الأمر الجامع بالوفاء بدأ بتفصيل أول ما عقده الله عليهم من أحكام الحلال والحرام؛ فصار تحليل الأنعام وما استثني منها تطبيقًا مباشرًا للعقد العام.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص497–498، تحت «المناسبة بين الوفاء بالعقود، وحل بهيمة الأنعام للمؤمنين»","url":""}]},{"id":"s5-6","number":6,"surah":5,"verses":[1],"references":[{"surah":5,"verses":[1]}],"verseLabel":"المائدة: 1","question":"ما سرّ بناء قوله تعالى: ﴿أُحلت لكم﴾ للمجهول؟","answer":"بُني الفعل لما لم يسم فاعله لأن الفاعل معلوم؛ فالمخاطبون مؤمنون يقرون بأن المنعم والمشرّع هو الله وحده. وفي الإخبار بإحلال الأنعام لهم إظهار لرحمته وكرمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص497، تحت عنوان «دلالة بناء الفعل (أحل) لما لم يسم فاعله، في قوله: ﴿أحلت لكم بهيمة الأنعام﴾»","url":""}]},{"id":"s5-7","number":7,"surah":5,"verses":[1],"references":[{"surah":5,"verses":[1]}],"verseLabel":"المائدة: 1","question":"ما دلالة إضافة ﴿بهيمة﴾ إلى ﴿الأنعام﴾ في قوله تعالى: ﴿بهيمة الأنعام﴾؟","answer":"لفظ البهيمة أعم، وإضافته إلى الأنعام تبين الجنس الذي يتعلق به الحل وتحتَرز من دخول ما حُرّم من البهائم؛ فلا تُحمل الإباحة على عموم لفظ البهيمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص499، تحت عنوان «الاحتراز بذكر المضاف إليه في قوله تعالى: ﴿أحلت لكم بهيمة الأنعام﴾»","url":""}]},{"id":"s5-8","number":8,"surah":5,"verses":[1],"references":[{"surah":5,"verses":[1]}],"verseLabel":"المائدة: 1","question":"ما سرّ إجمال المستثنى في قوله تعالى: ﴿إلا ما يتلى عليكم﴾؟","answer":"أُجمل المستثنى هنا، ثم بُيّن في قوله: ﴿حرمت عليكم الميتة والدم﴾ وما بعدها؛ فالعبارة تحيل إلى آيات التحريم التي تفصّل ما خرج من الإباحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص500، تحت «الاستثناء في قوله: ﴿إلا ما يتلى عليكم﴾ استثناء من بهيمة الأنعام»","url":""}]},{"id":"s5-9","number":9,"surah":5,"verses":[1],"references":[{"surah":5,"verses":[1]}],"verseLabel":"المائدة: 1","question":"ما سرّ التعبير بقوله تعالى: ﴿غير محلي الصيد وأنتم حرم﴾ بدل التصريح: وحرم عليكم الصيد في الإحرام؟","answer":"جاء النهي في صورة حال تقيد المخاطبين وقت الانتفاع بالإباحة: أحلت لكم الأنعام حال كونكم غير مستحلين للصيد وأنتم محرمون؛ فجمع التركيب سعة النعمة وحدها في جملة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص502، تحت «ترادف جملتين حاليتين لبيان المستثنى، والتدرج في صيغ التحريم»","url":""}]},{"id":"s5-10","number":10,"surah":5,"verses":[1],"references":[{"surah":5,"verses":[1]}],"verseLabel":"المائدة: 1","question":"ما مناسبة ختم أول آية بقوله تعالى: ﴿إن الله يحكم ما يريد﴾؟","answer":"الخاتمة تقرر أن التحليل والتحريم حكم الله وحده، وأن استثناء الصيد حال الإحرام داخل في سلطانه التشريعي، فلا تخضع الحدود لأهواء الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص504، تحت «جملة التذييل لتعليل الحكم، بقوله: ﴿إن الله يحكم ما يريد﴾»","url":""}]},{"id":"s5-11","number":11,"surah":5,"verses":[2],"references":[{"surah":5,"verses":[2]}],"verseLabel":"المائدة: 2","question":"ما دلالة تكرار نداء المؤمنين في أول الآية الثانية بعد وروده في الآية الأولى؟","answer":"جُدد نداء المؤمنين تنبيهًا لهم واستنهاضًا لعزائمهم وتذكيرًا بما ألزمهم الإيمان من طاعة الله، لئلا يحملهم ما سبق من صدّ المشركين على انتهاك الشعائر والاعتداء","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص509، تحت «سر تكرار عبارة النداء بقوله: ﴿يا أيها الذين آمنوا﴾ في هذه الآية وسابقتها»","url":""}]},{"id":"s5-12","number":12,"surah":5,"verses":[2],"references":[{"surah":5,"verses":[2]}],"verseLabel":"المائدة: 2","question":"ما الصورة في قوله تعالى: ﴿لا تحلوا شعائر الله﴾؟","answer":"استُعير الإحلال لانتهاك الشعائر؛ فصُورت حرمتها بشيء مربوط يُفكّ، وحلُّ هذا الرباط يصور استباحة ما وجب صونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص510، تحت «الاستعارة ودلالتها في قوله تعالى: ﴿لا تحلوا شعائر الله﴾»","url":""}]},{"id":"s5-13","number":13,"surah":5,"verses":[2],"references":[{"surah":5,"verses":[2]}],"verseLabel":"المائدة: 2","question":"ما دلالة إضافة الشعائر إلى اسم الله في قوله تعالى: ﴿شعائر الله﴾؟","answer":"أضيفت الشعائر إلى اسم الله لتشريفها وتعظيمها، وللتهويل من استباحتها أو التهاون بحرمتها","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص509–510، تحت «إضافة الشعائر إلى لفظ الجلالة للتشريف، في قوله تعالى: ﴿شعائر الله﴾»","url":""}]},{"id":"s5-14","number":14,"surah":5,"verses":[2],"references":[{"surah":5,"verses":[2]}],"verseLabel":"المائدة: 2","question":"لماذا خُص الهدي بالذكر بعد النهي العام عن إحلال شعائر الله؟","answer":"هو تخصيص بعد تعميم لتشريف الهدي وزيادة العناية به؛ فهو من أعظم الشعائر، وفيه نفع للناس وبذل لما تضن به النفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص510–511، تحت عنوان «سر تخصيص قوله ﴿ولا الهدي﴾ بالذكر في الآية الكريمة»","url":""}]},{"id":"s5-15","number":15,"surah":5,"verses":[2],"references":[{"surah":5,"verses":[2]}],"verseLabel":"المائدة: 2","question":"ما سرّ إسناد الإحلال إلى ﴿الشهر الحرام﴾ مع أن المقصود انتهاك حرمته؟","answer":"أُطلق الشهر وأريد القتال الواقع فيه، فعبر بالمحل عن الحالّ فيه على سبيل المجاز المرسل؛ والمقصود النهي عن استحلال القتال في الزمن الحرام.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص510، تحت «دلالة المجاز المرسل في قوله تعالى: ﴿ولا الشهر الحرام﴾»","url":""}]},{"id":"s5-16","number":16,"surah":5,"verses":[2],"references":[{"surah":5,"verses":[2]}],"verseLabel":"المائدة: 2","question":"ما مناسبة تخصيص ﴿القلائد﴾ بالذكر بعد ﴿الهدي﴾ وهي منه؟","answer":"القلائد العلامة الظاهرة التي يعرف بها الهدي فيأمن، وتخصيصها بعد عموم الهدي يشدد حرمة ما ظهر شعاره حتى لا يُعتدى عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص511–512، تحت «التخصيص بعد التعميم، في قوله: ﴿ولا الهدي ولا القلائد﴾»","url":""}]},{"id":"s5-17","number":17,"surah":5,"verses":[2],"references":[{"surah":5,"verses":[2]}],"verseLabel":"المائدة: 2","question":"لماذا قيل ﴿ولا آمين البيت الحرام﴾، ولم يقل: ولا قاصدي مكة؟","answer":"لأن مكة قد تُقصد لتجارة ونحوها، أما ذكر البيت الحرام فيدل على قصد الحج، ويستحضر حرمة البيت وحرمة قاصديه؛ فناسب النهي عن التعرض لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص512–513، تحت «قوله: ﴿ولا آمين البيت الحرام﴾، دون أن يقول: ولا آمين مكة؟»","url":""}]},{"id":"s5-18","number":18,"surah":5,"verses":[2],"references":[{"surah":5,"verses":[2]}],"verseLabel":"المائدة: 2","question":"كيف يُفهم ابتغاء الرضوان في قوله تعالى: ﴿يبتغون فضلًا من ربهم ورضوانًا﴾ مع دخول المشركين في قاصدي البيت زمن النزول؟","answer":"من أوجه التفسير أن المشركين كانوا يقصدون بحجهم ابتغاء رضوان الله، أو يظنون أنهم ينالونه؛ فالعبارة تحكي ما يطلبونه وما يزعمونه، ولا تقتضي حصول الرضوان لهم مع شركهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص514، تحت عنوان «دلالة الرضوان في قول الرحمن: ﴿يبتغون فضلًا من ربهم ورضوانًا﴾»","url":""}]},{"id":"s5-19","number":19,"surah":5,"verses":[2],"references":[{"surah":5,"verses":[2]}],"verseLabel":"المائدة: 2","question":"ما دلالة الأمر في قوله تعالى: ﴿وإذا حللتم فاصطادوا﴾؛ أهو للوجوب؟","answer":"الأمر بعد حظر الصيد حال الإحرام يرفع المنع ويعيد الإباحة، ولا يوجب الصيد؛ فالسياق صرف صيغة الأمر من الطلب إلى الإذن.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص515–516، تحت «الغرض من الأمر في قوله: ﴿فاصطادوا﴾ غايته التيسير»","url":""}]},{"id":"s5-20","number":20,"surah":5,"verses":[2],"references":[{"surah":5,"verses":[2]}],"verseLabel":"المائدة: 2","question":"لماذا استُعمل ﴿يجرمنكم﴾ في النهي عن أثر البغض في الاعتداء؟","answer":"اختير لفظ «جرم» مع مقاربته معنى الكسب لزيادة التنفير من الاعتداء على قاصدي البيت؛ فهو يصله بمعنى الجريمة ويشدد الزجر عن أن يحمل البغض على العدوان.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص518، تحت «إيثار التعبير بلفظ (جرم) على (كسب) في قوله ﴿ولا يجرمنكم شنآن قوم﴾»","url":""}]},{"id":"s5-21","number":21,"surah":5,"verses":[2,8],"references":[{"surah":5,"verses":[2,8]}],"verseLabel":"المائدة: 2، 8","question":"لماذا حُذفت «على» في ﴿أن تعتدوا﴾، وأُثبتت في ﴿على ألا تعدلوا﴾؟","answer":"الأولى تنهى عن اعتداء ناشئ عن واقعة الصد عن المسجد الحرام، أما الثانية فتقرر النهي العام المستمر عن ترك العدل؛ فجاء إثبات «على» في الثانية لزيادة التأكيد، لأن حكمها أعم وأشمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص523–524، تحت «من متشابه النظم»","url":""}]},{"id":"s5-22","number":22,"surah":5,"verses":[2],"references":[{"surah":5,"verses":[2]}],"verseLabel":"المائدة: 2","question":"ما مناسبة الانتقال من أحكام الحج والصيد إلى قوله تعالى: ﴿وتعاونوا على البر والتقوى ولا تعاونوا على الإثم والعدوان﴾؟","answer":"بعد النهي عن الانتقام ممن صدوا المؤمنين عمّم المبدأ: تكون المعاملة تعاونًا على الخير وصيانة الحدود، لا تعاونًا على المعصية والاعتداء؛ فارتقى من الواقعة إلى قاعدة اجتماعية شاملة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص519–520، تحت «علاقة جملة ﴿وتعاونوا على البر والتقوى﴾ بما قبلها»","url":""}]},{"id":"s5-23","number":23,"surah":5,"verses":[2],"references":[{"surah":5,"verses":[2]}],"verseLabel":"المائدة: 2","question":"ما دلالة الجمع بين ﴿البر والتقوى﴾ ومقابلتهما بـ﴿الإثم والعدوان﴾؟","answer":"قابل الأمر بالتعاون على الخير والتقوى بالنهي عن التعاون على ما يفسد صاحبه أو يعتدي به على غيره. فاجتمع الحث على تبادل المعونة والإحسان مع منع التعاون على وجوه الفساد، وقوّت المقابلة المعنى أمرًا ونهيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص521، تحت عنوان «بلاغة المقابلة في قوله تعالى: ﴿وتعاونوا على البر والتقوى ولا تعاونوا على الإثم والعدوان﴾»","url":""}]},{"id":"s5-24","number":24,"surah":5,"verses":[2],"references":[{"surah":5,"verses":[2]}],"verseLabel":"المائدة: 2","question":"ما دلالة تقديم ﴿الإثم﴾ على ﴿العدوان﴾؟","answer":"قُدّم الإثم لعمومه وشموله، ولأنه طريق إلى العدوان؛ فمن لم يمتنع عن معصية الله لم يردعه ذلك عن الاعتداء على الناس. فالنهي يتناول أصل المخالفة ثم ما يتعدى ضرره إلى الغير.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص521–522، تحت «النكتة في تقديم الإثم على العدوان، مع كونهما معًا ضررًا ومفسدة»","url":""}]},{"id":"s5-25","number":25,"surah":5,"verses":[2],"references":[{"surah":5,"verses":[2]}],"verseLabel":"المائدة: 2","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿إن الله شديد العقاب﴾؟","answer":"لما كثرت النواهي عن انتهاك الشعائر والاعتداء والتعاون على الإثم جاءت الخاتمة زجرًا يضمن جدية الحدود؛ فمن خالفها فالله شديد العقاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص522، تحت «وجه ارتباط التذييل في قوله: ﴿إن الله شديد العقاب﴾ بما قبله»","url":""}]},{"id":"s5-26","number":26,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"ما سرّ بناء ﴿حرمت عليكم الميتة﴾ للمفعول في المائدة، وبناء ﴿إنما حرم عليكم الميتة﴾ للفاعل في البقرة؟","answer":"يبين المصدر أن بناء الفعل للمفعول في المائدة يناسب علم المؤمنين بأن المحرِّم هو الله وحده. أما البناء للفاعل في البقرة فيناسب الرد على من ينسب التحليل والتحريم إلى علمائه؛ لتقرير أن التحريم حق لله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص535، تحت عنوان «سر التعبير بالبناء للفاعل في موضع البقرة في قوله: ﴿إنما حرم﴾، وبالبناء للمفعول في موضع المائدة»","url":""}]},{"id":"s5-27","number":27,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"ما سرّ التعبير بقوله تعالى: ﴿حرمت عليكم الميتة﴾ مع أن المقصود أكلها؟","answer":"التحريم يتعلق بأفعال المكلفين، والتقدير: حُرّم عليكم أكل الميتة؛ فحُذف المضاف وأقيمت الميتة مقامه، اعتمادًا على فهم الفعل المقصود من السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص531، تحت «دلالة حذف المضاف وإقامة المضاف إليه مقامه في قوله ﴿حرمت عليكم الميتة﴾»","url":""}]},{"id":"s5-28","number":28,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"لماذا خُص لحم الخنزير بالذكر في المحرمات؟","answer":"اللحم معظم ما يؤكل من الحيوان، وسائر أجزائه تابعة له في الحكم. وخُص لحم الخنزير بالذكر زيادةً في التغليظ على من اعتاد أكله، مع شمول التحريم لسائر أجزائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص534، تحت «دلالة ذكر اللحم وإضافته إلى الخنزير في الآية الكريمة»","url":""}]},{"id":"s5-29","number":29,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"ما سرّ تقديم ﴿لغير الله﴾ في قوله تعالى في المائدة: ﴿وما أهل لغير الله به﴾، وتأخيره في البقرة: ﴿وما أهل به لغير الله﴾؟","answer":"في البقرة كان المقام مقام الرزق والطعام، فقُدم ﴿به﴾ العائد إلى المذبوح؛ أما المائدة فمقامها بيان من يملك التحليل والتحريم وإبطال من يجعله لغير الله، فقُدم ﴿لغير الله﴾ لأنه موضع العناية.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص536، تحت عنوان «السر في تقديم الجار والمجرور ﴿به﴾ على ﴿لغير الله﴾ في قوله: ﴿وما أهل به لغير الله﴾، وسر تأخيره في آية المائدة في قوله: ﴿وما أهل لغير الله به﴾»","url":""}]},{"id":"s5-30","number":30,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"ما مناسبة تفصيل المنخنقة والموقوذة والمتردية والنطيحة بعد دخولها في عموم الميتة؟","answer":"فُصّلت هذه الصور بعد عموم الميتة لأنها كانت معروفةً مأكولةً في الجاهلية، ولئلا يظن أحد إباحة بعضها؛ فبيّن أنها داخلة في حكم الميتة","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص532، تحت «دلالة عطف قوله تعالى ﴿والمنخنقة والموقوذة والمتردية والنطيحة وما أكل السبع إلا ما ذكيتم﴾ على الميتة»","url":""}]},{"id":"s5-31","number":31,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"ما وجه الإيجاز في قوله تعالى: ﴿وما أكل السبع﴾ مع أن الحكم يتعلق بما بقي من الفريسة؟","answer":"التقدير: وما أكل منه السبع؛ فحُذف الجار والمجرور «منه» إيجازًا. أما الجزء الذي أكله السبع فقد ذهب، وإنما يتعلق الحكم بما بقي من الفريسة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص538، تحت عنوان «بلاغة الإيجاز والمجاز في قوله: ﴿وما أكل السبع﴾»","url":""}]},{"id":"s5-611","number":611,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"ما دلالة نسبة الأكل إلى السبع في قوله تعالى: ﴿وما أكل السبع﴾ دون التعبير بالافتراس؟","answer":"المراد ما افترسه السبع فأماته، سواء أكل منه أم لم يأكل؛ لأنه افترسه ليأكله. ففي التعبير مجاز مرسل أُطلق فيه الأكل، وهو الغاية المسببة للافتراس، وأريد الافتراس الذي أفضى إلى موت الفريسة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص539، تحت عنوان «دلالة نسبة الأكل إلى السبع دون الافتراس في قوله: ﴿وما أكل السبع﴾»","url":""}]},{"id":"s5-32","number":32,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"ما سرّ التعبير بقوله تعالى: ﴿إلا ما ذكيتم﴾، دون: إلا ما ذبحتم؟","answer":"التذكية إتمام الذبح الشرعي الذي تطيب به الذبيحة، وهي أوسع وأدق من مجرد إحداث الذبح؛ لأنها تقيد الاستثناء بإدراك الحيوان حيًا واستيفاء التذكية.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص540–541، تحت «سر التعبير بقوله ﴿إلا ما ذكيتم﴾ دون إلا ما ذبحتم»","url":""}]},{"id":"s5-33","number":33,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"ما مناسبة ذكر ﴿وما ذبح على النصب﴾ بعد قوله تعالى: ﴿وما أهل لغير الله به﴾؟","answer":"ما أُهل لغير الله به يلحظ الاسم المقصود عند الذبح، وما ذبح على النصب يلحظ المكان والشعيرة الوثنية ولو لم يسم اسم الصنم؛ فذكرهما يسد طريقي الشرك في القصد والمشهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص543، تحت «سر عطف قوله ﴿وما ذبح على النصب﴾ على قوله ﴿وما أهل لغير الله به﴾»","url":""}]},{"id":"s5-34","number":34,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"ما مناسبة إدخال الاستقسام بالأزلام في سياق المطعومات المحرمة؟","answer":"من وجوه اتصالها بالسياق أن الاستقسام كان يجري في تقسيم لحم الجزور بالميسر؛ فبعد بيان المحرم من الأطعمة نُهي عن طريقة محرمة في تحصيله وتقسيمه. ويعرض المصدر أيضًا وجهًا يربط العطف بإبطال خرافات الجاهلية في طلب معرفة ما قُسم لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص545، تحت عنوان «دلالة عطف قوله: ﴿وأن تستقسموا بالأزلام﴾ على ما قبله»","url":""}]},{"id":"s5-35","number":35,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"إلام يعود اسم الإشارة المفرد في قوله تعالى: ﴿ذلكم فسق﴾ بعد المذكورات المتعددة؟","answer":"يجوز أن يعود إلى الاستقسام بالأزلام خاصة، ويجوز أن يعود إلى جميع ما تقدم بتقدير: تناول هذه المحرمات فسق؛ فالإفراد باعتبار ذلك المقدر","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص548، تحت «نكتة التعبير باسم الإشارة في قوله تعالى ﴿ذلكم فسق﴾»","url":""}]},{"id":"s5-36","number":36,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"ما سرّ وصف المذكور بقوله تعالى: ﴿ذلكم فسق﴾، دون الاكتفاء بوصفه بالحرام؟","answer":"الفسق خروج عن طاعة الله، وهو يلائم الاستقسام والنصب لما فيهما من شعيرة جاهلية وتمرد على حكم الله؛ فليس الحكم منعًا فقهيًا مجردًا بل انحرافًا عقديًا وعمليًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص549، تحت «سر وصف الوقوع في المحرمات بالفسق في قوله ﴿ذلكم فسق﴾»","url":""}]},{"id":"s5-37","number":37,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"ما مناسبة مجيء قوله تعالى: ﴿اليوم يئس الذين كفروا من دينكم﴾ وسط أحكام المطعومات؟","answer":"جاءت الجملة اعتراضًا يؤكد حكم المحرمات ويعين على تقبله؛ فذكّرت المؤمنين بأن هذه الأحكام إكمال لدينهم وإصلاح لحالهم، وقد انقطع طمع الكافرين في إبطاله. فاجتمع التشديد في الحكم مع التبشير والامتنان.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص549–550، تحت «دلالة موقع قوله تعالى ﴿اليوم يئس الذين كفروا من دينكم فلا تخشوهم واخشون﴾ بين آية المحرمات وآية الرخصة»","url":""}]},{"id":"s5-38","number":38,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"ما دلالة حذف ياء المتكلم في قوله تعالى: ﴿واخشون﴾؟","answer":"يربط المصدر إثبات الياء في البقرة بشدة الملابسات التي دعت إلى التحذير من خشية الناس. أما هنا فقد ظهرت قوة المسلمين وضعف موجب خشية الكافرين، فناسب ذلك حذف الياء في ﴿واخشون﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص553–554، تحت «سر إثبات الياء في ﴿واخشوني﴾ في آية البقرة، وحذفها في موضعي المائدة»","url":""}]},{"id":"s5-39","number":39,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"ما دلالة تكرار ﴿اليوم﴾ في قوله تعالى: ﴿اليوم يئس﴾ ثم ﴿اليوم أكملت﴾؟","answer":"أعيد لفظ «اليوم» لتعداد المنن وإبراز كل منها نعمة مستقلة: يأس الكافرين وعدم خشيتهم، ثم إكمال الدين وإتمام النعمة وارتضاء الإسلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص556–557، تحت «دلالة إعادة لفظ ﴿اليوم﴾ في قوله ﴿اليوم أكملت لكم دينكم﴾»","url":""}]},{"id":"s5-40","number":40,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"ما سرّ التعبير بقوله تعالى: ﴿أكملت لكم دينكم﴾، دون: أكملت ديني؟","answer":"أضيف الدين إلى المخاطبين لترغيبهم في تحمّل تكاليفه وتبعاته والذبّ عن حياضه؛ فهو دينهم الذي أكمله الله لهم وارتضاه، وهم القائمون به","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص557، تحت «سر إضافة الدين إلى المخاطبين في قوله تعالى ﴿اليوم أكملت لكم دينكم﴾»","url":""}]},{"id":"s5-41","number":41,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"ما الفرق بين الإكمال في قوله تعالى: ﴿أكملت لكم دينكم﴾، والإتمام في قوله: ﴿وأتممت عليكم نعمتي﴾؟","answer":"الإكمال يلحظ بلوغ الدين كماله وخلوه من النقص والخلل، والإتمام يلحظ استيفاء النعمة أجزائها وأسبابها حتى تبلغ تمامها؛ فاختلاف الفعلين يلائم اختلاف جهة وصف الدين والنعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص559–560، تحت عنوان «الفرق بين الكمال والتمام في قوله: ﴿اليوم أكملت لكم دينكم وأتممت عليكم نعمتي﴾»","url":""}]},{"id":"s5-42","number":42,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"ما دلالة تعدية ﴿أكملت﴾ باللام في قوله تعالى: ﴿أكملت لكم دينكم﴾؟","answer":"اللام تدل على اختصاص المخاطبين بهذا الكمال، وتبرز كمال عناية الله بالمؤمنين؛ فقد تولى سبحانه إكمال الدين لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص557–558، تحت عنوان «دلالة تعدية الفعل ﴿أكملت﴾ بحرف اللام في قوله: ﴿أكملت لكم﴾»","url":""}]},{"id":"s5-612","number":612,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"ما دلالة تعدية ﴿أتممت﴾ بحرف ﴿على﴾ في قوله تعالى: ﴿وأتممت عليكم نعمتي﴾؟","answer":"يفيد الحرف معنى الاستعلاء، فيشير إلى علو هذه النعمة وأنها محض فضل من الله، وإلى شمولها للمخاطبين وإحاطتها بهم من كل جانب.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص558، تحت عنوان «دلالة تعدية الفعل ﴿وأتممت﴾ في قوله تعالى: ﴿وأتممت عليكم نعمتي﴾ بحرف (على)»","url":""}]},{"id":"s5-43","number":43,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"لماذا أضيفت النعمة إلى الله في قوله ﴿وأتممت عليكم نعمتي﴾؟","answer":"أضيفت إليه لتشريفها والتذكير بأنه وليّها ومسديها؛ فهو الذي أتمها عليهم منّةً وتفضلًا. فتستحضر الإضافة عظمة العطاء ومصدره.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص557، تحت «دلالة إضافة النعمة إليه سبحانه في قوله ﴿وأتممت عليكم نعمتي﴾»","url":""}]},{"id":"s5-44","number":44,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"ما دلالة تقديم ﴿لكم﴾ في قوله تعالى: ﴿ورضيت لكم الإسلام دينًا﴾؟","answer":"التقديم يفيد الاختصاص؛ فقد اختار الله لهذه الأمة الإسلام دينًا، وخصها بهذا الوصف. فيبرز موقع «لكم» عنايته بالمخاطبين وما اختاره لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص561، تحت «دلالة تقديم الجار والمجرور ﴿لكم﴾ في قوله ﴿ورضيت لكم الإسلام دينًا﴾»","url":""}]},{"id":"s5-45","number":45,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"ما مناسبة العودة إلى حكم المضطر في المخمصة بعد إعلان كمال الدين؟","answer":"لما تمت الجمل الاعتراضية عاد السياق إلى تتمة أحكام المحرمات، فذكر رخصة المضطر؛ وبذلك اتصل ما بعد الاعتراض بما قبله","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص561، تحت «مناسبة قوله تعالى ﴿فمن اضطر﴾ لما قبلها»","url":""}]},{"id":"s5-46","number":46,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"ما سرّ التعبير عن شدة الجوع بـ﴿مخمصة﴾؟","answer":"المخمصة المجاعة الشديدة التي تخمص فيها البطون، أي تضمر وتلتصق من الجوع؛ فاللفظ يصور أثر الضرورة في الجسد ولا يدل على جوع عادي.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص563، تحت «سر التعبير بالمخمصة دون الجوع في قوله ﴿فمن اضطر في مخمصة﴾»","url":""}]},{"id":"s5-47","number":47,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"ما الصورة في قوله تعالى: ﴿غير متجانف لإثم﴾؟","answer":"التجانف هو الميل؛ فالقيد يصور المضطر غير مائل إلى المحرم ميل المتشهي المستطيب، وإنما يأخذ منه عند خوف الهلاك بقدر ما يحفظ حياته","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص563–564، تحت «دلالة التعبير بقوله ﴿غير متجانف لإثم﴾»","url":""}]},{"id":"s5-48","number":48,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"ما مناسبة ختم حكم المضطر بقوله تعالى: ﴿فإن الله غفور رحيم﴾ مع أنه غير متعمد للمعصية؟","answer":"الخاتمة تطمئن المضطر وتؤكد رفع الحرج والإثم عنه في تناوله المحرم على الوجه المرخَّص فيه؛ فالمغفرة والرحمة هنا متصلتان بالتيسير عليه وحفظ حياته.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص564، تحت عنوان «دلالة الصيغة في صفتي المغفرة والرحمة في قوله: ﴿فإن الله غفور رحيم﴾»","url":""}]},{"id":"s5-49","number":49,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"كيف ترتبط صور الميتة المفصلة في المائدة بالمحرمات المجملة في الأنعام؟","answer":"صور المنخنقة والموقوذة والمتردية والنطيحة وما أكل السبع داخلة في جنس الميتة؛ فذكرها في المائدة تفصيل لما أجمل في الأنعام، وليس مجرد زيادة عدد الأسماء دليلًا على اختلاف الأصول المحرمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص373–374، تحت «الحصر المستفاد من النفي والاستثناء»","url":""}]},{"id":"s5-50","number":50,"surah":5,"verses":[4],"references":[{"surah":5,"verses":[4]}],"verseLabel":"المائدة: 4","question":"ما مناسبة سؤالهم: ﴿ماذا أحل لهم﴾ بعد تفصيل المحرمات؟","answer":"لما سمعوا تفصيل المحرمات توجهت نفوسهم إلى معرفة ما أُحل لهم، فجاء السؤال والجواب انتقالًا من بيان حدود المنع إلى بيان المباح.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص568، تحت عنوان «دلالة فصل جملة ﴿يسألونك ماذا أحل لهم﴾ عن الآية قبلها»","url":""}]},{"id":"s5-51","number":51,"surah":5,"verses":[4],"references":[{"surah":5,"verses":[4]}],"verseLabel":"المائدة: 4","question":"ما دلالة إعادة الفعل في الجواب: ﴿قل أحل لكم الطيبات﴾؟","answer":"تكرار الفعل يقرر أن التحليل والتحريم أمر شرعي يُتلقى من الله، وفيه امتنان وإعلام بأن ما أحله هو الطيب دون غيره؛ فيبطل جعل أهواء الناس معيارًا للحل والحرمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص570، تحت «دلالة تكرار الفعل ﴿أحل﴾ في قوله ﴿يسألونك ماذا أحل لهم قل أحل لكم الطيبات﴾»","url":""}]},{"id":"s5-52","number":52,"surah":5,"verses":[4],"references":[{"surah":5,"verses":[4]}],"verseLabel":"المائدة: 4","question":"لماذا عُبّر عن الحلال بقوله تعالى ﴿الطيبات﴾؟","answer":"أصل الطيب الطهارة والزكاء وحسن الأثر؛ فوصف الأطعمة به يشير إلى حسنها وسلامتها من المضرة، ويبين علة تحليلها، كما يدل على أن ضد الحلال هنا هو الخبيث.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص571، تحت عنوان «دلالة التعبير عن الحلال بالطيبات في قوله: ﴿قل أحل لكم الطيبات﴾»","url":""}]},{"id":"s5-53","number":53,"surah":5,"verses":[4],"references":[{"surah":5,"verses":[4]}],"verseLabel":"المائدة: 4","question":"ما سرّ تسمية حيوانات الصيد المدرَّبة ﴿الجوارح﴾؟","answer":"الجوارح من الجرح بمعنى الكسب، لأنها تكسب الصيد لصاحبها، ومن الجرح الحسي لأنها تمسكه بمخالبها أو أنيابها؛ فجمع الاسم فعلها وأثرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص571–572، تحت «دلالة تسمية الكواسب من السباع ونحوها بالجوارح»","url":""}]},{"id":"s5-54","number":54,"surah":5,"verses":[4],"references":[{"surah":5,"verses":[4]}],"verseLabel":"المائدة: 4","question":"ما سرّ التعبير بقوله تعالى: ﴿مكلبين﴾ مع دخول جوارح من الطير في الحكم؟","answer":"التكليب تعليم الجوارح الصيد، واشتق من الكلب لأنه أشهر ما يدرب عليه وأكثره استعمالًا؛ فغلب اسمه على مهنة التعليم مع شمول الحكم لغيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص572، تحت عنوان «دلالة التعبير بالمكلب دون المعلم»","url":""}]},{"id":"s5-55","number":55,"surah":5,"verses":[4],"references":[{"surah":5,"verses":[4]}],"verseLabel":"المائدة: 4","question":"ما دلالة قوله تعالى: ﴿تعلمونهن مما علمكم الله﴾؟","answer":"ترد الجملة العلم إلى منحة الله؛ فطرائق تعليم الجوارح إلهام منه، أو معرفة مكتسبة بالعقل الذي منحه للإنسان، أو بما عرّفه من علامات الجارحة المعلَّمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص573، تحت «بلاغة الفصل في قوله تعالى ﴿تعلمونهن مما علمكم الله﴾»","url":""}]},{"id":"s5-56","number":56,"surah":5,"verses":[4],"references":[{"surah":5,"verses":[4]}],"verseLabel":"المائدة: 4","question":"ما سرّ تعدية الإمساك بـ﴿على﴾ في قوله تعالى: ﴿مما أمسكن عليكم﴾، دون: لكم؟","answer":"عُدي الإمساك بـ﴿على﴾ للإيحاء بما على صاحب الجارحة من تبعة ومسؤولية في التحقق من شروط الحل، كالتسمية وكون الجارحة معلمة وألا تمسك الصيد لنفسها؛ بخلاف اللام التي قد توهم مجرد الاختصاص والإباحة بلا قيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص574، تحت «سر العدول عن اللام إلى على في ﴿فكلوا مما أمسكن عليكم﴾»","url":""}]},{"id":"s5-57","number":57,"surah":5,"verses":[4],"references":[{"surah":5,"verses":[4]}],"verseLabel":"المائدة: 4","question":"ما الذي أفاده التعبير بالضمير في ﴿واذكروا اسم الله عليه﴾؟","answer":"أوجز الضمير وأتاح أكثر من مرجع في السياق؛ فيجوز رده إلى إرسال الجوارح على الصيد، فتكون التسمية عند الإرسال، أو إلى ما أمسكن، فتكون عند إدراك ذكاة المصيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص576، تحت «بلاغة التعبير بالضمير في عليه بدلًا من الظاهر»","url":""}]},{"id":"s5-58","number":58,"surah":5,"verses":[4],"references":[{"surah":5,"verses":[4]}],"verseLabel":"المائدة: 4","question":"ما مناسبة ختم أحكام الصيد بقوله تعالى: ﴿إن الله سريع الحساب﴾؟","answer":"ختمت الآية بسرعة الحساب للتخويف من التساهل في شروط الصيد؛ فالله يعلم حقيقة التذكية وما يخفى من أحوالها، ويجازي المحسن ويعاقب المسيء","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص577، تحت «سر التعبير بقوله ﴿سريع الحساب﴾ خلافًا لفاصلة الآية السابقة»","url":""}]},{"id":"s5-59","number":59,"surah":5,"verses":[5],"references":[{"surah":5,"verses":[5]}],"verseLabel":"المائدة: 5","question":"ما دلالة تكرار قوله تعالى: ﴿اليوم أحل لكم الطيبات﴾ بعد قوله: ﴿قل أحل لكم الطيبات﴾؟","answer":"أعيد حكم الحل للتأكيد والتوطئة لما بعده من إباحة طعام أهل الكتاب، مع تعداد نعم الله والامتنان بسعة ما أباح للمؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص584، تحت عنوان «دلالة إعادة حكم حل الطيبات في قوله تعالى: ﴿اليوم أحل لكم الطيبات﴾»","url":""}]},{"id":"s5-60","number":60,"surah":5,"verses":[5],"references":[{"surah":5,"verses":[5]},{"surah":9,"verses":[29]}],"verseLabel":"المائدة: 5؛ التوبة: 29","question":"لماذا قيل في إباحة الطعام: ﴿وطعام الذين أوتوا الكتاب حل لكم﴾، دون الاكتفاء بقول: طعام أهل الكتاب؟","answer":"يشير الوصف إلى من يدينون بالتوراة والإنجيل ويعرفون كتابهم؛ فلا يكفي مجرد الانتساب إلى أهل الكتاب ممن لا يعرفون دينهم ولا يدينون به.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص584، تحت عنوان «دلالة التعبير بـ﴿أوتوا الكتاب﴾ دون أهل الكتاب في قوله: ﴿وطعام الذين أوتوا الكتاب﴾»","url":""}]},{"id":"s5-613","number":613,"surah":5,"verses":[5],"references":[{"surah":5,"verses":[5]},{"surah":9,"verses":[29]}],"verseLabel":"المائدة: 5؛ التوبة: 29","question":"ما دلالة التذكير بإيتاء الكتاب بعد قوله في التوبة: ﴿ولا يدينون دين الحق﴾؟","answer":"في بيان أنهم أوتوا الكتاب تشديد للذم؛ فقد جاءهم الكتاب الهادي إلى الحق، ثم نبذوا دين الحق الذي جاءتهم به كتبهم. فالتذكير بما عرفوه يزيد تقبيح مخالفتهم له.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص101، تحت عنوان «سر البيان في قوله: ﴿من الذين أوتوا الكتاب﴾»","url":""}]},{"id":"s5-614","number":614,"surah":5,"verses":[5],"references":[{"surah":5,"verses":[5]},{"surah":9,"verses":[29]}],"verseLabel":"المائدة: 5؛ التوبة: 29","question":"لماذا قُيّد المذكورون في آية التوبة بوصف ﴿من الذين أوتوا الكتاب﴾؟","answer":"يميّز الوصف أهل الكتاب من المشركين في الحكم المذكور في الآية؛ فإيتاؤهم الكتاب وصف له أثر في نوع المعاملة، وليس مجرد تسمية للجماعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص102، تحت عنوان «سر التعبير والتقييد بقوله: ﴿أوتوا الكتاب﴾، دون: (أهل الكتاب)»","url":""}]},{"id":"s5-61","number":61,"surah":5,"verses":[5],"references":[{"surah":5,"verses":[5]}],"verseLabel":"المائدة: 5","question":"ما دلالة قوله تعالى: ﴿وطعامكم حل لهم﴾ مع أن المقصود بيان ما يحل للمؤمنين؟","answer":"تقرر الجملة جواز إطعام المسلمين أهلَ الكتاب من طعامهم، بعد بيان حل طعام أهل الكتاب لهم؛ فتكتمل الإباحة من الجانبين، ويتجلى تيسير المعاملة والمخالطة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص585، تحت «دلالة عطف ﴿وطعامكم حل لهم﴾ على ما قبلها»","url":""}]},{"id":"s5-62","number":62,"surah":5,"verses":[5],"references":[{"surah":5,"verses":[5]}],"verseLabel":"المائدة: 5","question":"ما سرّ التعبير بالمصدر في قوله تعالى: ﴿حل لكم﴾، دون: أحل لكم؟","answer":"في التعبير بالمصدر توكيد ومبالغة لإزالة توهم التحريم؛ فقد يتردد المؤمن في طعام أهل الكتاب بعد سماع ما سبق من أحكام المنع، فجاء ﴿حل لكم﴾ تقريرًا قويًا للإباحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص585، تحت «سر العدول عن الفعل أحل إلى المصدر حل»","url":""}]},{"id":"s5-63","number":63,"surah":5,"verses":[5],"references":[{"surah":5,"verses":[5]}],"verseLabel":"المائدة: 5","question":"ما مناسبة الجمع في آية واحدة بين طعام أهل الكتاب والزواج من نسائهم؟","answer":"عُطف حكم الطعام وحكم النكاح على تحليل الطيبات بالواو، مع استقلال كل حكم بمعناه؛ فالعطف يجمع بيان الإباحة في السياق دون أن يزيل ما يختص به كل حكم من قيود.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص586–587، تحت عنوان «سر عطف تبادل الأطعمة ومنكوحات أهل الكتاب على تحليل الطيبات بالواو»","url":""}]},{"id":"s5-64","number":64,"surah":5,"verses":[5],"references":[{"surah":5,"verses":[5]}],"verseLabel":"المائدة: 5","question":"لماذا ذُكرت ﴿المحصنات من المؤمنات﴾ قبل محصنات أهل الكتاب مع أن حل المؤمنات معلوم؟","answer":"جاء ذكر المؤمنات توطئة وتمهيدًا لذكر محصنات أهل الكتاب، وإلحاقهن بهن في حكم الحل.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص586، تحت عنوان «بلاغة الإيجاز في قوله: ﴿والمحصنات من المؤمنات﴾»","url":""}]},{"id":"s5-615","number":615,"surah":5,"verses":[5],"references":[{"surah":5,"verses":[5]}],"verseLabel":"المائدة: 5","question":"ما دلالة تخصيص المحصنات بوصف ﴿من المؤمنات﴾ مع إباحة محصنات أهل الكتاب بعدها؟","answer":"يوضح المصدر أن تخصيصهن بوصف الإيمان هنا مسوق لبيان الأفضلية، وليس لنفي حل الكتابيات؛ فقد نص السياق نفسه على إباحتهن.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص586–587، تحت عنوان «سر عطف تبادل الأطعمة ومنكوحات أهل الكتاب على تحليل الطيبات بالواو»","url":""}]},{"id":"s5-65","number":65,"surah":5,"verses":[5],"references":[{"surah":5,"verses":[5]}],"verseLabel":"المائدة: 5","question":"ما سرّ تقييد حل الزواج بقوله تعالى: ﴿المحصنات﴾، دون: نساء الذين أوتوا الكتاب؟","answer":"قُيد الحل بالمحصنات لأن الإحصان من المنعة، والمراد هنا الحرائر العفيفات؛ فالإباحة متعلقة بمن اجتمع فيها وصف الحرية والعفة، لا بمجرد الانتساب إلى أهل الكتاب","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص586، تحت «بلاغة الإيجاز في قوله ﴿والمحصنات من المؤمنات﴾»","url":""}]},{"id":"s5-66","number":66,"surah":5,"verses":[5],"references":[{"surah":5,"verses":[5]}],"verseLabel":"المائدة: 5","question":"لماذا قيل ﴿إذا آتيتموهن أجورهن﴾ بـ«إذا» دون «إن»؟","answer":"جاءت «إذا» لتأكيد إيتاء المهر، لأن أداء هذا الحق مما ينبغي تحققه؛ أما «إن» فقد توهم تعليق الوفاء به على أمر مشكوك فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص587، تحت «سر التعبير بإذا دون إن في قوله ﴿إذا آتيتموهن أجورهن﴾»","url":""}]},{"id":"s5-67","number":67,"surah":5,"verses":[5],"references":[{"surah":5,"verses":[5]}],"verseLabel":"المائدة: 5","question":"ما سرّ تسمية المهور في قوله تعالى: ﴿إذا آتيتموهن أجورهن﴾؟","answer":"شُبّه المهر بالأجر من جهة كونه عوضًا ماليًا عن المنافع المترتبة على عقد النكاح؛ فالتعبير يقرب معنى استحقاقه ويؤكد وجوب أدائه، مع اختلاف عقد النكاح عن الإجارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص587، تحت «دلالة تسمية المهور أجورًا في قوله ﴿إذا آتيتموهن أجورهن﴾»","url":""}]},{"id":"s5-68","number":68,"surah":5,"verses":[5],"references":[{"surah":5,"verses":[5]}],"verseLabel":"المائدة: 5","question":"ما الفرق بين السفاح واتخاذ الأخدان في قوله تعالى: ﴿محصنين غير مسافحين ولا متخذي أخدان﴾؟","answer":"السفاح هنا المجاهرة بالزنا، واتخاذ الأخدان إسراره مع صديق أو صديقة؛ فنفى التعبير الفاحشة في صورتها الظاهرة والخفية، وأكد قصد العفة بالنكاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص588، تحت عنوان «دلالة الحالين في قوله: ﴿محصنين غير مسافحين ولا متخذي أخدان﴾»","url":""}]},{"id":"s5-69","number":69,"surah":5,"verses":[5],"references":[{"surah":5,"verses":[5]}],"verseLabel":"المائدة: 5","question":"ما مناسبة الانتقال من إباحة الطعام والزواج إلى قوله تعالى: ﴿ومن يكفر بالإيمان فقد حبط عمله﴾؟","answer":"إباحة نكاح الكتابية لا تعني تصحيح دينها؛ فجاءت الخاتمة تحذر من أن تجر هذه الصلة إلى الميل عن الإيمان، وتؤكد أن الكفر يحبط العمل ويؤول بصاحبه إلى الخسران.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص590، تحت «دلالة فاصلة الآية الكريمة»","url":""}]},{"id":"s5-70","number":70,"surah":5,"verses":[5],"references":[{"surah":5,"verses":[5]}],"verseLabel":"المائدة: 5","question":"ما سرّ التعبير بقوله تعالى: ﴿ومن يكفر بالإيمان﴾، دون: ومن لم يؤمن؟","answer":"وُجّه الكفر إلى الإيمان نفسه، كأنه حقيقة متعينة واحدة؛ للإشارة إلى أن الإيمان الحق هو الاعتقاد الصحيح، وما يخالفه لا يصح أن يُجعل إيمانًا آخر موازيًا له.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص589، تحت «سر العدول عن أن يقول ومن لم يؤمن إلى قوله ﴿ومن يكفر بالإيمان﴾»","url":""}]},{"id":"s5-71","number":71,"surah":5,"verses":[5],"references":[{"surah":5,"verses":[5]}],"verseLabel":"المائدة: 5","question":"ما الصورة في قوله تعالى: ﴿حبط عمله﴾؟","answer":"الحبط في الأصل فساد ينتفخ به بطن الدابة ثم يهلكها، فاستعير للعمل الذي يبدو موجودًا ثم يسقط أثره وثوابه بسبب الكفر؛ صورة خسارة بعد توهم النماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص581، 589، تحت «دلالة التعبير بالفعل ﴿حبط﴾ في قوله ﴿ومن يكفر بالإيمان فقد حبط عمله﴾»","url":""}]},{"id":"s5-72","number":72,"surah":5,"verses":[5],"references":[{"surah":5,"verses":[5]}],"verseLabel":"المائدة: 5","question":"ما مناسبة قوله تعالى: ﴿وهو في الآخرة من الخاسرين﴾ بعد حبوط العمل؟","answer":"ضم ذكر الخسران في الآخرة إلى حبوط العمل لتأكيد التحذير من الكفر؛ فلا تنفع صاحبه قرباته التي فقدت شرط قبولها، ويضيع ثوابها وما يرجوه من الفوز.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص589–590، تحت عنوان «دلالة التعبير بالفعل ﴿حبط﴾ في قوله: ﴿ومن يكفر بالإيمان فقد حبط عمله﴾»","url":""}]},{"id":"s5-73","number":73,"surah":5,"verses":[6],"references":[{"surah":5,"verses":[6]}],"verseLabel":"المائدة: 6","question":"لماذا قيل ﴿أو جاء أحد منكم من الغائط﴾، ولم يقل: أو جئتم من الغائط؟","answer":"تجنب التعبير إسناد هذا الفعل إلى المخاطبين مباشرة، وأسنده إلى فرد غير معين؛ مراعاةً لأدب الخطاب وحياء السامع، مع وضوح الحكم المراد.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص608، تحت «علة صرف إسناد الفعل الخادش إلى المخاطبين بإسناده إلى أحد غير معين»","url":""}]},{"id":"s5-74","number":74,"surah":5,"verses":[6],"references":[{"surah":5,"verses":[6]}],"verseLabel":"المائدة: 6","question":"كيف يُفهم قوله تعالى: ﴿إذا قمتم إلى الصلاة فاغسلوا وجوهكم﴾ مع أن الوضوء يسبق الدخول فيها؟","answer":"القيام إلى الشيء يأتي بمعنى إرادة الشروع فيه والتوجه إليه؛ أي إذا أردتم القيام إلى الصلاة وأنتم محدثون فتوضؤوا، كما يقال: إذا قرأت فاستعذ، أي إذا أردت القراءة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص595–596، تحت عنوان «المجاز المرسل وأثره في إبراز المعنى في قوله تعالى: ﴿إذا قمتم إلى الصلاة﴾»","url":""}]},{"id":"s5-75","number":75,"surah":5,"verses":[6],"references":[{"surah":5,"verses":[6]}],"verseLabel":"المائدة: 6","question":"لماذا أُدخل مسح الرأس بين غسل اليدين وغسل الرجلين في آية الوضوء؟","answer":"للعناية بمسح الرأس حتى لا يتهاون به، فيأخذ من الاهتمام ما تأخذه الأعضاء المغسولة؛ وفي تقديمه على غسل الرجلين تنبيه إلى أهمية الترتيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص601–602، تحت عنوان «القراءات الواردة في قوله: ﴿وأرجلكم﴾، وأثرها في المعنى والأحكام»","url":""}]},{"id":"s5-616","number":616,"surah":5,"verses":[6],"references":[{"surah":5,"verses":[6]}],"verseLabel":"المائدة: 6","question":"ما وجه مجاورة الأرجل للرؤوس في قراءة الجر في آية الوضوء؟","answer":"من التوجيهات التي يذكرها المصدر التنبيه إلى الاقتصاد في صب الماء على الرجلين؛ فهما مظنة الإسراف، فجاءت مجاورتهما للممسوح تذكيرًا بتقليل الماء مع استيفاء الغسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص602–603، تحت عنوان «دلالة اشتراك المتعاطفين في الوصف في قوله: ﴿وامسحوا برؤوسكم وأرجلكم﴾»","url":""}]},{"id":"s5-76","number":76,"surah":5,"verses":[6],"references":[{"surah":5,"verses":[6]}],"verseLabel":"المائدة: 6","question":"ما دلالة ﴿إلى المرافق﴾ و﴿إلى الكعبين﴾؟","answer":"تحدد ﴿إلى﴾ غاية الجزء المغسول، لكن دخول الغاية في الغسل لا يحسمه الحرف وحده، بل يُعرف بالدليل. ويذكر المصدر دخول المرفقين والكعبين في الغسل اعتمادًا على البيان النبوي.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص599، تحت عنوان «دلالات التعبير بحرف الانتهاء ﴿إلى﴾ في قوله تعالى: ﴿وأيديكم إلى المرافق﴾»","url":""}]},{"id":"s5-77","number":77,"surah":5,"verses":[6],"references":[{"surah":5,"verses":[6]}],"verseLabel":"المائدة: 6","question":"ما سرّ التعبير بقوله تعالى: ﴿وإن كنتم جنبًا فاطهروا﴾، دون: فاغتسلوا؟","answer":"اختير ﴿فاطهروا﴾ للدلالة على الاغتسال مع المبالغة والاجتهاد في إيصال الماء إلى جميع أجزاء البدن؛ لأن أثر الجنابة المعنوي يعم الجسد كله","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص606، تحت عنوان «دلالة ﴿فاطهروا﴾ على الحكم الشرعي، وسر تعليق الشرط بأداة الشك ﴿وإن﴾»","url":""}]},{"id":"s5-78","number":78,"surah":5,"verses":[6],"references":[{"surah":5,"verses":[6]}],"verseLabel":"المائدة: 6","question":"ما الصورة في قوله تعالى: ﴿أو على سفر﴾، دون: أو مسافرين؟","answer":"يدل ﴿على سفر﴾ على العزم عليه والاستعداد له، فيتناول من شرع فيه ولو لم يجاوز حد الحضر؛ فالتعبير يلائم مقام التخفيف والتيسير في بيان الرخصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص606–607، تحت «سر العدول عن لفظ مسافرين إلى قوله ﴿على سفر﴾»","url":""}]},{"id":"s5-79","number":79,"surah":5,"verses":[6],"references":[{"surah":5,"verses":[6]}],"verseLabel":"المائدة: 6","question":"ما سرّ الكناية في قوله تعالى: ﴿أو جاء أحد منكم من الغائط﴾؟","answer":"الغائط في الأصل المكان المنخفض الذي يقصده الإنسان ليستتر، ثم كُني بالمجيء منه عن قضاء الحاجة؛ فحفظ التعبير الأدب وتجنب التصريح بما يستقبح ذكره.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص608، تحت عنوان «علة الكناية عن قضاء الحاجة في قوله: ﴿أو جاء أحد منكم من الغائط﴾»","url":""}]},{"id":"s5-80","number":80,"surah":5,"verses":[6],"references":[{"surah":5,"verses":[6]}],"verseLabel":"المائدة: 6","question":"ما سرّ الكناية بقوله تعالى: ﴿أو لامستم النساء﴾؟","answer":"الملامسة كناية عن الجماع؛ عُدل إليها لتنزيه الخطاب عن التصريح بما يُستحيا من ذكره، مع دلالة اللفظ القريب على المقصود. ففي اختيارها وضوح المعنى وأدب التعبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص610–611، تحت «مزية الكناية وأثرها في المعنى في قوله ﴿أو لامستم النساء﴾»","url":""}]},{"id":"s5-81","number":81,"surah":5,"verses":[6],"references":[{"surah":5,"verses":[6]}],"verseLabel":"المائدة: 6","question":"ما دلالة قوله تعالى: ﴿فتيمموا صعيدًا طيبًا﴾؟","answer":"التيمم هو القصد، والصعيد وجه الأرض، والطيب الطاهر؛ أي اقصدوا عند فقد الماء أو تعذر استعماله جزءًا طاهرًا من جنس الأرض، فجمع اللفظ القصد والبديل وصفته.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص612، تحت عنوان «دلالة وصف الصعيد بالطيب في قوله تعالى: ﴿فتيمموا صعيدًا طيبًا﴾»","url":""}]},{"id":"s5-82","number":82,"surah":5,"verses":[6],"references":[{"surah":5,"verses":[6]}],"verseLabel":"المائدة: 6","question":"ما دلالة زيادة ﴿منه﴾ في آية المائدة: ﴿فامسحوا بوجوهكم وأيديكم منه﴾، وحذفها في النساء؟","answer":"فصلت آية المائدة أحكام الوضوء والتيمم، فناسبها مزيد البيان بإثبات ﴿منه﴾، تأكيدًا لأن المسح من الصعيد الطيب المذكور. أما آية النساء فذكرت بعض الأحكام، فناسبها الحذف.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص614–615، تحت «سر حذف الجار والمجرور منه من آية النساء وإثباته في آية المائدة»","url":""}]},{"id":"s5-83","number":83,"surah":5,"verses":[6],"references":[{"surah":5,"verses":[6]}],"verseLabel":"المائدة: 6","question":"ما دلالة الاستدراك في قوله تعالى: ﴿ما يريد الله ليجعل عليكم من حرج ولكن يريد ليطهركم﴾؟","answer":"ينفي أن يكون المقصود بالتشريع إيقاع المشقة، ويبين أن من حكمته التطهير. فللوضوء تطهير حسي ونفسي، وللتيمم عند تعذر الماء معنى التطهير النفسي الذي جعله الله بدلًا من الوضوء.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص616، تحت عنوان «الاستدراك بلفظ ﴿ولكن﴾؛ لتأكيد نفي الحرج الحسي والنفسي»","url":""}]},{"id":"s5-617","number":617,"surah":5,"verses":[6],"references":[{"surah":5,"verses":[6]}],"verseLabel":"المائدة: 6","question":"كيف يكون تشريع التيمم من إتمام النعمة في قوله تعالى: ﴿وليتم نعمته عليكم﴾؟","answer":"من أوجه إتمام النعمة أن الله شرع الرخصة إلى جانب أصل التكليف؛ فيتم التيسير بإباحة التيمم عند العذر، كما أتم التشريع بالطهارة التي تطهر الأبدان وتكفر الذنوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص617، تحت عنوان «مفهوم تمام النعمة في تشريع الرخصة بالتيمم في قوله: ﴿وليتم نعمته عليكم﴾»","url":""}]},{"id":"s5-84","number":84,"surah":5,"verses":[6],"references":[{"surah":5,"verses":[6]}],"verseLabel":"المائدة: 6","question":"ما مناسبة ختم آية الطهارة بقوله تعالى: ﴿لعلكم تشكرون﴾؟","answer":"لأن الله جمع لهم طهارة الماء ورخصة التيمم عند العجز، فأتم النعمة ولم يقطعهم عن الصلاة؛ وهذه النعمة تستدعي الشكر بالاعتراف والطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص617، تحت «استعارة صيغة الرجاء إلى الأمر لقصد الحث عليه في قوله ﴿لعلكم تشكرون﴾»","url":""}]},{"id":"s5-85","number":85,"surah":5,"verses":[6],"references":[{"surah":5,"verses":[6]}],"verseLabel":"المائدة: 6","question":"ما سرّ اختيار ﴿إذا﴾ في قوله تعالى: ﴿إذا قمتم إلى الصلاة﴾، و﴿إن﴾ في قوله: ﴿وإن كنتم جنبًا﴾؟","answer":"﴿إذا﴾ لما يتكرر ويتوقع من القيام إلى الصلاة، و﴿إن﴾ للجنابة لأنها حالة عارضة لا تتحقق كل مرة؛ فاختلاف الأداة يطابق اختلاف الوقوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص597، تحت عنوان «الفرق بين التعبيرين في قوله: ﴿إذا قمتم إلى الصلاة﴾ و﴿وإن كنتم مرضى﴾»","url":""}]},{"id":"s5-86","number":86,"surah":5,"verses":[7],"references":[{"surah":5,"verses":[7]}],"verseLabel":"المائدة: 7","question":"ما سرّ إفراد النعمة في قوله تعالى: ﴿واذكروا نعمة الله عليكم﴾؟","answer":"أفردت باعتبار جنس النعمة الشامل، أو النعمة العظمى المتمثلة في الهداية والتشريع، فتدخل فيها نعم كثيرة يستحضرها كل مخاطب.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص622، تحت «سر إفراد النعم في قوله ﴿واذكروا نعمة الله عليكم﴾»","url":""}]},{"id":"s5-87","number":87,"surah":5,"verses":[7],"references":[{"surah":5,"verses":[7]}],"verseLabel":"المائدة: 7","question":"ما دلالة إضافة النعمة إلى الله في قوله تعالى: ﴿واذكروا نعمة الله عليكم﴾؟","answer":"الإضافة تشرف النعمة وتعظمها، وتذكر بأنها من الله المنعم؛ فيستدعي استحضار إحسانه الشكر والامتثال والمحبة بدل الغفلة عن مصدر النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص623، تحت عنوان «علة إضافة النعمة إلى الله تعالى في قوله: ﴿نعمة الله﴾»","url":""}]},{"id":"s5-88","number":88,"surah":5,"verses":[7],"references":[{"surah":5,"verses":[7]}],"verseLabel":"المائدة: 7","question":"ما الذي تؤكده المواثقة في قوله ﴿وميثاقه الذي واثقكم به﴾؟","answer":"المواثقة معاهدة أُحكمت بالعقد على ثقة؛ فالتعبير يذكرهم بالعهد المؤكد الذي التزموه، ويشدد لزوم الوفاء بما أقروا به من السمع والطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص624، تحت «دلالة المواثقة للميثاق في قوله ﴿وميثاقه الذي واثقكم به﴾»","url":""}]},{"id":"s5-89","number":89,"surah":5,"verses":[7],"references":[{"surah":5,"verses":[7]}],"verseLabel":"المائدة: 7","question":"ما مناسبة استحضار قول المؤمنين: ﴿سمعنا وأطعنا﴾ هنا؟","answer":"هذا القول هو مضمون قبول الميثاق: سمع فهم وقبول، وطاعة تنفيذ؛ فذكّرهم بإقرارهم السابق قبل أن يأمرهم بالوفاء والعدل في الآيات التالية.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص624–625، تحت «التقييد بالظرف إذ في قوله ﴿إذ قلتم سمعنا وأطعنا﴾ وفائدته»","url":""}]},{"id":"s5-90","number":90,"surah":5,"verses":[7],"references":[{"surah":5,"verses":[7]}],"verseLabel":"المائدة: 7","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿إن الله عليم بذات الصدور﴾ بعد قولهم: ﴿سمعنا وأطعنا﴾؟","answer":"لأن الوفاء لا يثبت بظاهر القول وحده؛ فالله يعلم ما في الصدور من صدق الطاعة أو نية النقض، وجاءت الخاتمة مراقبةً للباطن بعد إعلان اللسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص626، تحت «دلالة الاعتراض التذييلي بقوله ﴿إن الله عليم بذات الصدور﴾»","url":""}]},{"id":"s5-92","number":92,"surah":5,"verses":[8],"references":[{"surah":5,"verses":[8]}],"verseLabel":"المائدة: 8","question":"ما دلالة صيغة المبالغة في قوله تعالى: ﴿قوامين﴾، دون: قائمين؟","answer":"﴿قوامين﴾ تدل على قوة القيام بالحق وتكرره والثبات عليه؛ فليس المطلوب موقف عدل عابرًا، بل أن يصير القيام لله وصفًا راسخًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص631–632، تحت «التعبير بصيغة المبالغة قوامين مناط بعلو الهمة وقداسة المهمة»","url":""}]},{"id":"s5-93","number":93,"surah":5,"verses":[8],"references":[{"surah":5,"verses":[8]}],"verseLabel":"المائدة: 8","question":"ما مناسبة إعادة التحذير من الشنآن في الآية الثامنة بعد وروده في الآية الثانية؟","answer":"في الآية الثانية نُهي عن أن يحملهم صد المشركين على الاعتداء، وفي الثامنة نُهي عن أن يحملهم البغض على ترك العدل في الشهادة والحكم؛ فتكرر الأصل لاختلاف ميدان تطبيقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص523–524، تحت عنوان «من متشابه النظم»","url":""}]},{"id":"s5-94","number":94,"surah":5,"verses":[8],"references":[{"surah":5,"verses":[8]}],"verseLabel":"المائدة: 8","question":"ما سرّ التعبير بقوله تعالى: ﴿اعدلوا هو أقرب للتقوى﴾، دون: العدل هو التقوى؟","answer":"أعاد الأمر بالعدل بعد النهي عن الجور لينقلهم من مجرد الكف إلى الفعل الإيجابي، وجعل العدل أقرب إلى التقوى لأنه طريقها العملي ودليلها، لا أنه يستوعب حقيقتها كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص635، تحت «دلالة التصريح بالأمر بالعدل في قوله ﴿اعدلوا هو أقرب للتقوى﴾»","url":""}]},{"id":"s5-95","number":95,"surah":5,"verses":[8],"references":[{"surah":5,"verses":[8]}],"verseLabel":"المائدة: 8","question":"ما دلالة إظهار اسم الله في قوله تعالى: ﴿واتقوا الله إن الله خبير بما تعملون﴾؟","answer":"إظهار الاسم الجليل بدل الضمير يجدد التعظيم والمهابة، ويربط الأمر بالتقوى مباشرة بمن يعلم خفايا العمل ودوافع العدل والجور.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص636، تحت «دلالة العدول عن الإضمار إلى الإظهار في قوله ﴿إن الله خبير بما تعملون﴾»","url":""}]},{"id":"s5-96","number":96,"surah":5,"verses":[8],"references":[{"surah":5,"verses":[8]}],"verseLabel":"المائدة: 8","question":"ما سرّ اختيار ﴿خبير بما تعملون﴾ في ختام آية العدل؟","answer":"الخبير هو العالم بدقائق الأمور وبواطنها، وهو الأنسب لعدل قد تحرفه مشاعر الشنآن الخفية؛ فالله يعلم ظاهر الحكم والدافع المستتر وراءه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص636، تحت «أتي بصفة خبير لينبه بها على الصفة القلبية التي لا تخفى على الله»","url":""}]},{"id":"s5-97","number":97,"surah":5,"verses":[9],"references":[{"surah":5,"verses":[9]}],"verseLabel":"المائدة: 9","question":"ما دلالة تقديم المغفرة على الأجر العظيم في وعد المؤمنين؟","answer":"المغفرة تزيل تبعات الذنوب أولًا، ثم يأتي الأجر زيادةً وإكرامًا على العمل الصالح؛ فقدم تطهير العبد من الموانع قبل تحليته بالثواب.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص643، تحت «سر تقديم الوعد بالمغفرة على الوعد بالأجر العظيم»","url":""}]},{"id":"s5-98","number":98,"surah":5,"verses":[9],"references":[{"surah":5,"verses":[9]}],"verseLabel":"المائدة: 9","question":"ما دلالة تقديم ﴿لهم﴾ في قوله تعالى: ﴿لهم مغفرة وأجر عظيم﴾؟","answer":"تقديم الجار والمجرور للاختصاص والاهتمام بأصحاب الوعد؛ فالمغفرة والأجر ثابتان لهم في مقابلة أصحاب الجحيم في الآية التالية.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص642، تحت «إفادة تقديم الخبر على المبتدأ الاختصاص في قوله ﴿لهم مغفرة﴾»","url":""}]},{"id":"s5-99","number":99,"surah":5,"verses":[9],"references":[{"surah":5,"verses":[9]}],"verseLabel":"المائدة: 9","question":"لماذا جاء الوعد بالمغفرة والأجر بصيغة الماضي ﴿وعد الله﴾؟","answer":"الماضي يؤكد تحقق الوعد كأنه قد وقع؛ فوعد الله لا يتخلف، وما أخبر بوقوعه مستقبلًا محقق. وفي ذلك تثبيت ليقين المؤمنين وطمأنة لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص640–641، تحت «نكتة التعبير عن الوعد بالماضي في قوله ﴿وعد الله الذين آمنوا﴾»","url":""}]},{"id":"s5-100","number":100,"surah":5,"verses":[10],"references":[{"surah":5,"verses":[10]}],"verseLabel":"المائدة: 10","question":"ما دلالة الجمع بين الكفر والتكذيب في قوله تعالى: ﴿والذين كفروا وكذبوا بآياتنا﴾؟","answer":"عُطف التكذيب بالآيات على الكفر عطفَ الخاص على العام؛ فبعد وصفهم بجحود الحق، صُرّح بما واجهوا به آيات الله من التكذيب، وهو أخص صور ذلك الجحود.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص648–649، تحت «البدء بصفة الذين كفروا ثم الذين كذبوا»","url":""}]},{"id":"s5-101","number":101,"surah":5,"verses":[10],"references":[{"surah":5,"verses":[10]}],"verseLabel":"المائدة: 10","question":"ما دلالة تقديم الكفر على التكذيب؟","answer":"لأن الكفر جحودٌ في القلب يطمس معالم إدراك الحق؛ فينشأ عنه رد الحقائق والتكذيب بآيات الله. فقدم فساد الباطن الذي يؤدي إلى هذا التكذيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص649، تحت «بلاغة تقديم فعل الكفر على فعل التكذيب»","url":""}]},{"id":"s5-102","number":102,"surah":5,"verses":[10],"references":[{"surah":5,"verses":[10]}],"verseLabel":"المائدة: 10","question":"ما سرّ تسمية أهل النار ﴿أصحاب الجحيم﴾؟","answer":"الصحبة تدل على الملازمة وطول المكث، والجحيم النار الشديدة التأجج؛ فالتعبير لا يذكر مجرد دخول عابر بل مصاحبة دائمة للعذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص647–648، تحت عنوان «شرح المفردات»","url":""}]},{"id":"s5-103","number":103,"surah":5,"verses":[11],"references":[{"surah":5,"verses":[11]}],"verseLabel":"المائدة: 11","question":"ما سرّ تكرار الأمر بذكر نعمة الله في الآية 11 بعد وروده في الآية 7؟","answer":"النعمة الأولى مطلقة تشمل الهداية والتشريع، وهنا تذكير بنعمة معينة: أن كف الله عنهم أيدي من هموا بإيذائهم. فتجدد الأمر بالذكر لاختلاف النعمة وتجدد موجب شكرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص657–658، تحت عنوان «دلالة رسم تاء ﴿نعمت﴾ مفتوحة»","url":""}]},{"id":"s5-104","number":104,"surah":5,"verses":[11],"references":[{"surah":5,"verses":[11]}],"verseLabel":"المائدة: 11","question":"ما الصورة في قوله تعالى: ﴿إذ هم قوم أن يبسطوا إليكم أيديهم﴾؟","answer":"بسط اليد كناية عن مدها بالأذى والقتل، فحوّل نية الاعتداء إلى مشهد أيدٍ تمتد نحو المؤمنين، ليظهر أثر نعمة كفها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص659، تحت «دلالة استعمال بسط اليد في الإيذاء»","url":""}]},{"id":"s5-105","number":105,"surah":5,"verses":[11],"references":[{"surah":5,"verses":[11]}],"verseLabel":"المائدة: 11","question":"لماذا أُعيدت كلمة ﴿أيديهم﴾ في ﴿فكف أيديهم عنكم﴾ بدل الاكتفاء بالضمير؟","answer":"إظهار الأيدي مرة أخرى يزيد تقرير النعمة؛ فهي موضع قوة المعتدين ووسيلة بطشهم، وقد منعها الله من الوصول إلى المؤمنين. فالتصريح بها يبرز الحماية من موضع الخطر نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص660، تحت عنوان «إظهار ما حقه الإضمار»","url":""}]},{"id":"s5-106","number":106,"surah":5,"verses":[11],"references":[{"surah":5,"verses":[11]}],"verseLabel":"المائدة: 11","question":"ما دلالة تقديم ﴿إليكم﴾ في قوله تعالى: ﴿أن يبسطوا إليكم أيديهم﴾؟","answer":"قُدم المتعلق لتوجيه العناية إلى المؤمنين الذين قصدهم الاعتداء وإلى خصوص النعمة الواقعة عليهم، ثم ذُكرت وسيلة الأذى وهي الأيدي.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص658–659، تحت «بلاغة تقديم المجرور إليكم على المفعول أيديهم»","url":""}]},{"id":"s5-107","number":107,"surah":5,"verses":[11],"references":[{"surah":5,"verses":[11]}],"verseLabel":"المائدة: 11","question":"ما دلالة إظهار اسم الله في قوله تعالى: ﴿واتقوا الله وعلى الله فليتوكل المؤمنون﴾؟","answer":"أعيد اسم الله لبيان فضله على خلقه، وأنهم إذا توكلوا عليه كفاهم ما هم فيه؛ فالإظهار يصل الأمر بالتوكل بمن يتفضل بالحماية والكفاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص660–661، تحت «إظهار ما حقه الإضمار»","url":""}]},{"id":"s5-108","number":108,"surah":5,"verses":[11],"references":[{"surah":5,"verses":[11]}],"verseLabel":"المائدة: 11","question":"ما دلالة تقديم ﴿على الله﴾ في قوله تعالى: ﴿وعلى الله فليتوكل المؤمنون﴾؟","answer":"تقديم الجار والمجرور يفيد القصر: على الله وحده يعتمد المؤمنون، لا على قوتهم وأسبابهم، ولا سيما بعد تذكيرهم بحفظه لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص661، تحت «تقديم الجار والمجرور على الفعل»","url":""}]},{"id":"s5-109","number":109,"surah":5,"verses":[12],"references":[{"surah":5,"verses":[12]}],"verseLabel":"المائدة: 12","question":"لماذا أُكد أخذ ميثاق بني إسرائيل بقوله ﴿ولقد أخذ الله ميثاق بني إسرائيل﴾؟","answer":"اجتمع التوكيد باللام و«قد» للاهتمام بالخبر وتقريره، وتنبيه المخاطبين إلى عظمة الميثاق ولزوم الوفاء به؛ فالتأكيد يرسّخ الالتزام بالعهود.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص669، تحت «وجه اشتمال الجملة على قد واللام»","url":""}]},{"id":"s5-110","number":110,"surah":5,"verses":[12],"references":[{"surah":5,"verses":[12]}],"verseLabel":"المائدة: 12","question":"لماذا سُمّي المتولون لشؤون بني إسرائيل ﴿نقباء﴾ في قوله تعالى: ﴿وبعثنا منهم اثني عشر نقيبًا﴾؟","answer":"النقيب يتفقد أحوال قومه وينقب عما يخفى منها؛ فتناسب تسميته وظيفته في معرفتهم ورعاية شؤونهم. ويذكر المصدر أيضًا احتمال أن تكون الصيغة بمعنى من اختير على علم بأحوال القوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص669–670، تحت عنوان «دلالة التعبير بـ(نقيب) زنة (فعيل)»","url":""}]},{"id":"s5-111","number":111,"surah":5,"verses":[12],"references":[{"surah":5,"verses":[12]}],"verseLabel":"المائدة: 12","question":"ما دلالة قوله تعالى بعد بعث النقباء: ﴿إني معكم﴾؟","answer":"هي معية نصرة وتأييد مشروطة بالوفاء بما بعدها من الصلاة والزكاة والإيمان بالرسل؛ فطمأنتهم إلى العون وربطته بالطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص671، تحت عنوان «المجاز في قوله: ﴿إني معكم﴾»","url":""}]},{"id":"s5-112","number":112,"surah":5,"verses":[12],"references":[{"surah":5,"verses":[12]}],"verseLabel":"المائدة: 12","question":"لماذا بُدئ بالصلاة في شروط الميثاق في قوله تعالى: ﴿لئن أقمتم الصلاة وآتيتم الزكاة﴾؟","answer":"لأن الصلاة ركن كل دين، وبها طهارة النفوس وتزكية القلوب وتربية الضمير؛ فناسب أن تتقدم في بيان ما يتحقق به الوفاء بالميثاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص671–672، تحت عنوان «وجه البدء بالصلاة في الأركان المأخوذة عليهم»","url":""}]},{"id":"s5-618","number":618,"surah":5,"verses":[12],"references":[{"surah":5,"verses":[12]}],"verseLabel":"المائدة: 12","question":"لماذا أُخر الإيمان بالرسل عن الصلاة والزكاة في شروط الميثاق مع أنه أصل لهما؟","answer":"ينبه الترتيب إلى أن الصلاة والزكاة لا تحققان النجاة مع تكذيب بعض الرسل، بل لا بد من الإيمان بجميعهم. ويذكر المصدر أيضًا أن مجاورة الإيمان بالرسل لتعزيرهم تبين ما يقتضيه الإيمان من نصرتهم ومؤازرتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص674، تحت عنوان «سر تأخير الإيمان بالرسل مع أنه مقدم على الصلاة والزكاة»","url":""}]},{"id":"s5-619","number":619,"surah":5,"verses":[12],"references":[{"surah":5,"verses":[12]}],"verseLabel":"المائدة: 12","question":"لماذا ذُكر إقراض الله بعد إيتاء الزكاة في شروط الميثاق؟","answer":"المقصود بالزكاة هنا الواجبات المالية، وبالإقراض الصدقات المندوبة؛ فخُصت صدقات التطوع بالذكر تنبيهًا إلى شرفها وعلو منزلتها، وليست تكرارًا للزكاة الواجبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص675، تحت عنوان «دلالة قوله: ﴿وأقرضتم الله﴾ بعد ذكر الزكاة مع أن بينهما تشابهًا»","url":""}]},{"id":"s5-113","number":113,"surah":5,"verses":[12],"references":[{"surah":5,"verses":[12]}],"verseLabel":"المائدة: 12","question":"لماذا سُمّي الإنفاق في سبيل الله إقراضًا لله مع أن المال له سبحانه؟","answer":"شُبّه الإنفاق بالقرض لأن الله وعد بجزائه والثواب عليه، كما يُقضى القرض؛ فالتعبير يرغب المنفق بما يطمئنه إلى الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص675–676، تحت عنوان «الاستعارة في قوله: ﴿وأقرضتم الله﴾»","url":""}]},{"id":"s5-620","number":620,"surah":5,"verses":[12],"references":[{"surah":5,"verses":[12]}],"verseLabel":"المائدة: 12","question":"لماذا وُصف القرض بأنه ﴿حسنًا﴾ في قوله تعالى: ﴿وأقرضتم الله قرضًا حسنًا﴾؟","answer":"ليكون خاليًا من المن والأذى والمنفعة التي تعود على المقرض على وجه الربا؛ فالحسن قيد ينزه الإنفاق عما يفسده ويؤذي من ينتفع به.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص676، تحت عنوان «دلالة وصف القرض بالحسن»","url":""}]},{"id":"s5-114","number":114,"surah":5,"verses":[12],"references":[{"surah":5,"verses":[12]}],"verseLabel":"المائدة: 12","question":"ما دلالة تقديم تكفير السيئات على إدخال الجنات؟","answer":"تكفير السيئات يزيل أسباب العقوبة أولًا، ثم يأتي إدخال الجنات إكرامًا وثوابًا؛ فقدم التطهير من الموانع على الفوز بالنعيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص676–677، تحت «تقديم تكفير السيئات على إدخال الجنات»","url":""}]},{"id":"s5-116","number":116,"surah":5,"verses":[13],"references":[{"surah":5,"verses":[13]}],"verseLabel":"المائدة: 13","question":"ما دلالة الباء و﴿ما﴾ في قوله تعالى: ﴿فبما نقضهم ميثاقهم لعناهم﴾؟","answer":"الباء للسببية، أي بسبب نقضهم، و﴿ما﴾ تؤكد هذا الربط؛ فالعقوبة لم تقع اعتباطًا، بل ترتبت على جريمتهم في نقض الميثاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص686، تحت عنوان «معنى (ما) بين الإعراب النحوي والإعراب التفسيري»","url":""}]},{"id":"s5-117","number":117,"surah":5,"verses":[13],"references":[{"surah":5,"verses":[13]}],"verseLabel":"المائدة: 13","question":"ما علاقة قسوة القلوب بتحريف الكلم الذي ذُكر عقبها؟","answer":"جاء التحريف عقب القسوة بيانًا لثمرتها؛ إذ لم تلن قلوبهم للحق، فجرؤوا على تغيير كلام الله وتحريفه. فترتيب الجمل يصل فساد التلقي بفساد التصرف في الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص687، تحت «دلالة تعقيب التحريف على قسوة القلوب»","url":""}]},{"id":"s5-118","number":118,"surah":5,"verses":[13,41],"references":[{"surah":5,"verses":[13,41]}],"verseLabel":"المائدة: 13؛ المائدة: 13، 41","question":"ما الفرق بين قوله تعالى: ﴿يحرفون الكلم عن مواضعه﴾ في الآية 13، وقوله: ﴿يحرفون الكلم من بعد مواضعه﴾ في الآية 41؟","answer":"﴿عن مواضعه﴾ يناسب التحريف القريب من وضع الكلام، وهو تحريف الأوائل؛ أما ﴿من بعد مواضعه﴾ فيصور التحريف بعد أن استقر الكلام وعُرف وعُمل به زمنًا. فالتغاير يبرز الفرق بين القرب من الأصل والتأخر عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص693–694، تحت «يحرفون الكلم عن مواضعه ويحرفون الكلم من بعد مواضعه»","url":""}]},{"id":"s5-119","number":119,"surah":5,"verses":[13],"references":[{"surah":5,"verses":[13]}],"verseLabel":"المائدة: 13","question":"ما سرّ التعبير بقوله تعالى: ﴿ونسوا حظًا مما ذكروا به﴾، دون: نسوا ما ذكروا به؟","answer":"الحظ نصيب يُنتفع به؛ فتسميته حظًا تبرز أنهم فوّتوا على أنفسهم خيرًا كان لهم أن ينالوه. وتنكيره هنا للتعظيم، والنسيان يشمل ترك ما ذُكروا به وإهمال العمل به، لا مجرد غياب ألفاظه عن الذاكرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص688–689، تحت «من جمال النظم القرآني التعبير بالحظ»","url":""}]},{"id":"s5-120","number":120,"surah":5,"verses":[13],"references":[{"surah":5,"verses":[13]}],"verseLabel":"المائدة: 13","question":"كيف يحتمل لفظ ﴿خائنة﴾ معنى الخيانة نفسها، لا شخصًا خائنًا بعينه؟","answer":"يحتمل أن يكون مصدرًا بمعنى الخيانة، وإن جاء على صورة اسم الفاعل المؤنث؛ ونظيره استعمال ﴿الطاغية﴾ بمعنى الطغيان. وعلى هذا يحمل اللفظ على الحدث نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص690، تحت عنوان «التعبير بقوله: ﴿خائنة﴾»","url":""}]},{"id":"s5-621","number":621,"surah":5,"verses":[13],"references":[{"surah":5,"verses":[13]}],"verseLabel":"المائدة: 13","question":"هل تدل التاء في لفظ ﴿خائنة﴾ على التأنيث وحده؟","answer":"من الأوجه التي يذكرها المصدر أن التاء للمبالغة، كما يقال: رجل علامة؛ فزيادة التاء قد تقوي الوصف، ولا يلزم أن تعين مؤنثًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص690، تحت عنوان «لفظ ﴿خائنة﴾ يحتمل دلالته على المبالغة»","url":""}]},{"id":"s5-622","number":622,"surah":5,"verses":[13],"references":[{"surah":5,"verses":[13]}],"verseLabel":"المائدة: 13","question":"ما دلالة ﴿ولا تزال﴾ في قوله تعالى: ﴿ولا تزال تطلع على خائنة منهم﴾؟","answer":"يدل التعبير على التجدد والاستمرار: تتكرر الخيانة ويستمر انكشافها للمخاطب، فلا يصف حادثة انقضت مرة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص689، تحت عنوان «دلالة الفعل ﴿ولا تزال﴾»","url":""}]},{"id":"s5-121","number":121,"surah":5,"verses":[13],"references":[{"surah":5,"verses":[13]}],"verseLabel":"المائدة: 13","question":"ما مناسبة الأمر بالعفو والصفح بعد ذكر نقض الميثاق والتحريف والخيانة؟","answer":"المقصود التجاوز عن خيانتهم وتليين قلوبهم؛ ويبين المصدر أن العفو والصفح يورثان النفس قوة وثباتًا لا يورثهما النزاع والجدال.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص691–692، تحت عنوان «سر التعبير بالعفو والصفح»","url":""}]},{"id":"s5-623","number":623,"surah":5,"verses":[13],"references":[{"surah":5,"verses":[13]}],"verseLabel":"المائدة: 13","question":"ما الذي يضيفه ﴿واصفح﴾ بعد ﴿فاعف عنهم﴾؟","answer":"العفو ترك العقوبة، والصفح أبلغ منه؛ إذ يضم إلى ذلك ترك اللوم والتثريب. فجمعهما يشمل التجاوز في المعاملة والسماحة في النفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص692، تحت عنوان «بلاغة عطف الأفعال المتقاربة الدلالة»","url":""}]},{"id":"s5-122","number":122,"surah":5,"verses":[13],"references":[{"surah":5,"verses":[13]}],"verseLabel":"المائدة: 13","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿إن الله يحب المحسنين﴾؟","answer":"لما أمر بالعفو والصفح رفعهما من مجرد كف الانتقام إلى مقام الإحسان، ثم رغب فيهما بمحبة الله للمحسنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص693، تحت «دلالة تذييل الآية بالإحسان»","url":""}]},{"id":"s5-123","number":123,"surah":5,"verses":[14],"references":[{"surah":5,"verses":[14]}],"verseLabel":"المائدة: 14","question":"ما سرّ التعبير بقوله تعالى: ﴿ومن الذين قالوا إنا نصارى﴾، دون: ومن النصارى؟","answer":"نسبهم إلى دعواهم التي قالوها ولم يحققوا مقتضاها من نصرة الله والوفاء بميثاقه؛ ففي الموصول تعريض بالفارق بين الاسم المعلن والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص699–700، تحت «نكتة الإطناب في التعبير عن النصارى بالموصول وصلته»","url":""}]},{"id":"s5-124","number":124,"surah":5,"verses":[14],"references":[{"surah":5,"verses":[14]}],"verseLabel":"المائدة: 14","question":"ما مناسبة جعل العداوة والبغضاء جزاءً لنسيانهم الميثاق؟","answer":"تركوا العمل بنصيب مما ذُكروا به وبدلوا دينهم، فجازاهم الله بإلقاء الخصومة والكراهية بينهم؛ فصارت الفرقة والعداوة عقوبة على نقض ما أُخذ عليهم من الميثاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص698، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s5-125","number":125,"surah":5,"verses":[14],"references":[{"surah":5,"verses":[14]}],"verseLabel":"المائدة: 14","question":"ما الذي يفيده الجمع بين ﴿العداوة﴾ و﴿البغضاء﴾ مع تقاربهما في المعنى؟","answer":"يقوّي الجمع دلالة تأصل الكراهية واستحكامها؛ فإن حمل اللفظان على معنى متقارب كان العطف للتأكيد، وإن لوحظ بينهما عموم وخصوص زاد ذكر الثاني احتراسًا وبيانًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص703–704، تحت «السر في عطف البغضاء على العداوة»","url":""}]},{"id":"s5-126","number":126,"surah":5,"verses":[14],"references":[{"surah":5,"verses":[14]}],"verseLabel":"المائدة: 14","question":"ما الصورة في قوله تعالى ﴿فأغرينا بينهم العداوة والبغضاء﴾؟","answer":"الإغراء في الأصل الحث على الشيء، ويأتي بمعنى الإلصاق؛ فصور ملازمة العداوة لهم بما أُلصق فلا ينفك، أو بما يُحمل المرء عليه ويُدفع إليه. وفيه تصوير لشدة استحكام الفرقة بينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص702، تحت «دلالة استعارة لفظ الإغراء مع العداوة والبغضاء»","url":""}]},{"id":"s5-127","number":127,"surah":5,"verses":[14],"references":[{"surah":5,"verses":[14]}],"verseLabel":"المائدة: 14","question":"ما دلالة تقييد العداوة والبغضاء بقوله تعالى: ﴿إلى يوم القيامة﴾؟","answer":"يبين القيد امتداد عقوبة الفرقة في الدنيا إلى يوم القيامة؛ فلا يصورها خلافًا عابرًا، ويهيئ للوعيد التالي بما ينتظرهم من الجزاء في الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص704، تحت «فائدة ذكر الغاية في قوله ﴿إلى يوم القيامة﴾»","url":""}]},{"id":"s5-128","number":128,"surah":5,"verses":[14],"references":[{"surah":5,"verses":[14]}],"verseLabel":"المائدة: 14","question":"ما دلالة التعبير عن الجزاء بقوله تعالى: ﴿وسوف ينبئهم الله بما كانوا يصنعون﴾؟","answer":"في التنبئة وعيد بالمجازاة؛ كما يقول المتوعد: سأخبرك بما فعلت، يريد الجزاء عليه. وذكر ﴿سوف﴾ يؤكد الوعيد الآتي ويزيد التهديد به.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص705، تحت عنوان «سر التعبير عن المجازاة بالتنبئة»","url":""}]},{"id":"s5-624","number":624,"surah":5,"verses":[14],"references":[{"surah":5,"verses":[14]}],"verseLabel":"المائدة: 14","question":"لماذا قيل ﴿بما كانوا يصنعون﴾ بدل: بما كانوا يعملون؟","answer":"الصنع أخص من مطلق العمل؛ فيشير إلى رسوخهم في تلك الأفعال حتى غدت كالصنعة التي تمرسوا بها، وفي ذلك تقرير لشدة مؤاخذتهم عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص705–706، تحت عنوان «دلالة التعبير عن العمل بالصنع»","url":""}]},{"id":"s5-129","number":129,"surah":5,"verses":[15],"references":[{"surah":5,"verses":[15]}],"verseLabel":"المائدة: 15","question":"ما دلالة وصف المخاطبين بأهل الكتاب في قوله ﴿يا أهل الكتاب قد جاءكم رسولنا﴾؟","answer":"يلزمهم بما ينتسبون إليه من كتاب ووحي أن يتبعوا الرسول الذي يبين ما أخفوه ويصدق أصل الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص712، تحت «سر ندائهم بأهل الكتاب»","url":""}]},{"id":"s5-130","number":130,"surah":5,"verses":[15],"references":[{"surah":5,"verses":[15]}],"verseLabel":"المائدة: 15","question":"ما سرّ بيان الرسول كثيرًا مما أخفوه من الكتاب والعفو عن كثير؟","answer":"بيّن ما تقوم به الحجة وتصلح به العقيدة والشريعة، وترك كشف ما لا تقتضيه الرسالة أو ما لا تتعلق به مصلحة البيان؛ فالعفو إعراض مقصود لا عجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص714–715، تحت «توجيه ذكر العفو بدل الإخفاء في مقابل ذكر البيان»","url":""}]},{"id":"s5-131","number":131,"surah":5,"verses":[15],"references":[{"surah":5,"verses":[15]}],"verseLabel":"المائدة: 15","question":"ما سرّ التعبير عن ترك بيان بعض ما أخفوه بقوله تعالى: ﴿ويعفو عن كثير﴾؟","answer":"العفو أصله المحو والستر؛ فاختير للدلالة على أنه يعرض عما لا تدعو ضرورة دينية لإظهاره، صيانة لهم من زيادة الافتضاح، وفي لفظ العفو معنى جميل بدل إعادة لفظ الإخفاء المشعر بالذم","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص714–715، تحت «توجيه ذكر العفو بدل الإخفاء في مقابل ذكر البيان»","url":""}]},{"id":"s5-132","number":132,"surah":5,"verses":[15],"references":[{"surah":5,"verses":[15]}],"verseLabel":"المائدة: 15","question":"ما دلالة الجمع بين ﴿نور﴾ و﴿كتاب مبين﴾؟","answer":"النور هو الرسول أو القرآن؛ سمي نورًا لكشفه ظلمات الشرك وإظهاره طريق الهدى. والكتاب المبين هو القرآن الظاهر إعجازه أو المظهر لما خفي؛ فإن أريد بالنور القرآن تعدد الوصف لشيء واحد، وإن أريد الرسول اجتمع نور الرسول وبيان الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص716–717، تحت «بلاغة الاستعارة وبديع اللف والنشر المرتب»","url":""}]},{"id":"s5-133","number":133,"surah":5,"verses":[16],"references":[{"surah":5,"verses":[16]}],"verseLabel":"المائدة: 16","question":"ما دلالة قوله تعالى: ﴿يهدي به الله﴾ بعد ذكر النور والكتاب؟","answer":"أُفرد الضمير لأن النور والكتاب المبين شيء واحد، وهو القرآن، أو لأنهما كشيء واحد في الحكم؛ وأُظهر اسم الله لإبراز كمال العناية بأمر الهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص717–718، تحت «دلالة توحيد الضمير وتقديمه على المسند إليه في ﴿يهدي به الله﴾»","url":""}]},{"id":"s5-134","number":134,"surah":5,"verses":[16],"references":[{"surah":5,"verses":[16]}],"verseLabel":"المائدة: 16","question":"ما دلالة وصف طرق الدين الحق بأنها ﴿سبل السلام﴾؟","answer":"صُورت شرائع الحق بطرق توصل إلى السلامة؛ فإضافة السبل إلى السلام تمدحها بأن سالكها يأمن المخاوف ويبلغ النجاة. وفي ذلك ترغيب في طاعة الله واتباع دينه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص719، تحت «سر الاستعارة في التعبير عن الدين الحق بسبيل السلام»","url":""}]},{"id":"s5-135","number":135,"surah":5,"verses":[16],"references":[{"surah":5,"verses":[16]},{"surah":6,"verses":[1]}],"verseLabel":"المائدة: 16؛ الأنعام: 1","question":"ما سرّ جمع الظلمات وإفراد النور في قوله تعالى: ﴿يخرجهم من الظلمات إلى النور﴾؟","answer":"من أوجهه أن طرق الكفر والضلال وأسبابهما متعددة، أما الحق فطريقه واحد؛ فناسب جمع الظلمات وإفراد النور. ويذكر المصدر أيضًا تعدد معاني الظلمات، كالكفر والنفاق والجهل، في مقابل نور الهدى والإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص720–721، تحت عنوان «وجه جمع الظلمات وإفراد النور»","url":""}]},{"id":"s5-625","number":625,"surah":5,"verses":[16],"references":[{"surah":5,"verses":[16]},{"surah":6,"verses":[1]}],"verseLabel":"المائدة: 16؛ الأنعام: 1","question":"كيف يُوجّه جمع الظلمات وإفراد النور في الأنعام على المعنى الحسي؟","answer":"من توجيهات المصدر أن المراد بالنور جنسه، فجيء به مفردًا؛ أما الظلمات فكثيرة، إذ لكل جرم وظل ظلمة، بخلاف النور الذي عُدّ جنسًا واحدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص210–211، تحت عنوان «بلاغة إفراد (النور) وجمع الظلمات»","url":""}]},{"id":"s5-626","number":626,"surah":5,"verses":[16],"references":[{"surah":5,"verses":[16]},{"surah":6,"verses":[1]}],"verseLabel":"المائدة: 16؛ الأنعام: 1","question":"ما المعنى المعنوي المحتمل للظلمات والنور في قوله تعالى: ﴿وجعل الظلمات والنور﴾؟","answer":"يحتمل أن تكون الظلمات الكفر أو الجهل، والنور الإيمان أو العلم. وعلى هذا التأويل تكون طرق الغواية والباطل كثيرة، أما طريق الحق والإسلام فواحد؛ فالمقصود هداية القلوب وضلالها، لا الضوء والظلام الماديان.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص211، تحت عنوان «دلالة لفظي (النور) و(الظلمات)، وأثر تنوع معانيهما في السياق»","url":""}]},{"id":"s5-136","number":136,"surah":5,"verses":[16],"references":[{"surah":5,"verses":[16]}],"verseLabel":"المائدة: 16","question":"ما الفرق بين الهداية إلى ﴿سبل السلام﴾ والهداية إلى ﴿صراط مستقيم﴾؟","answer":"الهداية إلى الصراط المستقيم هي عين الهداية إلى سبل السلام؛ وعُطفت عليها لتنزيل التغاير في الوصف منزلة التغاير في الذات. فالأولى تبرز السلامة، والثانية وضوح الطريق واستقامته.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص721–722، تحت «سر الاستعارة في تشبيه الإسلام بالصراط المستقيم»","url":""}]},{"id":"s5-137","number":137,"surah":5,"verses":[17,72],"references":[{"surah":5,"verses":[17,72]}],"verseLabel":"المائدة: 17؛ المائدة: 17، 72","question":"ما دلالة تأكيد الحكم في قوله تعالى: ﴿لقد كفر الذين قالوا إن الله هو المسيح ابن مريم﴾؟","answer":"أُكد الخبر باللام الموطئة للقسم و«قد»، لأن أصحاب هذه المقالة كانوا يعتقدون أنهم على الحق؛ فنُزلوا منزلة المنكرين لكفرهم، وجاء التأكيد لإنكار اعتقادهم وردهم إلى توحيد الله وعبادته وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص438، تحت عنوان «دلالة التأكيد في قوله تعالى: ﴿لقد كفر الذين قالوا إن الله هو المسيح ابن مريم﴾»","url":""}]},{"id":"s5-138","number":138,"surah":5,"verses":[17],"references":[{"surah":5,"verses":[17]}],"verseLabel":"المائدة: 17","question":"ما دلالة الاستفهام في قوله تعالى: ﴿فمن يملك من الله شيئًا﴾؟","answer":"هو استفهام للإنكار والتوبيخ، ينفي أن يستطيع أحد رد إرادة الله أو صرف شيء من أمره؛ فهو المالك للوجود كله، ولا يستقل أحد بأمر دونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص729، تحت عنوان «دلالة الاستفهام الإنكاري»","url":""}]},{"id":"s5-627","number":627,"surah":5,"verses":[17],"references":[{"surah":5,"verses":[17]}],"verseLabel":"المائدة: 17","question":"ما وجه التعبير بالملك عن المنع والقدرة في قوله تعالى: ﴿فمن يملك من الله شيئًا﴾؟","answer":"يُفسر الملك هنا بالمنع أو القدرة عليه؛ فنفي أن يملك أحد شيئًا كناية عن نفي قدرته على دفع مراد الله. وبه يتبين أن من يعجز عن دفع الهلاك عن نفسه لا يستحق الألوهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص729–730، تحت عنوان «بلاغة الكناية على المنع والقدرة بالملك»","url":""}]},{"id":"s5-139","number":139,"surah":5,"verses":[17],"references":[{"surah":5,"verses":[17]}],"verseLabel":"المائدة: 17","question":"ما دلالة بناء الحجة على قوله تعالى: ﴿إن أراد أن يهلك المسيح ابن مريم وأمه ومن في الأرض جميعًا﴾؟","answer":"فرضت الآية تعلق القدرة الإلهية بالمسيح وأمه كسائر الخلق، ثم سألت عمن يستطيع المنع؛ فانتقل البرهان من إمكان الهلاك إلى نفي الألوهية عمن لا يملك دفعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص730–731، تحت «سر تقديم الجزاء على الشرط في الجملة الشرطية»","url":""}]},{"id":"s5-140","number":140,"surah":5,"verses":[17],"references":[{"surah":5,"verses":[17]}],"verseLabel":"المائدة: 17","question":"ما دلالة التدرج في ذكر المسيح وأمه ومن في الأرض جميعًا؟","answer":"خُص المسيح وأمه بالذكر لإظهار عجزهما، ثم عمّ بقوله ﴿ومن في الأرض جميعًا﴾ لإدخالهما في جنس المخلوقين الخاضعين لملك الله، وتأكيد أنهما كغيرهما عرضة للهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص732–733، تحت عنوان «سر تعميم إرادة الإهلاك مع حصول الغرض بقصرها على عيسى»","url":""}]},{"id":"s5-141","number":141,"surah":5,"verses":[17],"references":[{"surah":5,"verses":[17]}],"verseLabel":"المائدة: 17","question":"كيف يرد قوله تعالى: ﴿يخلق ما يشاء﴾ على الاستدلال بخلق المسيح من غير أب على ألوهيته؟","answer":"يبين أن الله يخلق على أي كيفية يشاء؛ فخلق إنسان من أنثى وحدها داخل في تنوع خلقه وكمال قدرته. لذلك لا يكون هذا الخلق غير المعتاد دليلًا على ألوهية المخلوق، بل على قدرة خالقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص735–736، تحت عنوان «دلالة الاستئناف بعد التذييل»","url":""}]},{"id":"s5-628","number":628,"surah":5,"verses":[17],"references":[{"surah":5,"verses":[17]}],"verseLabel":"المائدة: 17","question":"ما دلالة قوله تعالى: ﴿والله على كل شيء قدير﴾ بعد ﴿يخلق ما يشاء﴾؟","answer":"هو تذييل يقرر مضمون ما قبله ويعمم القدرة ويؤكدها. وإظهار اسم الجلالة يقوي استقلال الجملة، ويدل على أن القدرة لا تقتصر على الخلق المذكور، بل تشمل كل شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص736، تحت عنوان «السر في التذييل بعد التذييل»","url":""}]},{"id":"s5-142","number":142,"surah":5,"verses":[17],"references":[{"surah":5,"verses":[17]}],"verseLabel":"المائدة: 17","question":"ما سرّ زيادة ﴿لكم﴾ في قوله تعالى في الفتح: ﴿فمن يملك لكم من الله شيئًا﴾، وحذفها في المائدة؟","answer":"في الفتح خوطب المخلفون بأعيانهم في شأن ضرهم ونفعهم، فناسب ﴿لكم﴾ لتخصيص الخطاب بهم. أما في المائدة فجاء النفي عامًا لإبطال مقالة النصارى وإظهار عجز المسيح وأمه وسائر الخلق أمام قدرة الله، فناسب حذفها وعموم العبارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص733–734، تحت «توجيه المتشابه اللفظي بين هذه الآية وآية الفتح»","url":""}]},{"id":"s5-143","number":143,"surah":5,"verses":[18],"references":[{"surah":5,"verses":[18]}],"verseLabel":"المائدة: 18","question":"كيف تُفهم دعوى ﴿نحن أبناء الله وأحباؤه﴾ مع امتناع البنوة الحقيقية لله؟","answer":"من توجيهات المصدر أن التعبير يراد به ادعاء شدة العناية والقرب والمنزلة، كمنزلة الأبناء عند آبائهم؛ ويذكر وجهًا آخر على حذف مضاف، أي أبناء رسل الله. فحاصل الدعوى إثبات فضل وخصوصية لهم على سائر الخلق، لا إثبات بنوة حقيقية صحيحة لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص740–741، تحت عنوان «مجيء الإضافة على خلاف مقتضى الظاهر في معنى البنوة»","url":""}]},{"id":"s5-144","number":144,"surah":5,"verses":[18],"references":[{"surah":5,"verses":[18]}],"verseLabel":"المائدة: 18","question":"ما دلالة الاستفهام في قوله تعالى: ﴿قل فلم يعذبكم بذنوبكم﴾؟","answer":"استفهام إلزامي إنكاري يجعل واقع العقوبة حجة على بطلان دعوى المحبة التي تعصمهم؛ فوجود التعذيب يناقض ما توهموه من خصوصية مطلقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص742–743، تحت «السر في مجيء جواب الشرط على طريقة الإلزام والاحتباك»","url":""}]},{"id":"s5-145","number":145,"surah":5,"verses":[18],"references":[{"surah":5,"verses":[18]}],"verseLabel":"المائدة: 18","question":"ما سرّ التعبير بقوله تعالى: ﴿بل أنتم بشر ممن خلق﴾، دون: بل أنتم عباده؟","answer":"لفظ البشر يسويهم بغيرهم في الطبيعة المخلوقة التي يدعون التميز عليها، و﴿ممن خلق﴾ تدخلهم صراحة في عموم الخلق الخاضع لمشيئته.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص744، تحت «دلالة العطف بحرف الإضراب الانتقالي»","url":""}]},{"id":"s5-146","number":146,"surah":5,"verses":[18],"references":[{"surah":5,"verses":[18]}],"verseLabel":"المائدة: 18","question":"ما دلالة الجمع بين ﴿يغفر لمن يشاء ويعذب من يشاء﴾ بعد نفي دعوى البنوة والمحبة؟","answer":"هذا احتراس من توهم أن نفي البنوة يوجب إهانتهم أو حتم عذابهم؛ فهم كسائر البشر، يغفر الله لمن يشاء ويعذب من يشاء، فلا امتياز يوجب لهم النجاة ولا مجرد البشرية يوجب العقاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص744، تحت «سر الاحتراس بعد ذكر وصف البشرية»","url":""}]},{"id":"s5-147","number":147,"surah":5,"verses":[18],"references":[{"surah":5,"verses":[18]}],"verseLabel":"المائدة: 18","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿وإليه المصير﴾؟","answer":"الجملة تذييل لما قبلها من ذكر المغفرة والعذاب، لأن الرجوع يكون للحساب والجزاء. وتقديم «إليه» يفيد اختصاص الرجوع به سبحانه، وأن ذلك المصير خاضع لتصرفه وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص745، تحت عنوان «سر تقديم الجار والمجرور في جملة التذييل»","url":""}]},{"id":"s5-148","number":148,"surah":5,"verses":[19],"references":[{"surah":5,"verses":[19]}],"verseLabel":"المائدة: 19","question":"ما الصورة في قوله تعالى: ﴿على فترة من الرسل﴾؟","answer":"الفترة سكون وانقطاع بعد نشاط، فصورت المدة بين الرسالات زمنًا فتر فيه توالي الرسل وخفيت معالم من الوحي، فجاء الرسول ﷺ يجدد البيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص755، تحت «سر الاستعارة في التعبير عن الانقطاع بالفترة»","url":""}]},{"id":"s5-149","number":149,"surah":5,"verses":[19],"references":[{"surah":5,"verses":[19]}],"verseLabel":"المائدة: 19","question":"ما وجه اختلاف وصف مجيء الرسول في آيتي المائدة15 و19 بعد تكرار ﴿قد جاءكم رسولنا يبين لكم﴾؟","answer":"في الآية15 وُصف الرسول ببيان كثير مما يخفونه من الكتاب؛ وفي الآية19 وُصف مجيئه بأنه على فترة من الرسل، تذكيرًا بتعاقب رسل الله وأن مجيئه ليس أمرًا مبتدعًا. فلكل موضع وصف يناسب الحجة المقامة فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص752، تحت عنوان «المتشابه اللفظي»","url":""}]},{"id":"s5-629","number":629,"surah":5,"verses":[19],"references":[{"surah":5,"verses":[19]}],"verseLabel":"المائدة: 19","question":"ما نكتة حذف مفعول ﴿يبين لكم﴾ في قوله تعالى: ﴿قد جاءكم رسولنا يبين لكم على فترة من الرسل﴾؟","answer":"من أوجهه تقدير الدين والشرائع التي يحتاجون إلى بيانها، أو ما كانوا يخفونه. ويحتمل ألا يقدر مفعول مخصوص ليعم البيان كل ما يبينه الرسول للناس، أو أن ينزل الفعل منزلة اللازم ليدل على أن البيان وصفه وشأنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص753، تحت عنوان «نكتة حذف المفعول في قوله تعالى: ﴿يبين لكم﴾»","url":""}]},{"id":"s5-150","number":150,"surah":5,"verses":[19],"references":[{"surah":5,"verses":[19]}],"verseLabel":"المائدة: 19","question":"ما دلالة تقديم البشير على النذير في العذر المحكي والجواب عنه؟","answer":"تقديم البشارة أدعى إلى القبول؛ لأن الأصل في دعوة الرسول الرحمة واللطف والتيسير، ثم يأتي الإنذار بما يخافه المعرض. فناسب هذا المقام أن تسبق البشارة النذارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص757–758، تحت «سر تقديم البشارة على النذارة»","url":""}]},{"id":"s5-151","number":151,"surah":5,"verses":[19],"references":[{"surah":5,"verses":[19]}],"verseLabel":"المائدة: 19","question":"ما دلالة التعليل بقوله تعالى: ﴿أن تقولوا ما جاءنا من بشير ولا نذير﴾؟","answer":"من توجيهاته أن الرسول جاء كراهة أن يحتجوا بانقطاع الرسالات وعدم مجيء من يجدد لهم البيان؛ أي لئلا يقولوا هذا القول. فالبيان يقطع عذرهم عند مؤاخذتهم، ولا يعني أنهم لم يأتهم رسول قط.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص756، تحت عنوان «دلالة التعليل في قوله: ﴿أن تقولوا ما جاءنا من بشير ولا نذير﴾»","url":""}]},{"id":"s5-630","number":630,"surah":5,"verses":[19],"references":[{"surah":5,"verses":[19]}],"verseLabel":"المائدة: 19","question":"ما دلالة ﴿من﴾ في قوله تعالى: ﴿ما جاءنا من بشير ولا نذير﴾؟","answer":"دخلت على النكرة في سياق النفي لتوكيد عمومه والمبالغة في تقريره؛ فتصور مقالتهم على نفي مجيء أي بشير أو نذير.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص756، تحت عنوان «نكتة مجيء حرف الجر (من) في قوله: ﴿ما جاءنا من بشير﴾»","url":""}]},{"id":"s5-152","number":152,"surah":5,"verses":[19],"references":[{"surah":5,"verses":[19]}],"verseLabel":"المائدة: 19","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿والله على كل شيء قدير﴾؟","answer":"الفترة توجب حاجة الخلق إلى بعثة الرسل؛ والله قادر على إرسالهم وعلى إمساك إرسالهم. فالتذييل يقرر أن إحياء الهداية بعد انقطاع الرسالات داخل في عموم قدرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص758، تحت «دلالة الختم والتذييل بذكر القدرة»","url":""}]},{"id":"s5-153","number":153,"surah":5,"verses":[20],"references":[{"surah":5,"verses":[20]}],"verseLabel":"المائدة: 20","question":"ما مناسبة بدء موسى خطابه بقوله: ﴿يا قوم اذكروا نعمة الله عليكم﴾ قبل الأمر بدخول الأرض؟","answer":"استثار ذكر النعم الثقة بالطاعة والشجاعة للدخول؛ فمن جعل فيهم الأنبياء وحررهم وملكهم قادر على نصرهم إذا امتثلوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص765، تحت «دلالة تقديم الأمر بتذكر النعم على الأمر بالحرب»","url":""}]},{"id":"s5-154","number":154,"surah":5,"verses":[20],"references":[{"surah":5,"verses":[20]}],"verseLabel":"المائدة: 20","question":"ما سرّ التعبير بـ﴿فيكم أنبياء﴾، ثم ﴿وجعلكم ملوكًا﴾؟","answer":"الأنبياء بعض منهم قائمون في جماعتهم، فناسب ﴿فيكم﴾، أما وصف الملوك أو نعمة الحرية والملك فتعلقت بالجماعة المخاطبة، فجيء بـ﴿جعلكم﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص765–766، تحت «دلالة تقديم النعمة ببعث الأنبياء في بني إسرائيل على غيرها من النعم»","url":""}]},{"id":"s5-155","number":155,"surah":5,"verses":[20],"references":[{"surah":5,"verses":[20]}],"verseLabel":"المائدة: 20","question":"كيف يُفهم قوله تعالى: ﴿وجعلكم ملوكًا﴾ مع أنهم لم يكونوا جميعًا أصحاب عروش؟","answer":"يحتمل أن يكون تشبيهًا لهم بالملوك لاستقلالهم بأمورهم بعد القهر والعبودية، ويحتمل أن يكون التقدير: جعل منكم أو فيكم ملوكًا؛ فلا يلزم أن يكون كل فرد صاحب عرش.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص766، تحت «بلاغة التعبير في قوله ﴿وجعلكم ملوكًا﴾»","url":""}]},{"id":"s5-156","number":156,"surah":5,"verses":[20],"references":[{"surah":5,"verses":[20]}],"verseLabel":"المائدة: 20","question":"كيف يُفهم قوله تعالى: ﴿وآتاكم ما لم يؤت أحدًا من العالمين﴾ مع إيتاء أمم أخرى نعمًا عظيمة؟","answer":"المراد عالمو زمانهم، أو اجتماع نعم مخصوصة لهم كالأنبياء والنجاة والملك والمن والسلوى؛ فلا يقتضي تفضيل كل فرد منهم على جميع الأمم في كل زمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص766–767، تحت «دلالة التعريف بأل بين العهد والاستغراق في العالمين»","url":""}]},{"id":"s5-157","number":157,"surah":5,"verses":[20],"references":[{"surah":5,"verses":[20]}],"verseLabel":"المائدة: 20","question":"ما سرّ إثبات ﴿يا قوم﴾ في خطاب موسى هنا، وحذفها من الخطاب المشابه في سورة إبراهيم؟","answer":"في المائدة عُددت النعم الجسام والتشريف والاعتناء بهم، فناسب نداء القرب ﴿يا قوم﴾؛ أما في إبراهيم فاقتصر التذكير على الإنجاء من آل فرعون، فناسب الاقتصار على الخطاب دون النداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص764–765، تحت «المتشابه اللفظي»","url":""}]},{"id":"s5-158","number":158,"surah":5,"verses":[21],"references":[{"surah":5,"verses":[21]}],"verseLabel":"المائدة: 21","question":"ما معنى وصف الأرض بقوله تعالى ﴿المقدسة﴾؟","answer":"أي المطهرة؛ فالآية تصف الأرض التي أمرهم موسى بدخولها بالطهارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص763، تحت «المعنى الإجمالي»","url":""}]},{"id":"s5-159","number":159,"surah":5,"verses":[21],"references":[{"surah":5,"verses":[21]}],"verseLabel":"المائدة: 21","question":"كيف يُفهم قوله تعالى: ﴿التي كتب الله لكم﴾ مع عقوبتهم بالتيه ومنعهم منها؟","answer":"من الأوجه المذكورة أن الوعد مشروط بالطاعة، فلما لم يوجد الشرط لم يتحقق الموعود حينئذ. وقيل: اللفظ عام والمراد مخصوص، فكأنها مكتوبة لبعضهم ومحرمة على بعضهم؛ وقيل: حُرمت عليهم أربعين سنة ثم حصل لهم ما كُتب.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص769، تحت عنوان «فإن قيل: لم قال ﴿كتب الله لكم﴾ ثم قال ﴿فإنها محرمة عليهم﴾؟»","url":""}]},{"id":"s5-160","number":160,"surah":5,"verses":[21],"references":[{"surah":5,"verses":[21]}],"verseLabel":"المائدة: 21","question":"ما الصورة في قوله تعالى: ﴿ولا ترتدوا على أدباركم﴾؟","answer":"صور العصيان برجوع المرء إلى الوراء على عقبيه بعد أن توجه نحو الغاية؛ فهو تراجع حسي يجسد النكوص عن أمر الله بعد وضوح الطريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص770، تحت عنوان «سر الاستعارة التمثيلية في التعبير عن عدم الامتثال بالارتداد على الأدبار»","url":""}]},{"id":"s5-161","number":161,"surah":5,"verses":[21],"references":[{"surah":5,"verses":[21]}],"verseLabel":"المائدة: 21","question":"ما سرّ التعبير بقوله تعالى: ﴿فتنقلبوا خاسرين﴾، دون: فتكونوا خاسرين؟","answer":"الانقلاب رجوع، ووُصفوا في رجوعهم بالخسران لأنهم يفوتون على أنفسهم خيرًا عظيمًا بالإحجام عن الامتثال والقتال؛ فالتعبير يصل النكوص عن الأمر بمآله الخاسر.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص770، تحت «دلالة الفاء في قوله ﴿فتنقلبوا خاسرين﴾»","url":""}]},{"id":"s5-162","number":162,"surah":5,"verses":[21],"references":[{"surah":5,"verses":[21]}],"verseLabel":"المائدة: 21","question":"لماذا كرر موسى ﴿يا قوم﴾ قبل الأمر بدخول الأرض المقدسة؟","answer":"أعيد النداء اهتمامًا بالأمر وحثًا على امتثاله، وفي إضافتهم إلى نفسه تشريف لهم واستمالة لقلوبهم؛ فناسب تجديد النداء عند الانتقال من تذكيرهم بالنعم إلى تكليفهم بالدخول.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص768، تحت «سر تكرار النداء بعد ذكر النعم والآلاء»","url":""}]},{"id":"s5-163","number":163,"surah":5,"verses":[22],"references":[{"surah":5,"verses":[22]}],"verseLabel":"المائدة: 22","question":"ما دلالة وصف القوم بقوله تعالى: ﴿جبارين﴾ بدل تفصيل قوتهم وعددهم؟","answer":"الجبار هو القاهر الذي يجبر غيره على ما يريد؛ وصيغة المبالغة تضخم شأن القوم وقوتهم، ويزيد تنكير «قومًا» هذا التعظيم والتهويل. فالوصف يصور ما عظم في نفوس القائلين من رهبة عدوهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص775، تحت عنوان «دلالة التعبير بصيغة المبالغة في وصف الأعداء»","url":""}]},{"id":"s5-164","number":164,"surah":5,"verses":[22],"references":[{"surah":5,"verses":[22]}],"verseLabel":"المائدة: 22","question":"ما دلالة تكرار رفضهم الدخول ثم تعليقه على خروج الجبارين؟","answer":"أكدوا أولًا امتناعهم ما دام الجبارون فيها، ثم أعلنوا استعدادًا مشروطًا بزوال الخطر كله؛ فالتكرار يكشف أنهم لا يريدون جهادًا بل دخولًا بلا مقاومة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص774، تحت عنوان «دلالة العطف في قوله تعالى: ﴿إن فيها قومًا جبارين وإنا لن ندخلها حتى يخرجوا منها﴾»","url":""}]},{"id":"s5-165","number":165,"surah":5,"verses":[22],"references":[{"surah":5,"verses":[22]}],"verseLabel":"المائدة: 22","question":"ما دلالة قولهم: ﴿فإن يخرجوا منها فإنا داخلون﴾ بالجملة الاسمية والتوكيد؟","answer":"ثبتوا دخولهم بـ﴿إن﴾ والجملة الاسمية، لكن بعد شرط يفرغه من الشجاعة: لا يدخلون إلا إذا خرج العدو؛ فالتوكيد يبرز مفارقة ثبات القول وضعف الفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص775، تحت «دلالة الشرط في قوله ﴿فإن يخرجوا منها فإنا داخلون﴾»","url":""}]},{"id":"s5-166","number":166,"surah":5,"verses":[23],"references":[{"surah":5,"verses":[23]}],"verseLabel":"المائدة: 23","question":"ما دلالة وصف الرجلين بقوله تعالى: ﴿من الذين يخافون﴾؟","answer":"تفيد «من» أنهما بعض الذين يخافون الله، ووصفهما بذلك يبين وجه نصيحتهما لقومهما؛ فخوفهما من الله حملهما على الحث على دخول الباب امتثالًا لأمره.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص779، تحت عنوان «دلالة شبه الجملة في قوله: ﴿قال رجلان من الذين يخافون﴾»","url":""}]},{"id":"s5-631","number":631,"surah":5,"verses":[23],"references":[{"surah":5,"verses":[23]}],"verseLabel":"المائدة: 23","question":"ما الذي تبينه جملة ﴿أنعم الله عليهما﴾ عن الرجلين اللذين حثا قومهما على الدخول؟","answer":"تحتمل أن تكون استئنافًا يفسر منشأ خوفهما من الله وشجاعتهما؛ فتلك الشجاعة نعمة منه. وتحتمل أن تكون صفة ثانية لهما تشمل الإيمان والتثبيت والثقة بوعد الله والطاعة، أو حالًا تبين أنهما يخافان الله مع إنعامه عليهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص779–780، تحت عنوان «دلالة قوله تعالى: ﴿أنعم الله عليهما﴾ بين الاستئناف والصفة والحالية»","url":""}]},{"id":"s5-167","number":167,"surah":5,"verses":[23],"references":[{"surah":5,"verses":[23]}],"verseLabel":"المائدة: 23","question":"ما دلالة تقديم ﴿عليهم﴾ في قوله تعالى: ﴿ادخلوا عليهم الباب﴾؟","answer":"وجه التقديم النظر إلى مباغتة الجبارين ومواجهتهم قبل ذكر مكان الدخول؛ فالعناية بالفعل الواقع عليهم الذي يكسر هيبتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص780، تحت «نكتة تقديم عليهم في قوله ﴿ادخلوا عليهم الباب﴾»","url":""}]},{"id":"s5-168","number":168,"surah":5,"verses":[23],"references":[{"surah":5,"verses":[23]}],"verseLabel":"المائدة: 23","question":"ما دلالة الجزم بالغلبة في قوله تعالى: ﴿فإذا دخلتموه فإنكم غالبون﴾؟","answer":"بنيا الجزم على وعد الله ومعرفتهما بحال العدو: متى امتثلوا واقتحموا الباب انهارت رهبتهم وحضر نصر الله؛ فجاءت ﴿إن﴾ والجملة الاسمية للتثبيت.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص780–781، تحت «دلالة الشرط والجزاء في قوله ﴿فإذا دخلتموه فإنكم غالبون﴾»","url":""}]},{"id":"s5-169","number":169,"surah":5,"verses":[23],"references":[{"surah":5,"verses":[23]}],"verseLabel":"المائدة: 23","question":"ما دلالة تقديم ﴿وعلى الله﴾ في قوله تعالى: ﴿وعلى الله فتوكلوا﴾؟","answer":"يفيد التقديم الاختصاص والاهتمام؛ فالتوكل على الله وحده في دخول الباب وفي سائر الأعمال، بعد ترتيب الأسباب، دون الاعتماد عليها استقلالًا لأنها لا تؤثر إلا بإذنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص781، تحت عنوان «نكتة تقديم الجار والمجرور ﴿وعلى الله﴾ على الفعل»","url":""}]},{"id":"s5-632","number":632,"surah":5,"verses":[23],"references":[{"surah":5,"verses":[23]}],"verseLabel":"المائدة: 23","question":"ما سرّ ختم الأمر بالتوكل بقوله تعالى: ﴿إن كنتم مؤمنين﴾؟","answer":"ربط التوكل بالإيمان يؤكد الأمر به ويقرره في النفوس؛ فجواب الشرط محذوف دل عليه ما سبق، كأنه قيل: إن كنتم مؤمنين فعلى الله توكلوا. وفي ذلك حث على الثقة بوعد الله عند الإقدام.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص781، تحت عنوان «سر التذييل بالجملة الشرطية»","url":""}]},{"id":"s5-170","number":170,"surah":5,"verses":[24],"references":[{"surah":5,"verses":[24]}],"verseLabel":"المائدة: 24","question":"ما دلالة تأكيد الضمير في قوله تعالى: ﴿فاذهب أنت وربك﴾؟","answer":"تأكيد الضمير المتصل بالمنفصل «أنت» إطناب في التنصل من القتال؛ يزيد إظهار الجفاء والاستخفاف وترك أدب الخطاب مع موسى عليه السلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص787، تحت عنوان «بيان الإطناب في جملة التنصل عن القتال»","url":""}]},{"id":"s5-633","number":633,"surah":5,"verses":[24],"references":[{"surah":5,"verses":[24]}],"verseLabel":"المائدة: 24","question":"ما دلالة قولهم ﴿وربك﴾ بصيغة الخطاب بدل: وربنا؟","answer":"تظهر صيغة الخطاب استخفافهم وتحقيرهم للمخاطب، وجهلهم بالله وصفاته، وتؤكد إنكارهم لتدبير النعم السابقة عليهم؛ فاختيار «ربك» يزيد جفاء مقالتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص788، تحت عنوان «دلالة التعبير بلفظ ﴿وربك﴾ بصيغة الخطاب»","url":""}]},{"id":"s5-171","number":171,"surah":5,"verses":[24],"references":[{"surah":5,"verses":[24]}],"verseLabel":"المائدة: 24","question":"ما دلالة الجمع بين ﴿أبدًا﴾ و﴿ما داموا فيها﴾؟","answer":"﴿أبدًا﴾ تؤكد أنهم لن يدخلوا في أي وقت من أوقات بقاء الجبارين، و﴿ما داموا فيها﴾ يبين الحد الذي علقوا عليه امتناعهم؛ فالأبدية مقيدة بمدة وجودهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص786–787، تحت «فائدة الجمع بين قوله أبدًا وقوله ما داموا فيها»","url":""}]},{"id":"s5-172","number":172,"surah":5,"verses":[24],"references":[{"surah":5,"verses":[24]}],"verseLabel":"المائدة: 24","question":"ما دلالة اسم الإشارة في قولهم: ﴿إنا هاهنا قاعدون﴾؟","answer":"يشيرون إلى المكان الحاضر القريب ويؤكدون أنهم لن يبرحوه؛ فالإشارة المقترنة بالتنبيه تشدد معنى الرفض والتعلق بالمكان وعدم التقدم للقتال.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص788–789، تحت عنوان «سر التعبير باسم الإشارة مسبوقًا بأداة التنبيه»","url":""}]},{"id":"s5-634","number":634,"surah":5,"verses":[24],"references":[{"surah":5,"verses":[24]}],"verseLabel":"المائدة: 24","question":"عن أي خُلُق تكني عبارة ﴿إنا هاهنا قاعدون﴾ في سياق رفض الدخول؟","answer":"هي كناية عن عدم التقدم للحرب جبنًا وعصيانًا؛ إذ جعلوا بقاء الجبارين مانعًا من الدخول الذي يستلزم القتال، ففي العبارة تبكيت على هذا الامتناع المذموم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص789، تحت عنوان «بلاغة الكناية في بيان الأخلاق»","url":""}]},{"id":"s5-635","number":635,"surah":5,"verses":[24],"references":[{"surah":5,"verses":[24]}],"verseLabel":"المائدة: 24","question":"ما نكتة التعبير باسم الفاعل ﴿قاعدون﴾ في قولهم: ﴿إنا هاهنا قاعدون﴾؟","answer":"يدل اسم الفاعل على ثبات القعود ودوامه فيهم، كأنه أمر حاصل مستمر؛ ويقوي هذا المعنى توكيد الجملة بـ«إن» والإشارة إلى مكان القعود.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص790، تحت عنوان «نكتة التعبير بصيغة اسم الفاعل في قوله تعالى: ﴿قاعدون﴾»","url":""}]},{"id":"s5-173","number":173,"surah":5,"verses":[25],"references":[{"surah":5,"verses":[25]}],"verseLabel":"المائدة: 25","question":"كيف يُفهم قول موسى: ﴿إني لا أملك إلا نفسي وأخي﴾ مع رسالته في قومه؟","answer":"الملك هنا القدرة على حمل الغير على الامتثال، لا مقام الرسالة؛ فلما أعلن القوم العصيان لم يبق ممن يضمن طاعته إلا نفسه وأخوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص793–794، تحت «وجه قول موسى ﴿لا أملك إلا نفسي وأخي﴾»","url":""}]},{"id":"s5-174","number":174,"surah":5,"verses":[25],"references":[{"surah":5,"verses":[25]}],"verseLabel":"المائدة: 25","question":"ما سرّ حذف حرف النداء في قوله تعالى: ﴿رب إني لا أملك إلا نفسي وأخي﴾؟","answer":"حذفت ياء النداء لأن الغالب استعمالها للبعيد، والله قريب من عبده؛ فالحذف للاسترحام والمبالغة في تصوير قرب المنادى واستدعاء قرب الإجابة","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص792–793، تحت «نكتة حذف حرف النداء مع رب»","url":""}]},{"id":"s5-175","number":175,"surah":5,"verses":[25],"references":[{"surah":5,"verses":[25]}],"verseLabel":"المائدة: 25","question":"ما دلالة طلب موسى بقوله: ﴿فافرق بيننا وبين القوم الفاسقين﴾؟","answer":"يطلب الفصل بينه وبينهم بحكم الله: أن يحكم له ولمن أطاع بما يستحقون، ويحكم على العصاة بما يستحقون. ويذكر المصدر أيضًا احتمال التفريق بين مسكني الفريقين في الدنيا أو منزلتيهما في الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص795، تحت عنوان «دلالة التعبير بلفظ: ﴿فافرق﴾»","url":""}]},{"id":"s5-636","number":636,"surah":5,"verses":[25],"references":[{"surah":5,"verses":[25]}],"verseLabel":"المائدة: 25","question":"لماذا صرّح موسى بوصف ﴿القوم الفاسقين﴾ بدل أن يقول: بيننا وبينهم؟","answer":"ليكون الدعاء أبلغ وأقرب إلى الأدب في مخاطبة الله، وليتعلق الحكم بوصف الفسق دون تعيين الأشخاص؛ إذ يجوز أن يصلح بعضهم، فلا يشمل الدعاء من زال عنه هذا الوصف.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص796، تحت عنوان «علة التصريح بوصف الفاسقين»","url":""}]},{"id":"s5-176","number":176,"surah":5,"verses":[26],"references":[{"surah":5,"verses":[26]}],"verseLabel":"المائدة: 26","question":"كيف وُصفت الأرض بأنها ﴿محرمة عليهم﴾ مع تحديد التحريم بأربعين سنة؟","answer":"التحريم هنا فعلي واقعي لا تكليفي شرعي؛ أي مُنعوا من دخولها أربعين سنة، فإذا تعلقت المدة بالتحريم كان مؤقتًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص11، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s5-177","number":177,"surah":5,"verses":[26],"references":[{"surah":5,"verses":[26]}],"verseLabel":"المائدة: 26","question":"ما حكمة توقيت التيه بأربعين سنة؟","answer":"يذكر المصدر أن هذه المدة يذهب فيها الجيل الذي تمكن منه العناد والضلال، وينشأ جيل آخر؛ ومن امتد به العمر من الجيل الأول يبلغ من الضعف والشيخوخة ما لا ينتفع معه بدخول الأرض كحال قوته. فالتوقيت يهيئ زوال آثار ذلك الجيل وحاله.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص14، تحت عنوان «حكمة التوقيت بأربعين سنة»","url":""}]},{"id":"s5-178","number":178,"surah":5,"verses":[26],"references":[{"surah":5,"verses":[26]}],"verseLabel":"المائدة: 26","question":"ما دلالة المضارع في قوله تعالى ﴿يتيهون في الأرض﴾؟","answer":"يصور استمرار الضياع وتجدده طوال مدة التيه؛ فهم يبحثون عن المخرج مرارًا ولا يهتدون إليه. فالصيغة تستحضر عذاب الحيرة المتكرر.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص15، تحت «نكتة التعبير بصيغة الفعل المضارع»","url":""}]},{"id":"s5-179","number":179,"surah":5,"verses":[26],"references":[{"surah":5,"verses":[26]}],"verseLabel":"المائدة: 26","question":"ما مناسبة قوله تعالى لموسى: ﴿فلا تأس على القوم الفاسقين﴾؟","answer":"في الخطاب تسلية لموسى، وإشارة إلى تسلية النبي محمد ﷺ؛ فمخالفة الأنبياء عادة للفسقة في الأزمنة، وفيه تذكير بنعمة التوفيق، وترغيب لمن أطاع وترهيب لمن عصى.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص16، تحت عنوان «بلاغة خطاب الأنبياء السابقين في اللاحقين»","url":""}]},{"id":"s5-180","number":180,"surah":5,"verses":[27],"references":[{"surah":5,"verses":[27]}],"verseLabel":"المائدة: 27","question":"لماذا سُمّي خبر ابني آدم ﴿نبأ﴾؟","answer":"النبأ خبر عظيم الشأن ذو فائدة عظيمة؛ ولعظم شأن هذه القصة عُبّر عنها بالنبأ، فهي تفصل خبر أول حادثة قتل عرفتها البشرية.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص24، تحت عنوان «النبأ والخبر»","url":""}]},{"id":"s5-637","number":637,"surah":5,"verses":[27],"references":[{"surah":5,"verses":[27]}],"verseLabel":"المائدة: 27","question":"إلى ماذا يحتمل أن يشير قيد ﴿بالحق﴾ في نبأ ابني آدم؟","answer":"يحتمل أن يشير إلى الزيادات التي ألحقها أهل القصص من بني إسرائيل بأسباب قتل أحد الأخوين الآخر؛ فجاء القيد لتمييز الخبر الحق مما أضيف إلى القصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص20، تحت عنوان «يراد بالحق: الإشارة إلى ما حف بالقصة من زيادات»","url":""}]},{"id":"s5-181","number":181,"surah":5,"verses":[27],"references":[{"surah":5,"verses":[27]}],"verseLabel":"المائدة: 27","question":"ما سرّ إبهام اسمي ابني آدم؟","answer":"أُبهم اسم المتقبَّل منه وغير المتقبَّل منه لأن في الكلام دليلاً عليه، ولا جدوى من التعيين في موضع العبرة","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص22، تحت «وجه إبهام اسم المتقبل منه وغير المتقبل منه»","url":""}]},{"id":"s5-182","number":182,"surah":5,"verses":[27],"references":[{"surah":5,"verses":[27]}],"verseLabel":"المائدة: 27","question":"ما سرّ بناء قوله تعالى: ﴿فتقبل من أحدهما ولم يتقبل من الآخر﴾ للمجهول؟","answer":"بُني الفعلان للمجهول مع العلم بأن المتقبِّل هو الله؛ للإشارة إلى أن أمر القبول وكيفيته الغيبية موكولان إليه، ثم صُرّح باسمه في ﴿إنما يتقبل الله﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص21، تحت «دلالات التعبير عن فعل التقبل بالفعل الذي لم يسم فاعله»","url":""}]},{"id":"s5-183","number":183,"surah":5,"verses":[27],"references":[{"surah":5,"verses":[27]}],"verseLabel":"المائدة: 27","question":"ما دلالة جواب المهدد بقوله تعالى: ﴿إنما يتقبل الله من المتقين﴾ بدل الدفاع عن نفسه؟","answer":"رد سبب رفض قربان أخيه إلى تقواه لا إلى منافسة بينهما؛ والقصر يقرر أن طريق القبول إصلاح النفس، فيحول التهديد إلى موعظة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص23، تحت عنوان «بلاغة الكناية في جواب المقتول»","url":""}]},{"id":"s5-184","number":184,"surah":5,"verses":[28],"references":[{"surah":5,"verses":[28]}],"verseLabel":"المائدة: 28","question":"ما الأثر البلاغي للمقابلة بين ﴿لئن بسطت﴾ و﴿ما أنا بباسط﴾؟","answer":"في الجمع بين الإثبات والنفي طباق السلب؛ يبرز التضاد بين فعل المعتدي وامتناع أخيه، ويظهر الفرق بين جهة الخير وسلامة السريرة وجهة الشر والظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص31، تحت عنوان «جمال المحسنات البديعية في سياق الآية»","url":""}]},{"id":"s5-185","number":185,"surah":5,"verses":[28],"references":[{"surah":5,"verses":[28]}],"verseLabel":"المائدة: 28","question":"ما الصورة في التعبير عن القتل ببسط اليد؟","answer":"بسط اليد كناية عن المباشرة إلى القتل؛ فمعنى ﴿لئن بسطت إلي يدك لتقتلني﴾: لئن باشرت قتلي.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص26، تحت عنوان «بلاغة الكناية في لفظ البسط»","url":""}]},{"id":"s5-638","number":638,"surah":5,"verses":[28],"references":[{"surah":5,"verses":[28]}],"verseLabel":"المائدة: 28","question":"ما نكتة ذكر اليد وإفرادها في قوله تعالى: ﴿لئن بسطت إلي يدك﴾؟","answer":"ذكرت اليد لأنها الآلة الأكثر استعمالًا في القتل، وأفردت لإرادة الجنس أو للاكتفاء بيد واحدة في بعض الأحوال. وفي ذكرها استجلاب لعاطفة الأخوة: فاليد التي يرجى نصرها وإعانتها صارت ممدودة للإضعاف والقتل.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص27، تحت عنوان «نكتة التعبير باليد وإفرادها»","url":""}]},{"id":"s5-186","number":186,"surah":5,"verses":[28],"references":[{"surah":5,"verses":[28]}],"verseLabel":"المائدة: 28","question":"ما غرض الباء في قوله تعالى: ﴿ما أنا بباسط يدي إليك﴾؟","answer":"الباء تؤكد نفي بسط اليد وتبالغ فيه؛ فهي توكيدية في خبر «ما» على إعمالها، أو في خبر المبتدأ على إهمالها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص27، تحت عنوان «غرض حرف (الباء) في قوله: ﴿بباسط﴾»","url":""}]},{"id":"s5-639","number":639,"surah":5,"verses":[28],"references":[{"surah":5,"verses":[28]}],"verseLabel":"المائدة: 28","question":"لماذا قيل ﴿ما أنا بباسط يدي﴾ بالجملة الاسمية بدل: لا أبسط يدي؟","answer":"الجملة الاسمية المنفية تنفي اتصافه بالبسط للقتل وتبالغ في التبرؤ منه؛ فلا يقتصر المعنى على نفي حدوث فعل عابر، بل ينفي أن يكون ذلك شأنًا أو وصفًا ثابتًا له. ويقوي اسم الفاعل والباء هذا النفي.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص27–28، تحت عنوان «علة العدول عن الفعلية إلى الاسمية»","url":""}]},{"id":"s5-187","number":187,"surah":5,"verses":[28],"references":[{"surah":5,"verses":[28]}],"verseLabel":"المائدة: 28","question":"كيف يعلل قوله تعالى: ﴿إني أخاف الله رب العالمين﴾ الامتناع عن القتل؟","answer":"يذكر خوف الله علة لامتناعه عن بسط يده بالقتل، وفيه إرشاد لأخيه إلى الخشية: إذا كان يخاف العقاب على مقابلته، فالمعتدي أولى بالخوف. ويؤكد «إن» وبناء الجملة الاسمية ثبات هذا الخوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص29–30، تحت عنوان «بلاغة الفاصلة القرآنية في التعليل والتأكيد»","url":""}]},{"id":"s5-640","number":640,"surah":5,"verses":[28],"references":[{"surah":5,"verses":[28]}],"verseLabel":"المائدة: 28","question":"ما نكتة التصريح باسم الله في قوله تعالى: ﴿إني أخاف الله﴾؟","answer":"يستحضر اسم الجلالة كمال الله وعلوه، ويشعر بأن سلطانه وحده هو الحاكم على نفس القائل؛ فلا يدفعه الغضب أو حب الانتقام إلى مخالفة أمره.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص30، تحت عنوان «نكتة التصريح باسم الله الأعظم»","url":""}]},{"id":"s5-641","number":641,"surah":5,"verses":[28],"references":[{"surah":5,"verses":[28]}],"verseLabel":"المائدة: 28","question":"لماذا أتبع اسم الله بوصف ﴿رب العالمين﴾ في التعليل بالخوف؟","answer":"يستحضر أنه منشئ الخلق ومربيهم والمنعم عليهم بالإيجاد والتربية؛ فقتل النفس المحرمة هدم لما بناه الله ونشر للفساد. ووصفه بالربوبية يؤكد الخوف ويمنع الإساءة إلى خلقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص30–31، تحت عنوان «إتباع الاسم العظيم الوصف بالربوبية»","url":""}]},{"id":"s5-188","number":188,"surah":5,"verses":[29],"references":[{"surah":5,"verses":[29]}],"verseLabel":"المائدة: 29","question":"كيف يُفهم قوله تعالى: ﴿إني أريد أن تبوء بإثمي وإثمك﴾؛ أيريد لأخيه الإثم؟","answer":"من أوجه تفسيرها أنها ليست محبة للمعصية، بل تخير بين شرين فرضهما تهديد المعتدي: إن أصررت على قتلي فلن أقابلك بالقتل، فتتحمل إثم قتلي مع إثمك السابق، بدل أن أتحمل أنا إثم قتلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص34، تحت عنوان «إرادة الإباءة ليست رغبة وشهوة، وإنما هو تخير في شرين»","url":""}]},{"id":"s5-189","number":189,"surah":5,"verses":[29],"references":[{"surah":5,"verses":[29]}],"verseLabel":"المائدة: 29","question":"ما الذي يضيفه ذكر ﴿وإثمك﴾ إلى وعيد القاتل؟","answer":"يضم إثمَه السابق إلى إثم قتل أخيه، فيذكره بأن الجناية الجديدة تزيد ما يتحمله من الآثام. وفي ذلك تحذير له من عاقبة الإصرار على القتل.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص38، تحت «فن الإدماج البديعي في عطف وإثمك»","url":""}]},{"id":"s5-190","number":190,"surah":5,"verses":[29],"references":[{"surah":5,"verses":[29]}],"verseLabel":"المائدة: 29","question":"ما سرّ التعبير بقوله تعالى: ﴿فتكون من أصحاب النار﴾، دون: فتدخل النار؟","answer":"الصحبة تدل على الملازمة والاستقرار، فتوعده بما وراء مجرد الدخول: أن يصير من الجماعة الملازمة للنار بسبب ظلمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص39، تحت «بلاغة الكناية في لفظ أصحاب»","url":""}]},{"id":"s5-191","number":191,"surah":5,"verses":[29],"references":[{"surah":5,"verses":[29]}],"verseLabel":"المائدة: 29","question":"ما دلالة قوله تعالى: ﴿وذلك جزاء الظالمين﴾، دون: القاتلين؟","answer":"ينبه وصف الظلم إلى السبب الموجب للجزاء: أنه قتل بغير حق. فذكر الوصف يعلل استحقاق العقوبة ويزيد التحذير من الإقدام على هذا العدوان.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص39، تحت عنوان «فائدة ذكر وصف الظلم في قوله: ﴿الظالمين﴾»","url":""}]},{"id":"s5-192","number":192,"surah":5,"verses":[30],"references":[{"surah":5,"verses":[30]}],"verseLabel":"المائدة: 30","question":"ما الصورة في قوله تعالى: ﴿فطوعت له نفسه قتل أخيه﴾؟","answer":"صورت النفس كأنها روضت الجريمة الشاقة وزينتها حتى صارت سهلة طيعة؛ فالفعل يكشف تدرجًا داخليًا سبق القتل لا اندفاعًا لحظيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص43–44، تحت عنوان «فائدة التعبير بالفعل (طوع)»","url":""}]},{"id":"s5-193","number":193,"surah":5,"verses":[30],"references":[{"surah":5,"verses":[30]}],"verseLabel":"المائدة: 30","question":"ما سرّ إظهار الأخوة في قوله تعالى: ﴿قتل أخيه﴾، دون: قتله؟","answer":"إظهار ﴿أخيه﴾ يجدد رابطة القرابة التي كان ينبغي أن تمنع الجريمة، فيزيد القتل فظاعة ويكشف مقدار ما غلب الحسد الفطرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص46، تحت «نكتة التصريح بلفظ الأخوة»","url":""}]},{"id":"s5-194","number":194,"surah":5,"verses":[30],"references":[{"surah":5,"verses":[30]}],"verseLabel":"المائدة: 30","question":"ما دلالة الفاء في قوله تعالى: ﴿فقتله﴾ بعد ﴿فطوعت له نفسه قتل أخيه﴾؟","answer":"تربط القتل بتطويع النفس الذي سبقه، ويُلمح منها أنه ما إن اتخذ قراره حتى سارع إلى تنفيذه، فلم يتوان ولم يتمهل أو يتردد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص46، تحت عنوان «دلالة الفاء في قوله: ﴿فقتله﴾»","url":""}]},{"id":"s5-642","number":642,"surah":5,"verses":[30],"references":[{"surah":5,"verses":[30]}],"verseLabel":"المائدة: 30","question":"ما معنى ﴿فأصبح من الخاسرين﴾ عقب قتل أخيه؟","answer":"من توجيهاته أن «أصبح» بمعنى صار، والخسارة خسارة الآخرة بسبب القتل. ويجوز إبقاؤها على معنى الصباح، فتظهر خسارته في الدنيا بالاضطراب وسوء الحال وخيبة الرجاء؛ ويذكر المصدر وجهي الخسران الدنيوي والأخروي.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص46–47، تحت عنوان «توجيه افتتاح التذييل بلفظ ﴿فأصبح﴾»","url":""}]},{"id":"s5-195","number":195,"surah":5,"verses":[31],"references":[{"surah":5,"verses":[31]}],"verseLabel":"المائدة: 31","question":"ما لطيفة تشبيه القاتل نفسه بالغراب في حسن التدبير؟","answer":"وجه الشبه الحذق وحسن التدبير؛ فالقاتل، مع ما كرمه الله به من العقل، حقر نفسه واستصغرها أمام الغراب بعد أن هبطت بها الجريمة والمعصية، فظهر انكساره وندمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص57، تحت عنوان «لطيفة تشبيه القاتل نفسه بالغراب»","url":""}]},{"id":"s5-196","number":196,"surah":5,"verses":[31],"references":[{"surah":5,"verses":[31]}],"verseLabel":"المائدة: 31","question":"ما سرّ التعبير بقوله تعالى: ﴿يبحث في الأرض ليريه كيف يواري سوأة أخيه﴾، دون: يحفر قبرًا؟","answer":"البحث تقليب التراب وإثارته، فاستحضرت الآية حركة الغراب التي علمت القاتل المواراة، لا النتيجة الجامدة وحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص53، تحت عنوان «نكتة التعبير عن لفظ (البحث) بصيغة المضارع»","url":""}]},{"id":"s5-197","number":197,"surah":5,"verses":[31],"references":[{"surah":5,"verses":[31]}],"verseLabel":"المائدة: 31","question":"ما سرّ تسمية جثة أخيه ﴿سوأة أخيه﴾؟","answer":"السوأة ما يسوء ظهوره ويجب ستره، فصار جسد المقتول بعد تغيره مشهدًا يفضح الجريمة ويستدعي المواراة؛ وفي إضافة الأخ تجديد للتقريع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص55، تحت عنوان «علة التصريح بذكر لفظ السوأة مضافًا إلى الأخ»","url":""}]},{"id":"s5-198","number":198,"surah":5,"verses":[31],"references":[{"surah":5,"verses":[31]}],"verseLabel":"المائدة: 31","question":"ما دلالة قوله: ﴿يا ويلتى﴾ بعد رؤية فعل الغراب؟","answer":"هي كلمة تحسر وتلهف واعتراف باستحقاق العذاب عند الداهية؛ صُوّر الويل كأنه غائب فناداه ليحضر، إعلانًا لحلول سببه وشدة الأسى على ما فعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص56، تحت عنوان «سر التعبير بالتركيب: ﴿يا ويلتى﴾»","url":""}]},{"id":"s5-643","number":643,"surah":5,"verses":[31],"references":[{"surah":5,"verses":[31]}],"verseLabel":"المائدة: 31","question":"ما دلالة الاستفهام في قوله: ﴿أعجزت أن أكون مثل هذا الغراب﴾؟","answer":"يفيد التعجب والإنكار على النفس، والإقرار بالعجز والتحسر؛ فيوبخ نفسه على جهله وغفلته وعدم اهتدائه إلى ما اهتدى إليه الغراب.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص57، تحت عنوان «بلاغة الاستفهام في قوله: ﴿أعجزت أن أكون مثل هذا الغراب﴾»","url":""}]},{"id":"s5-199","number":199,"surah":5,"verses":[31],"references":[{"surah":5,"verses":[31]}],"verseLabel":"المائدة: 31","question":"ما الفرق بين قوله تعالى: ﴿فأصبح من الخاسرين﴾ و﴿فأصبح من النادمين﴾؟","answer":"عقب القتل وصفه بالخسران؛ لأن الجريمة أوقعته فيه، ثم وصفه بالندم بعدما رأى صنيع الغراب وعجزه عن ستر أخيه. فالأولى تبين عاقبة فعله، والثانية تبين ما نشأ في نفسه من حسرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص59–60، تحت عنوان «الفرق بين فاصلة الآية ﴿النادمين﴾ والسابقة ﴿الخاسرين﴾»","url":""}]},{"id":"s5-200","number":200,"surah":5,"verses":[32],"references":[{"surah":5,"verses":[32]}],"verseLabel":"المائدة: 32","question":"إلى ماذا يشير قوله تعالى: ﴿من أجل ذلك﴾ في افتتاح حكم حرمة الدماء؟","answer":"الإشارة إلى الجناية المذكورة وما عرضته القصة من آثار القتل المحرم. وعلى تعلق العبارة بـ«كتبنا» تكون تعليلًا لتشريع تعظيم حرمة الدماء، وفي ذكر السبب تهويل للجريمة وإظهار لشناعتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص64–65، تحت عنوان «فائدة التعليل والإشارة في قوله: ﴿من أجل ذلك﴾»","url":""}]},{"id":"s5-201","number":201,"surah":5,"verses":[32],"references":[{"surah":5,"verses":[32]}],"verseLabel":"المائدة: 32","question":"ما سرّ تخصيص بني إسرائيل في قوله تعالى: ﴿كتبنا على بني إسرائيل﴾ مع أن حرمة القتل عامة؟","answer":"جاء هذا التشريع عقب قصة ابني آدم؛ لما كشفت عنه الجريمة من خطر العدوان في البشر، وخصّ بني إسرائيل بالذكر لأن الحكم كُتب عليهم في شريعتهم ولِما عُرف في تاريخهم من التهاون بالدماء، أما حرمة النفس فليست مقصورة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص66، تحت «علة تخصيص بني إسرائيل بالذكر»","url":""}]},{"id":"s5-202","number":202,"surah":5,"verses":[32],"references":[{"surah":5,"verses":[32]}],"verseLabel":"المائدة: 32","question":"ما المقصود بقيد ﴿بغير نفس أو فساد في الأرض﴾؟","answer":"يستثني من الوعيد القتلَ بحق نفس يوجب قتلها القصاص، أو بسبب فساد يوجب ذلك الحكم. فالمذموم هنا الاعتداء على النفس بغير سبب مشروع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص66–68، تحت «سر العدول عن المصدر الصريح إلى المصدر المؤول»","url":""}]},{"id":"s5-203","number":203,"surah":5,"verses":[32],"references":[{"surah":5,"verses":[32]}],"verseLabel":"المائدة: 32","question":"ما معنى ﴿ومن أحياها فكأنما أحيا الناس جميعًا﴾؟","answer":"من امتنع عن قتل النفس المحرمة أو أنقذها وصان حرمتها كان كمن أحيا الناس في تعظيم حق الحياة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص70، تحت عنوان «بلاغة الشرط والتشبيه»","url":""}]},{"id":"s5-204","number":204,"surah":5,"verses":[32],"references":[{"surah":5,"verses":[32]}],"verseLabel":"المائدة: 32","question":"كيف سمي إنقاذ النفس إحياءً في قوله ﴿ومن أحياها﴾؟","answer":"هذا مجاز مرسل علاقته السببية؛ أطلق الإحياء وأريد سببه، وهو استنقاذ النفس من أسباب الهلاك وصيانتها. وفي التعبير ترغيب في حفظ الدماء والحرص على حياة الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص68–69، تحت «بلاغة المجاز في قوله ومن أحياها»","url":""}]},{"id":"s5-205","number":205,"surah":5,"verses":[32],"references":[{"surah":5,"verses":[32]}],"verseLabel":"المائدة: 32","question":"ما دلالة توكيد مجيء الرسل في قوله تعالى: ﴿ولقد جاءتهم رسلنا بالبينات﴾؟","answer":"أُكد الخبر بالقسم وحرف التحقيق «قد» لإثبات تحقق مضمونه. والتصريح بأن الرسل جاءتهم، لا بمجرد إرسالهم، يقرر وصول الرسالة والبينات إليهم، فيظهر تماديهم في العتو بعد قيام الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص70–71، تحت عنوان «القسم، والتأكيد، وتقديم ما حقه التأخير، وأثر ذلك في تجلية المعنى»","url":""}]},{"id":"s5-644","number":644,"surah":5,"verses":[32],"references":[{"surah":5,"verses":[32]}],"verseLabel":"المائدة: 32","question":"ما دلالة ﴿ثم﴾ في قوله تعالى: ﴿ثم إن كثيرًا منهم بعد ذلك في الأرض لمسرفون﴾؟","answer":"هي للتراخي في الرتبة والاستبعاد؛ فمجيء الرسل بالبينات شأن عجيب، واستمرار الإسراف بعد تلك البينات أعجب، فيشتد التعجيب من مخالفتهم بعد وضوح الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص71، تحت عنوان «بلاغة استعمال اسم الإشارة»","url":""}]},{"id":"s5-206","number":206,"surah":5,"verses":[33],"references":[{"surah":5,"verses":[33]}],"verseLabel":"المائدة: 33","question":"ما دلالة وصف المفسدين بأنهم ﴿يحاربون الله ورسوله﴾؟","answer":"لأن عدوانهم المسلح على الناس وأمن الطريق تمرد على حكم الله وسلطان رسوله، فصُوّر إفسادهم محاربةً لله ورسوله تغليظًا لجريمتهم، لا بمعنى إمكان محاربة الله حقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص77، تحت «الاستئناف وسبب النزول والعطف ووجوه الإعراب وأثرها في تجلية المعنى وإثرائه»","url":""}]},{"id":"s5-207","number":207,"surah":5,"verses":[33],"references":[{"surah":5,"verses":[33]}],"verseLabel":"المائدة: 33","question":"ما سرّ التعبير بقوله تعالى: ﴿ويسعون في الأرض فسادًا﴾ بدل: يفسدون في الأرض؟","answer":"استُعمل السعي هنا في اكتساب الفساد واجتراحه، وعُطف على المحاربة لبيان أن الجزاء متعلق بمجموع الأمرين؛ فالمقصود وصف جريمة مركبة، لا مجرد ذكر الإفساد منفردًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص78، تحت عنوان «بلاغة القصر وفائدته»","url":""}]},{"id":"s5-208","number":208,"surah":5,"verses":[33],"references":[{"surah":5,"verses":[33]}],"verseLabel":"المائدة: 33","question":"ما سرّ تنويع عقوبات الحرابة بين القتل والصلب والقطع والنفي؟","answer":"من أوجه تفسير «أو» أن العقوبات مرتبة بحسب صور الجناية، فتختلف باختلاف القتل وأخذ المال وإخافة الطريق. وقيل إنها للتخيير في العقوبة؛ فالمصدر يذكر خلاف التفسير ولا يحصر اللفظ في وجه واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص80–81، تحت عنوان «دلالات ﴿أو﴾»","url":""}]},{"id":"s5-209","number":209,"surah":5,"verses":[33],"references":[{"surah":5,"verses":[33]}],"verseLabel":"المائدة: 33","question":"ما دلالة قوله تعالى: ﴿تُقطع أيديهم وأرجلهم من خلاف﴾؟","answer":"أي من جهتين متقابلتين؛ فتقطع اليد من جانب والرجل من الجانب الآخر، كاليمنى مع اليسرى. والقيد يبين هيئة القطع، وينفي أن يكون في اليدين أو الرجلين وحدهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص79–80، تحت «فائدة ذكر من خلاف»","url":""}]},{"id":"s5-210","number":210,"surah":5,"verses":[33],"references":[{"surah":5,"verses":[33]}],"verseLabel":"المائدة: 33","question":"ما دلالة الجمع بين ﴿خزي في الدنيا﴾ و﴿عذاب عظيم في الآخرة﴾ في جزاء المحاربين؟","answer":"الخزي هو ما يلحقهم في الدنيا من الذل والفضيحة والعقوبة، والعذاب العظيم جزاء الآخرة على عظم جنايتهم؛ فجمع الوعيد بين العاقبة العاجلة والآجلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص81، تحت عنوان «وجوه الإعراب، وأسلوب الحصر، وأثر ذلك في تجلية المعنى»","url":""}]},{"id":"s5-211","number":211,"surah":5,"verses":[34],"references":[{"surah":5,"verses":[34]}],"verseLabel":"المائدة: 34","question":"ما دلالة تقييد توبة المحاربين بقوله تعالى: ﴿من قبل أن تقدروا عليهم﴾؟","answer":"خُصت التوبة بما قبل القدرة عليهم؛ فتسقط بها عقوبة الحرابة المتعلقة بحق الله، أما الدماء والجراح والأموال فتبقى حقوقًا لأصحابها إلا أن يعفوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص82–83، تحت «الاستثناء وأثره في تجلية المعنى»","url":""}]},{"id":"s5-212","number":212,"surah":5,"verses":[34],"references":[{"surah":5,"verses":[34]}],"verseLabel":"المائدة: 34","question":"ما مناسبة ختم استثناء التائبين بقوله تعالى: ﴿أن الله غفور رحيم﴾؟","answer":"تؤكد الخاتمة قبول التائبين وسقوط العقوبة المختصة بحق الله عنهم، مع بقاء حقوق الناس. وفي المغفرة والرحمة ترغيب في صدق الرجوع إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص82–83، تحت «الاستثناء وأثره في تجلية المعنى»","url":""}]},{"id":"s5-213","number":213,"surah":5,"verses":[35],"references":[{"surah":5,"verses":[35]}],"verseLabel":"المائدة: 35","question":"ما مناسبة الأمر بالتقوى وابتغاء الوسيلة والجهاد بعد ذكر جزاء المحاربين وتوبة من تاب؟","answer":"بعد بيان جزاء أهل الحرابة في الدنيا والآخرة واستثناء من تاب قبل القدرة عليه، انتقل الخطاب إلى أمر المؤمنين بالتقوى والتقرب إلى الله بالطاعات والجهاد في سبيله لنيل الفوز عنده؛ فناسب التحذير من الفساد أن يعقبه الحث على طريق الطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص85، تحت عنوان «مناسبة الآية لما قبلها»","url":""}]},{"id":"s5-214","number":214,"surah":5,"verses":[35],"references":[{"surah":5,"verses":[35]}],"verseLabel":"المائدة: 35","question":"ما دلالة قوله تعالى: ﴿وابتغوا إليه الوسيلة﴾؟","answer":"الوسيلة ما يُتقرّب به إلى الله من الإيمان والطاعة والعمل الصالح، و﴿ابتغوا﴾ تفيد قصدها وطلبها؛ فالمعنى اطلبوا كل سبب مشروع يبلغ بكم رضاه وقربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص85، تحت عنوان «شرح المفردات»","url":""}]},{"id":"s5-215","number":215,"surah":5,"verses":[35],"references":[{"surah":5,"verses":[35]}],"verseLabel":"المائدة: 35","question":"ما مناسبة قوله تعالى: ﴿وجاهدوا في سبيله﴾ بعد الأمر بابتغاء الوسيلة؟","answer":"أُفرد الجهاد بعد عموم الوسيلة لأنه من أفرادها، وخُص بالذكر لأهميته وعلو منزلته في الدعوة إلى دين الله ونشر رسالته","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص87، تحت «سر عطف الخاص على العام»","url":""}]},{"id":"s5-216","number":216,"surah":5,"verses":[35],"references":[{"surah":5,"verses":[35]}],"verseLabel":"المائدة: 35","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿لعلكم تفلحون﴾؟","answer":"تبين الخاتمة أن امتثال هذه الأوامر طريق الفلاح والنجاح عند الله؛ وذلك باجتهاد المؤمن في الطاعة واجتناب ما يسخطه، وأداء فرائضه القلبية والبدنية والمالية.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص86، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s5-217","number":217,"surah":5,"verses":[36],"references":[{"surah":5,"verses":[36]}],"verseLabel":"المائدة: 36","question":"ما دلالة افتراض ملكهم ما في الأرض جميعًا ومثله معه ليفتدوا به؟","answer":"يصور أقصى فدية متخيلة ثم ينفي قبولها، تهويلًا للعذاب وقطعًا لكل أمل في النجاة بالمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص92، تحت عنوان «بلاغة التقديم»","url":""}]},{"id":"s5-218","number":218,"surah":5,"verses":[36],"references":[{"surah":5,"verses":[36]}],"verseLabel":"المائدة: 36","question":"لماذا أُفرد الضمير في ﴿ليفتدوا به﴾ مع ذكر ﴿ما في الأرض جميعًا ومثله معه﴾؟","answer":"من توجيهاته أن الضمير يعود إلى المذكور كله باعتباره مجموعًا واحدًا، أو إلى «ما في الأرض» ومثله معه تابع له. فالإفراد يجمع هذه الفدية المفترضة في شيء واحد يُبذل للخلاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص91–92، تحت «التعليل وجواب الشرط وتأخير ما حقه التقديم وأثر ذلك في تجلية المعنى»","url":""}]},{"id":"s5-219","number":219,"surah":5,"verses":[36],"references":[{"surah":5,"verses":[36]}],"verseLabel":"المائدة: 36","question":"لماذا عقب افتراض الفدية بقوله ﴿ما تُقبل منهم﴾؟","answer":"لإبطال نتيجة الشرط المتوهمة؛ فمهما بلغ المال لا يكون وسيلة خلاص من عذاب القيامة، ثم أكد المصير بقوله ﴿ولهم عذاب أليم﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص91–92، تحت «التعليل وجواب الشرط وتأخير ما حقه التقديم وأثر ذلك في تجلية المعنى»","url":""}]},{"id":"s5-220","number":220,"surah":5,"verses":[37],"references":[{"surah":5,"verses":[37]}],"verseLabel":"المائدة: 37","question":"ما دلالة الجمع بين قوله تعالى: ﴿يريدون أن يخرجوا من النار﴾ وقوله: ﴿وما هم بخارجين منها﴾؟","answer":"تقابل الآية قصدهم الخروج أو تمنّيهم إياه بنفيه المؤكد: فالجملة الاسمية تثبت دوام عدم الخروج، والباء تزيد النفي تقريرًا وتثبيتًا، فتشتد حسرتهم مع عدم حصول مرادهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص99، تحت عنوان «تأكيد الكلام لتقرير المعنى في قوله تعالى: ﴿وما هم بخارجين منها﴾»","url":""}]},{"id":"s5-221","number":221,"surah":5,"verses":[37],"references":[{"surah":5,"verses":[37]}],"verseLabel":"المائدة: 37","question":"ما دلالة المضارع في قوله تعالى: ﴿يريدون أن يخرجوا من النار﴾؟","answer":"المضارع يستحضر إرادتهم المتجددة للخروج كلما اشتد بهم العذاب، مع أن هذه الإرادة المتكررة لا تبلغ غايتها كما يقرر ما بعدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص96، تحت «دلالة التعبير بلفظ يريدون»","url":""}]},{"id":"s5-222","number":222,"surah":5,"verses":[37],"references":[{"surah":5,"verses":[37]},{"surah":11,"verses":[39]}],"verseLabel":"المائدة: 37؛ هود: 39","question":"ما بلاغة وصف العذاب بأنه ﴿مقيم﴾ في خاتمة آية المائدة37؟","answer":"المقيم هو الدائم الذي لا يزول ولا يتحول؛ وفي وصف العذاب باسم الفاعل مبالغة في ثباته، فدوامه عقوبة أشد فوق أصل العذاب. وفي تنكير «مقيم» تعظيم لشأنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص103، تحت عنوان «بلاغة وصف العذاب بلفظ ﴿مقيم﴾ من قوله تعالى: ﴿ولهم عذاب مقيم﴾»","url":""}]},{"id":"s5-645","number":645,"surah":5,"verses":[37],"references":[{"surah":5,"verses":[37]},{"surah":11,"verses":[39]}],"verseLabel":"المائدة: 37؛ هود: 39","question":"ما سرّ المغايرة بين ﴿عذاب يخزيه﴾ و﴿عذاب مقيم﴾ في هود39؟","answer":"من أوجه المصدر أن الأول عذاب الدنيا الذي يخزيهم بالغرق، والثاني عذاب الآخرة الدائم؛ فجيء في الأول بالوصف الفعلي، وفي الثاني بالوصف الاسمي الدال على الثبات. ويذكر وجهًا آخر يعم فيه الخزي الدنيا والآخرة، وتختص الإقامة بعذاب الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص791–792، تحت عنوان «سر المغايرة بين أوصاف العذاب»","url":""}]},{"id":"s5-223","number":223,"surah":5,"verses":[38],"references":[{"surah":5,"verses":[38]},{"surah":24,"verses":[2]}],"verseLabel":"المائدة: 38؛ النور: 2","question":"ما سرّ تقديم السارق على السارقة، وتقديم الزانية على الزاني في سورة النور؟","answer":"من توجيهات التقديم في المصدر أن السرقة تقتضي غالبًا جرأة واقتحامًا يغلب ظهورهما في الرجال، فقدم السارق. وفي آية الزنا قدمت المرأة بالنظر إلى جهة الإغراء وإبداء الزينة. وهذا تعليل لترتيب الذكر، مع شمول الحكم للرجال والنساء.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص110–111، تحت «سبب تقديم لفظ السارق على السارقة»","url":""}]},{"id":"s5-224","number":224,"surah":5,"verses":[38],"references":[{"surah":5,"verses":[38]}],"verseLabel":"المائدة: 38","question":"ما سرّ جمع ﴿الأيدي﴾ في قوله تعالى: ﴿فاقطعوا أيديهما﴾ مع أن المراد يد من كل واحد؟","answer":"من توجيهاته أن السارق والسارقة جنسان يشملان أفرادًا كثيرين، فناسب جمع الأيدي، مع تثنية الضمير باعتبار الجنسين. وقيل إن الجمع أخف من اجتماع تثنيتين في تركيب واحد؛ والمراد يد واحدة من كل سارق.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص112، تحت «دلالة نكتة جمع لفظ الأيدي»","url":""}]},{"id":"s5-225","number":225,"surah":5,"verses":[38],"references":[{"surah":5,"verses":[38]}],"verseLabel":"المائدة: 38","question":"ما دلالة قوله تعالى: ﴿جزاء بما كسبا نكالًا من الله﴾، وما الفرق بين الجزاء والنكال؟","answer":"﴿جزاء﴾ يبين أن العقوبة مقابلة لما كسباه، و﴿نكالًا﴾ يبين أثرها الرادع الذي يمنع الجاني وغيره من العودة؛ فالأول نظر إلى الاستحقاق، والثاني إلى الزجر والاعتبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص114، تحت عنوان «سر مجيء ﴿جزاء﴾ و﴿نكالًا﴾ تعليلين في الكلام في قوله: ﴿جزاء بما كسبا نكالًا من الله﴾»","url":""}]},{"id":"s5-226","number":226,"surah":5,"verses":[38],"references":[{"surah":5,"verses":[38]}],"verseLabel":"المائدة: 38","question":"ما مناسبة ختم حد السرقة بقوله تعالى: ﴿والله عزيز حكيم﴾؟","answer":"﴿عزيز﴾ غالب لا يمتنع عليه إنفاذ حكمه، و﴿حكيم﴾ يضع العقوبة في موضعها ويقدرها بما يحفظ الحقوق؛ فجمعت الخاتمة قوة التشريع وحكمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص118، تحت «مناسبة حسن الختام لمضمون الآية»","url":""}]},{"id":"s5-227","number":227,"surah":5,"verses":[39],"references":[{"surah":5,"verses":[39]}],"verseLabel":"المائدة: 39","question":"ما دلالة الجمع بين التوبة والإصلاح في قوله تعالى: ﴿فمن تاب من بعد ظلمه وأصلح﴾؟","answer":"عطف الإصلاح على التوبة يجعل الشرط في مجموعهما، فلا تكفي التوبة باللفظ إذا لم يصحبها من العمل ما يحققها؛ فاقترانهما بمنزلة أمر واحد يكون جزاؤه قبول التوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص121، تحت عنوان «مناسبة اجتماع جملتين في جملة الشرط في قوله تعالى: ﴿فمن تاب من بعد ظلمه وأصلح﴾»","url":""}]},{"id":"s5-228","number":228,"surah":5,"verses":[39],"references":[{"surah":5,"verses":[39]}],"verseLabel":"المائدة: 39","question":"ما دلالة تسمية السرقة ﴿ظلمًا﴾ في قوله تعالى: ﴿من بعد ظلمه﴾؟","answer":"لأن السارق يضع يده على مال غيره بغير حق، فيظلم صاحبه، ويظلم نفسه بتعريضها للإثم والعقوبة؛ فاللفظ يكشف حقيقة الجناية ولا يقتصر على اسمها الفقهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص120، تحت عنوان «حذف مفعول ﴿ظلمه﴾، من قوله: ﴿فمن تاب من بعد ظلمه﴾»","url":""}]},{"id":"s5-229","number":229,"surah":5,"verses":[39],"references":[{"surah":5,"verses":[39]}],"verseLabel":"المائدة: 39","question":"ما دلالة قوله تعالى بعد توبة العبد: ﴿فإن الله يتوب عليه﴾؟","answer":"توبة العبد رجوعه إلى الله عن المعصية، وتوبة الله عليه قبول توبته. وعُبر عن القبول بالفعل «يتوب» لموافقة «تاب» على طريق الجناس الناقص؛ فاتفقت مادة الفعل واختلفت جهة معناه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص122، تحت عنوان «أثر الجناس الناقص في قوله تعالى: ﴿فمن تاب﴾، ﴿يتوب عليه﴾»","url":""}]},{"id":"s5-230","number":230,"surah":5,"verses":[38,39],"references":[{"surah":5,"verses":[38,39]}],"verseLabel":"المائدة: 38–39","question":"ما سرّ ختم آية الحد بقوله تعالى: ﴿عزيز حكيم﴾، وختم آية التوبة بقوله: ﴿غفور رحيم﴾؟","answer":"ناسب العزة والحكمة مقام إنفاذ الحد وردع الجريمة، وناسبت المغفرة والرحمة مقام التوبة والإصلاح؛ فلكل خاتمة معناها الموافق لما قبلها، واجتمع في السياق العدل وفتح باب الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص132، تحت عنوان «مناسبة اقتران الجملتين في قوله تعالى: ﴿يعذب من يشاء ويغفر لمن يشاء﴾»","url":""}]},{"id":"s5-231","number":231,"surah":5,"verses":[40],"references":[{"surah":5,"verses":[40]}],"verseLabel":"المائدة: 40","question":"ما مناسبة تقرير ملك الله للسماوات والأرض بعد بيان حد السرقة وقبول التوبة؟","answer":"يبين أن الله هو المتصرف في ملكه، فله الحكم بالعقوبة أو المغفرة، وهو أعلم بمواضع العقاب والعفو. فجاء تقرير الملك حجة على ما سبق من إنفاذ الحد وقبول التوبة، وجوابًا عما قد يستغرب من انتقال السارق من العقاب إلى المغفرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص125، تحت عنوان «الربط بين إقامة الحد وقبول التوبة، وكونه سبحانه الفعال لما يريد في ملكه»","url":""}]},{"id":"s5-646","number":646,"surah":5,"verses":[40],"references":[{"surah":5,"verses":[40]}],"verseLabel":"المائدة: 40","question":"ما دلالة الاستفهام في قوله تعالى: ﴿ألم تعلم أن الله له ملك السماوات والأرض﴾؟","answer":"هو استفهام تقريري يقصد به تثبيت العلم بملك الله؛ وجاء في صورة الإنشاء لتنشيط ذهن المخاطب والاعتناء بالمعنى وتقريره، والاستشهاد به على قدرته على التعذيب والمغفرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص127، تحت عنوان «بلاغة الاستفهام المجازي في قوله: ﴿ألم تعلم أن الله له ملك السماوات والأرض﴾»","url":""}]},{"id":"s5-233","number":233,"surah":5,"verses":[40],"references":[{"surah":5,"verses":[40]}],"verseLabel":"المائدة: 40","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿والله على كل شيء قدير﴾؟","answer":"بعد تقرير ملك الله وتعذيبه من يشاء ومغفرته لمن يشاء، جاءت القدرة دليلًا على نفاذ ذلك كله؛ فلا يعجزه إقامة حكم ولا إنفاذ جزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص133، تحت «حسن ختام الآية بجملة التذييل»","url":""}]},{"id":"s5-234","number":234,"surah":5,"verses":[40],"references":[{"surah":5,"verses":[40]}],"verseLabel":"المائدة: 40","question":"ما سرّ تقديم العذاب على المغفرة في قوله تعالى: ﴿يعذب من يشاء ويغفر لمن يشاء﴾ مع أن المغفرة تُقدّم في مواضع أخرى؟","answer":"قدم العذاب لمناسبة ما تقدم من السرقة وعقوبتها، ثم ذكر المغفرة لمناسبة التوبة التي جاءت بعدها؛ فترتيب الجزاء يوافق ترتيب الكلام السابق. وهذا لا ينافي سبق الرحمة، إذ المقام هنا بيان عاقبة الجناية ثم فتح باب الرجوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص131–132، تحت «مناسبة تقديم لفظ يعذب على لفظ ويغفر»","url":""}]},{"id":"s5-235","number":235,"surah":5,"verses":[41],"references":[{"surah":5,"verses":[41]}],"verseLabel":"المائدة: 41","question":"ما دلالة نداء النبي ﷺ بوصف الرسالة في قوله تعالى: ﴿يا أيها الرسول﴾؟","answer":"النداء بوصف ﴿الرسول﴾ تشريف له وتثبيت بأن ما يواجهه داخل في مهمة البلاغ، وفيه تذكير بأن عليه أداء الرسالة وألا يحزنه مسارعة المعاندين في الكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص140–141، تحت «دلالة النداء بقوله تعالى مخاطبًا النبي يا أيها الرسول»","url":""}]},{"id":"s5-236","number":236,"surah":5,"verses":[41],"references":[{"surah":5,"verses":[41]}],"verseLabel":"المائدة: 41","question":"ما دلالة قوله تعالى: ﴿يسارعون في الكفر﴾ دون: إلى الكفر؟","answer":"حرف ﴿في﴾ يصورهم منغمسين في دائرة الكفر يتنقلون مسرعين في أعماله، لا أنهم خارجون عنه ثم يقصدونه كما قد يوحي حرف ﴿إلى﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص144–145، تحت عنوان «سبب إيثار لفظ (في) على لفظ (إلى) في قوله تعالى: ﴿يسارعون في الكفر﴾»","url":""}]},{"id":"s5-237","number":237,"surah":5,"verses":[41],"references":[{"surah":5,"verses":[41]}],"verseLabel":"المائدة: 41","question":"ما سرّ التعبير بلفظ ﴿بأفواههم﴾ في قوله تعالى: ﴿قالوا آمنا بأفواههم﴾؟","answer":"يشعر أن دعواهم قول بالفم لا يوافقه اعتقاد القلب؛ فنسبة القول إلى الأفواه تكشف كذبه. ومن الأوجه المذكورة تصوير مبالغتهم في إطلاق دعوى الإيمان وتضخيمها بألسنتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص146–147، تحت عنوان «سر التعبير بلفظ ﴿بأفواههم﴾ في قوله تعالى: ﴿من الذين قالوا آمنا بأفواههم﴾»","url":""}]},{"id":"s5-647","number":647,"surah":5,"verses":[41],"references":[{"surah":5,"verses":[41]}],"verseLabel":"المائدة: 41","question":"ما دلالة جملة الحال ﴿ولم تؤمن قلوبهم﴾ بعد قولهم ﴿آمنا﴾؟","answer":"تقارن الجملة بين زمن دعوى الإيمان وحال قلوبهم التي خلت منه؛ فتبين أنهم كاذبون في تلك الدعوى، وأن مدار الإيمان على القلب، لا على مجرد القول الظاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص147، تحت عنوان «دلالة جملة الحال في قوله تعالى: ﴿ولم تؤمن قلوبهم﴾»","url":""}]},{"id":"s5-238","number":238,"surah":5,"verses":[41],"references":[{"surah":5,"verses":[41]}],"verseLabel":"المائدة: 41","question":"ما الفرق بين قوله تعالى: ﴿سماعون للكذب﴾ وقوله: ﴿سماعون لقوم آخرين لم يأتوك﴾؟","answer":"من توجيهات المصدر أن الأولى تصف سماعهم لأجل أن يكذبوا فيما ينقلونه، والثانية تصف سماعهم نيابة عن قوم آخرين لم يحضروا المجلس. فتعدد الخبر يكشف غرض السماع ولمن يقع، ولا يكون مجرد تكرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص150، تحت عنوان «تنوع الخبر لتكثير المعنى في قوله تعالى: ﴿سماعون للكذب سماعون لقوم آخرين﴾»","url":""}]},{"id":"s5-239","number":239,"surah":5,"verses":[41],"references":[{"surah":5,"verses":[41]}],"verseLabel":"المائدة: 41","question":"ما دلالة قوله تعالى: ﴿لم يأتوك﴾ في وصف القوم الآخرين؟","answer":"وصفهم بعدم حضور مجلس الرسول ﷺ إيذان بكمال طغيانهم؛ فهم قوم آخرون مستقلون في الرأي والتدبير، ينيبون عنهم السماعين لينقلوا إليهم ما يسمعون","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص151، تحت «نكتة التعبير بقوله لقوم آخرين لم يأتوك يحرفون الكلم»","url":""}]},{"id":"s5-241","number":241,"surah":5,"verses":[41],"references":[{"surah":5,"verses":[41]}],"verseLabel":"المائدة: 41","question":"ما دلالة حكاية قولهم: ﴿إن أوتيتم هذا فخذوه وإن لم تؤتوه فاحذروا﴾؟","answer":"تكشف الحكاية أنهم لم يطلبوا حكم الله طلب إذعان، بل اشترطوا قبول الحكم إن وافق ما اختاروه سلفًا والحذر منه إن خالفه؛ فهي تفضح انتقائية التحاكم وتحريفهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص152، تحت عنوان «ترديد الشرط بين الإثبات والنفي في قوله: ﴿إن أوتيتم هذا فخذوه وإن لم تؤتوه فاحذروا﴾»","url":""}]},{"id":"s5-242","number":242,"surah":5,"verses":[41],"references":[{"surah":5,"verses":[41]}],"verseLabel":"المائدة: 41","question":"ما دلالة لفظ ﴿فتنته﴾ في قوله تعالى: ﴿ومن يرد الله فتنته﴾؟","answer":"المراد بالفتنة هنا الضلال، وسمي بذلك باعتبار ما آل إليه الاختبار؛ فاختيار لفظ الفتنة يصور أنه اختُبر فلم ينجح في الاختبار. وهو مجاز مرسل بالنظر إلى المآل.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص155، تحت عنوان «المجاز المرسل في لفظ ﴿فتنته﴾ من قوله تعالى: ﴿ومن يرد الله فتنته﴾»","url":""}]},{"id":"s5-648","number":648,"surah":5,"verses":[41],"references":[{"surah":5,"verses":[41]}],"verseLabel":"المائدة: 41","question":"لماذا نُفي الملك في قوله تعالى: ﴿فلن تملك له من الله شيئًا﴾؟","answer":"نفي الملك أبلغ من مجرد نفي الاستطاعة؛ فقد يملك الإنسان شيئًا ولا يستطيع التصرف فيه، أما إذا انتفى ملكه للشيء انتفت قدرته على التصرف فيه أصلًا. فإذا كان الخطاب للرسول ﷺ بأنه لا يملك للمفتون من الله شيئًا، فغيره أولى بذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص156، تحت عنوان «إيثار التعبير بنفي الملك دون غيره في قوله: ﴿فلن تملك له﴾»","url":""}]},{"id":"s5-649","number":649,"surah":5,"verses":[41],"references":[{"surah":5,"verses":[41]}],"verseLabel":"المائدة: 41","question":"ما دلالة تنكير ﴿شيئًا﴾ في قوله تعالى: ﴿فلن تملك له من الله شيئًا﴾؟","answer":"وردت النكرة في سياق النفي فأفادت العموم، وجاء لفظ الشيء للمبالغة في استيعاب النفي لكل أمر، ولو كان صغيرًا؛ تأكيدًا أنه لا يملك للمفتون من الله شيئًا من الهداية والرشد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص157، تحت عنوان «مجيء النكرة في سياق النفي في قوله: ﴿فلن تملك له من الله شيئًا﴾»","url":""}]},{"id":"s5-243","number":243,"surah":5,"verses":[41],"references":[{"surah":5,"verses":[41]}],"verseLabel":"المائدة: 41","question":"ما المراد بتطهير القلوب في قوله ﴿لم يرد الله أن يطهر قلوبهم﴾؟","answer":"المراد تخليصها من دنس الكفر؛ والسياق يصف من رسخ في الضلال وسارع فيه. وفي العبارة تحذير من حالهم ودعوة إلى الطهارة الباطنة بالإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص158، تحت «دلالة اسم الإشارة أولئك»","url":""}]},{"id":"s5-244","number":244,"surah":5,"verses":[41],"references":[{"surah":5,"verses":[41]}],"verseLabel":"المائدة: 41","question":"ما دلالة الطباق بين الدنيا والآخرة في قوله تعالى: ﴿لهم في الدنيا خزي ولهم في الآخرة عذاب عظيم﴾؟","answer":"بين الدنيا والآخرة طباق إيجاب، يبين استيعاب العقوبة لهم في الدارين، مع التصريح بنوع العقوبة في كل دار؛ فلا مفر لهم منها في الدنيا والآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص158، تحت عنوان «بديع المطابقة بين الدنيا والآخرة في قوله تعالى: ﴿لهم في الدنيا ولهم في الآخرة﴾»","url":""}]},{"id":"s5-245","number":245,"surah":5,"verses":[42],"references":[{"surah":5,"verses":[42]}],"verseLabel":"المائدة: 42","question":"ما دلالة الجمع بين وصفهم بـ﴿سماعون للكذب﴾ و﴿أكالون للسحت﴾؟","answer":"لأنهم اعتادوا سماع الكذب وأكل المال الحرام حتى صار ذلك طبعًا فيهم؛ فاستمراؤهم باطل القول وزوره أفضى إلى استمراء أكل أموال الناس بالباطل، وجمع الوصفين يكشف ارتباط فساد التلقي بفساد الكسب.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص173، تحت عنوان «العدول عن التعبير باسم الفاعل (سامع للكذب)، (آكل للسحت) إلى التعبير بصيغة المبالغة ﴿سماعون للكذب أكالون للسحت﴾»","url":""}]},{"id":"s5-246","number":246,"surah":5,"verses":[42],"references":[{"surah":5,"verses":[42]}],"verseLabel":"المائدة: 42","question":"ما دلالة تسمية المال الحرام ﴿السحت﴾؟","answer":"السحت في أصله الاستئصال والإتلاف؛ فسُمّي المال الحرام به لأنه لا يبارك لصاحبه، ويمحق البركة ويستأصل المروءة، ومنه الرشوة التي تؤخذ على تبديل الحكم","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص173–174، تحت عنوان «اختيار التعبير بـ(السحت) عن المال الحرام»","url":""}]},{"id":"s5-247","number":247,"surah":5,"verses":[42],"references":[{"surah":5,"verses":[42]}],"verseLabel":"المائدة: 42","question":"ما دلالة تخيير النبي ﷺ في قوله تعالى: ﴿فاحكم بينهم أو أعرض عنهم﴾؟","answer":"أفادت ﴿أو﴾ تخيير الرسول ﷺ بين الحكم بينهم والإعراض عنهم. وهذا تخيير مصلحة واجتهاد فيما فيه الخير، لا تخيير تشهٍّ واتباع رغبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص175، تحت عنوان «دلالة التعبير بـ(أو) في قوله تعالى: ﴿فإن جاؤوك فاحكم بينهم أو أعرض عنهم﴾»","url":""}]},{"id":"s5-248","number":248,"surah":5,"verses":[42],"references":[{"surah":5,"verses":[42]}],"verseLabel":"المائدة: 42","question":"ما مناسبة قوله تعالى: ﴿وإن تعرض عنهم فلن يضروك شيئًا﴾؟","answer":"طمأنه الله أن إعراضه عن تحكيمهم لن يمكّنهم من إيذائه أو إفساد دعوته، فلا يحمله خوف مكرهم على قبول خصومة لم يقصدوا بها الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص176–177، تحت عنوان «دلالة التعبير بـ﴿فلن﴾ في قوله تعالى: ﴿وإن تعرض عنهم فلن يضروك شيئًا﴾»","url":""}]},{"id":"s5-249","number":249,"surah":5,"verses":[42],"references":[{"surah":5,"verses":[42]}],"verseLabel":"المائدة: 42","question":"ما سر التعبير بلفظ ﴿بالقسط﴾ في قوله تعالى: ﴿فاحكم بينهم بالقسط﴾؟","answer":"القسط هو النصيب بالعدل الذي لا نقص فيه ولا جور، وفيه تصوير للعدل كأنه موزون ظاهر. فالأمر به يقتضي إعطاء كل ذي حق حقه، وتسوية الناس في الحكم دون محاباة لشريف أو قوي.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص178–179، تحت عنوان «سر التعبير بلفظ ﴿بالقسط﴾ في قوله تعالى: ﴿وإن حكمت فاحكم بينهم بالقسط﴾»","url":""}]},{"id":"s5-650","number":650,"surah":5,"verses":[42],"references":[{"surah":5,"verses":[42]}],"verseLabel":"المائدة: 42","question":"ما دلالة ختم الأمر بالحكم بالقسط بقوله تعالى: ﴿إن الله يحب المقسطين﴾؟","answer":"فيه ترغيب للحكام والقضاة في إقامة العدل، بإخبارهم أن الله يحب العادلين في أحكامهم؛ حتى تحفظ الحقوق وتستقر الأوضاع وتسعد البشرية.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص179، تحت عنوان «دلالة ختم الآية بقوله تعالى: ﴿إن الله يحب المقسطين﴾»","url":""}]},{"id":"s5-651","number":651,"surah":5,"verses":[42],"references":[{"surah":5,"verses":[42]}],"verseLabel":"المائدة: 42","question":"ما الجمال البلاغي في الجمع بين ﴿بالقسط﴾ و﴿المقسطين﴾ في آية الحكم؟","answer":"بين اللفظين جناس اشتقاق. وفي الآية رد العجز على الصدر، إذ وافقت كلمة ﴿المقسطين﴾ في آخر الكلام كلمة ﴿بالقسط﴾ في صدره.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص180، تحت عنوان «جمالية الجناس في قوله تعالى: ﴿فاحكم بينهم بالقسط إن الله يحب المقسطين﴾»","url":""}]},{"id":"s5-250","number":250,"surah":5,"verses":[43],"references":[{"surah":5,"verses":[43]}],"verseLabel":"المائدة: 43","question":"ما دلالة الاستفهام في قوله تعالى: ﴿وكيف يحكمونك وعندهم التوراة فيها حكم الله﴾؟","answer":"الاستفهام للتعجيب والإنكار؛ إذ يتركون حكم التوراة الموجود عندهم ثم يطلبون حكم النبي ﷺ، لا طلبًا للحق بل رجاء حكم يوافق أهواءهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص186، تحت عنوان «دلالة الاستفهام في قوله تعالى: ﴿وكيف يحكمونك﴾»","url":""}]},{"id":"s5-251","number":251,"surah":5,"verses":[43],"references":[{"surah":5,"verses":[43]}],"verseLabel":"المائدة: 43","question":"ما سر التعبير بـ﴿وعندهم التوراة﴾ دون «معهم التوراة»؟","answer":"التعبير بعندهم يصور التوراة بين أيديهم ملازمة لهم لا تفارقهم، مع علمهم بما فيها من الأحكام، بخلاف المعية التي قد تكون مؤقتة وتحتمل المفارقة. وفيه إقامة الحجة عليهم بما لديهم من الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص187–188، تحت عنوان «سر التعبير بالظرف ﴿وعندهم﴾ في قوله تعالى: ﴿وعندهم التوراة﴾ دون (معهم)»","url":""}]},{"id":"s5-652","number":652,"surah":5,"verses":[43],"references":[{"surah":5,"verses":[43]}],"verseLabel":"المائدة: 43","question":"ما دلالة قوله تعالى عن التوراة: ﴿فيها حكم الله﴾ في سياق التحاكم؟","answer":"يقرر أن حكم الله في المسألة التي اختصموا فيها مثبت في التوراة، فيصدقها في هذه الجزئية، وهي إقامة حد الزنا. ولا يقتضي تصديق هذا الحكم تصديق كل ما بأيديهم بعد ما وقع فيه من تحريف.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص188، تحت عنوان «دلالة التعبير بقوله تعالى: ﴿فيها حكم الله﴾»","url":""}]},{"id":"s5-252","number":252,"surah":5,"verses":[43],"references":[{"surah":5,"verses":[43]}],"verseLabel":"المائدة: 43","question":"ما دلالة ﴿ثم﴾ في قوله تعالى: ﴿ثم يتولون﴾ بعد ذكر تحكيمهم الرسول ﷺ؟","answer":"أفادت الترتيب مع التراخي، لتدل على رسوخ توليهم وإعراضهم وإصرارهم عليه حتى بعد ظهور الآيات الدالة على صدق التحكيم؛ فيزداد فعلهم استبعادًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص189، تحت عنوان «دلالة حرف العطف ﴿ثم﴾ في قوله: ﴿ثم يتولون﴾»","url":""}]},{"id":"s5-653","number":653,"surah":5,"verses":[43],"references":[{"surah":5,"verses":[43]}],"verseLabel":"المائدة: 43","question":"ما دلالة البعدية والإشارة في قوله تعالى: ﴿من بعد ذلك﴾ بعد ﴿ثم يتولون﴾؟","answer":"تشيران إلى التفاوت النفسي الكبير والتراخي المعنوي بين تحاكمهم إلى النبي ﷺ وإعراضهم عما حكم به؛ فهم يعرضون عن حكم وافق كتابهم بعد أن رضوا به حكمًا، فتظهر شدة تناقض موقفهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص190، تحت عنوان «دلالة التعبير بالبعدية والإشارة في قوله تعالى: ﴿من بعد ذلك﴾»","url":""}]},{"id":"s5-253","number":253,"surah":5,"verses":[43],"references":[{"surah":5,"verses":[43]}],"verseLabel":"المائدة: 43","question":"ما مناسبة ختم آية تحاكم اليهود بقوله تعالى: ﴿وما أولئك بالمؤمنين﴾؟","answer":"جاءت الجملة مقررة لما قبلها؛ فتوليهم عن حكم كتابهم وعدم رضاهم به، ثم إعراضهم عن حكم النبي ﷺ، يكشف أنهم ليسوا مؤمنين بكتابهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص191، تحت عنوان «سر ختام الآية بقوله تعالى: ﴿وما أولئك بالمؤمنين﴾»","url":""}]},{"id":"s5-654","number":654,"surah":5,"verses":[43],"references":[{"surah":5,"verses":[43]}],"verseLabel":"المائدة: 43","question":"ما دلالة الباء في قوله تعالى: ﴿وما أولئك بالمؤمنين﴾؟","answer":"جاءت الباء لتأكيد نفي الإيمان عنهم، وفيها تهكم بدعواهم الإيمان مع مخالفة أحكام الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص192، تحت عنوان «دلالة الإتيان بحرف الجر (الباء) في قوله تعالى: ﴿وما أولئك بالمؤمنين﴾»","url":""}]},{"id":"s5-254","number":254,"surah":5,"verses":[44],"references":[{"surah":5,"verses":[44]}],"verseLabel":"المائدة: 44","question":"ما دلالة الجمع بين ﴿هدى﴾ و﴿نور﴾ في وصف التوراة؟","answer":"النور مستعار لبيان الحق، فجمعه مع الهدى يبين أن أحكام التوراة هادية واضحة. ومن التوجيهات أيضًا أن النور مستعار للإيمان والحكمة، فيكون أعم من الهدى، ويكون العطف لهذه المغايرة في العموم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص203، تحت عنوان «دلالة عطف النور على الهدى»","url":""}]},{"id":"s5-255","number":255,"surah":5,"verses":[44],"references":[{"surah":5,"verses":[44]}],"verseLabel":"المائدة: 44","question":"لماذا وُصف النبيون بالإسلام في قوله تعالى: ﴿يحكم بها النبيون الذين أسلموا﴾؟","answer":"هو وصف مدح وثناء، يبين شرف إذعانهم للحق وتنفيذهم الأحكام بلا عوج ولا التواء. وفيه بيان فضل الإسلام وأنه دين الأنبياء جميعًا؛ فتعظم صفة الإسلام بذكرها وصفًا لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص205، تحت عنوان «وصف (النبيون) بالإسلام دون غيره»","url":""}]},{"id":"s5-655","number":655,"surah":5,"verses":[44],"references":[{"surah":5,"verses":[44]}],"verseLabel":"المائدة: 44","question":"ما معنى اللام في قوله تعالى: ﴿للذين هادوا﴾ بعد ﴿يحكم بها النبيون﴾؟","answer":"اللام للأجل؛ أي يحكمون من أجل الذين هادوا، وليست مقصورة على الحكم لصالحهم، فالحكم في الحقيقة لهم وعليهم. وفيها إشعار بانتفاع المحكوم عليه أيضًا بإسقاط تبعة ما عليه ورضاه بالحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص205، تحت عنوان «معنى اللام في قوله تعالى: ﴿للذين هادوا﴾»","url":""}]},{"id":"s5-256","number":256,"surah":5,"verses":[44],"references":[{"surah":5,"verses":[44]}],"verseLabel":"المائدة: 44","question":"ما مناسبة عطف ﴿الربانيون والأحبار﴾ بعد النبيين؟","answer":"يبين العطف أن تطبيق أحكام التوراة لم يكن مقصورًا على النبيين؛ فقد طبّقها الربانيون والأحبار أيضًا، لما اتصفوا به من الإخلاص والعلم العميق، وكونهم ورثة علم النبيين الذين تلقوا عنهم الدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص206، تحت عنوان «دلالة عطف قوله تعالى: ﴿والربانيون والأحبار﴾»","url":""}]},{"id":"s5-257","number":257,"surah":5,"verses":[44],"references":[{"surah":5,"verses":[44]}],"verseLabel":"المائدة: 44","question":"ما دلالة لفظ الاستحفاظ في قوله تعالى: ﴿بما استحفظوا من كتاب الله﴾؟","answer":"الاستحفاظ هو الاستئمان وطلب الحفظ؛ فحُمّلوا أمانة فهم الكتاب وتبليغه على وجهه، وحفظ التوراة من التحريف والتغيير والتبديل، وصيانة أحكامها من الضياع والنسيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص208، تحت عنوان «دلالة التعبير بلفظ الاستحفاظ في قوله تعالى: ﴿بما استحفظوا من كتاب الله﴾»","url":""}]},{"id":"s5-656","number":656,"surah":5,"verses":[44],"references":[{"surah":5,"verses":[44]}],"verseLabel":"المائدة: 44","question":"ما دلالة بناء الفعل ﴿استُحفظوا﴾ للمفعول في آية التوراة؟","answer":"يشير البناء للمفعول إلى أن المحافظة على التوراة أمر معهود إليهم، ومن صفات العهد الذي أُخذ عليهم؛ فليست أمانة حفظها أمرًا اختاروه من عند أنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص209، تحت عنوان «دلالة بناء الفعل ﴿استحفظوا﴾ للمفعول»","url":""}]},{"id":"s5-258","number":258,"surah":5,"verses":[44],"references":[{"surah":5,"verses":[44]}],"verseLabel":"المائدة: 44","question":"ما دلالة حذف ياء المتكلم في قوله تعالى: ﴿واخشون﴾؟","answer":"يربط المصدر الحذف بمراعاة السياق؛ فزيادة الياء في البقرة تناسب زيادة التوكيد في مواجهة الناس وبيان الحق، أما موضع المائدة فليس في السياق نفسه من مجابهة الخلق، فناسب حذفها والاكتفاء بالكسرة الدالة عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص213–214، تحت «سر إثبات الياء في واخشوني في آية البقرة وحذفها في موضعي المائدة»","url":""}]},{"id":"s5-259","number":259,"surah":5,"verses":[44],"references":[{"surah":5,"verses":[44]}],"verseLabel":"المائدة: 44","question":"ما مناسبة الجمع بين النهي عن خشية الناس والنهي عن اشتراء الآيات بثمن قليل؟","answer":"لأن تحريف الحكم قد تدفع إليه رهبة أصحاب النفوذ أو الرغبة في منفعة دنيوية كالرشوة والجاه؛ فواجهت الآية سببي الانحراف: الخوف والطمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص214، تحت عنوان «دلالة عطف قوله: ﴿ولا تشتروا بآياتي ثمنًا قليلًا﴾»","url":""}]},{"id":"s5-260","number":260,"surah":5,"verses":[44],"references":[{"surah":5,"verses":[44]}],"verseLabel":"المائدة: 44","question":"ما فائدة ضمير الفصل ﴿هم﴾ في قوله ﴿فأولئك هم الكافرون﴾؟","answer":"يؤكد القصر المستفاد من تعريف طرفي الجملة، ويبيّن أن ما بعده خبر وليس صفة لما قبله. فاجتمع توكيد الحكم وتمييز بنية الجملة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص217، تحت عنوان «دلالة ضمير الفصل ﴿هم﴾ في قوله تعالى: ﴿فأولئك هم الكافرون﴾»","url":""}]},{"id":"s5-261","number":261,"surah":5,"verses":[44],"references":[{"surah":5,"verses":[44]},{"surah":17,"verses":[2]}],"verseLabel":"المائدة: 44؛ الإسراء: 2","question":"ما سرّ وصف التوراة في الإسراء بأنها ﴿هدى﴾، وفي المائدة بأنها ﴿هدى ونور﴾؟","answer":"اكتفى الإسراء بوصف الهدى لأن الكلام منصبّ على إيتاء موسى الكتاب هدايةً لبني إسرائيل، وجمعت المائدة الهدى والنور لتقرير علو شأن التوراة وزيادة فظاعة حال المحرّفين، مع التدرج في الوصف لأن الإسراء أسبق نزولًا","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص770، تحت عنوان «نكتة الاكتفاء بوصف التوراة بالهدى»","url":""}]},{"id":"s5-262","number":262,"surah":5,"verses":[45],"references":[{"surah":5,"verses":[45]}],"verseLabel":"المائدة: 45","question":"ما دلالة تفصيل القصاص في قوله تعالى: ﴿النفس بالنفس والعين بالعين والأنف بالأنف...﴾؟","answer":"التفصيل يقرر المماثلة في القصاص، وأن النفس تقابل بالنفس والأعضاء بنظائرها، من غير تفريق بين شريف ووضيع؛ فيمنع مجاوزة العدل والتفاضل بين الأنفس","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص226، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s5-263","number":263,"surah":5,"verses":[45],"references":[{"surah":5,"verses":[45]}],"verseLabel":"المائدة: 45","question":"ما سر ترتيب الأعضاء في قوله تعالى: ﴿والعين بالعين والأنف بالأنف والأذن بالأذن والسن بالسن﴾؟","answer":"بُدئ بالعين لشرفها والحاجة إلى البصر وما يتصل به من وظائف حسية ومعنوية، ثم الأنف لما فيه من الشم والتنفس، ثم الأذن مع عظم منفعتها، ثم السن؛ فناسب ترتيبها قدر وظائفها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص230، تحت عنوان «سر الترتيب في ذكر الأعضاء»","url":""}]},{"id":"s5-657","number":657,"surah":5,"verses":[45],"references":[{"surah":5,"verses":[45]}],"verseLabel":"المائدة: 45","question":"ما دلالة ذكر ﴿والجروح﴾ بعد الأعضاء في آية القصاص؟","answer":"يشمل ذلك الجروح التي تقع في أجزاء الجسد ويجري فيها التماثل، مما يتجاوز قطع الأطراف المعينة؛ فيدل على صيانة جسد الإنسان وكرامته حتى في الجرح اليسير.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص230–231، تحت عنوان «دلالة ﴿والجروح﴾»","url":""}]},{"id":"s5-264","number":264,"surah":5,"verses":[45],"references":[{"surah":5,"verses":[45]}],"verseLabel":"المائدة: 45","question":"ما سر الوصف بالمصدر في قوله تعالى: ﴿والجروح قصاص﴾؟","answer":"الوصف بالمصدر أبلغ من الصفة الصريحة؛ فكأن الجروح خُلقت للقصاص لكثرة ارتباطها به، مبالغة في تقريره. وهو أبلغ من تقدير مضاف محذوف، أي: الجروح ذات القصاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص231، تحت عنوان «سر الوصف بالمصدر دون الوصف بالصفة الصريحة في قوله تعالى: ﴿والجروح قصاص﴾»","url":""}]},{"id":"s5-658","number":658,"surah":5,"verses":[45],"references":[{"surah":5,"verses":[45]}],"verseLabel":"المائدة: 45","question":"لماذا جُمعت ﴿الجروح﴾ مع إفراد النفس والعين والأنف والأذن والسن في آية القصاص؟","answer":"جُمعت الجروح لإمكان تعددها في الشخص الواحد، بخلاف الألفاظ المفردة التي سبقتها في تعداد القصاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص230، تحت عنوان «سر إفراد هذه الألفاظ وجمع الجروح»","url":""}]},{"id":"s5-265","number":265,"surah":5,"verses":[45],"references":[{"surah":5,"verses":[45]}],"verseLabel":"المائدة: 45","question":"ما دلالة تسمية العفو عن القصاص ﴿صدقة﴾؟","answer":"لأن العفو إسقاط لحق ثابت في يد مستحق القصاص، فجُعل بمنزلة الصدقة للمبالغة في الترغيب فيه والإشارة إلى عظم ثوابه؛ فشُبّه العفو بالتصدق لاشتراكهما في كثرة الثواب.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص231–232، تحت عنوان «سر إيثار التعبير بالتصدق دون العفو»","url":""}]},{"id":"s5-266","number":266,"surah":5,"verses":[45],"references":[{"surah":5,"verses":[45]}],"verseLabel":"المائدة: 45","question":"إلى من يعود الضمير في قوله تعالى: ﴿فهو كفارة له﴾؟","answer":"يعود في أحد التفسيرين إلى المتصدق صاحب الحق، فيكون عفوه كفارة لذنوبه. ويحتمل عوده إلى الجاني، فيكون العفو والتصدق كفارة له تسقط ما لزمه من القصاص. وورود الاحتمالين لا يقتضي الجزم بأحدهما في كل تفسير.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص232، تحت «دلالة التعبير بقوله كفارة مع ذكر دلالة الضمائر»","url":""}]},{"id":"s5-267","number":267,"surah":5,"verses":[44,45],"references":[{"surah":5,"verses":[44,45]}],"verseLabel":"المائدة: 44–45","question":"ما الفرق بين ختم آية الحكم بقوله تعالى: ﴿الكافرون﴾ وختم آية القصاص بقوله: ﴿الظالمون﴾؟","answer":"ناسب الكفر مقام رد حكم الله وستره، وناسب الظلم مقام مجاوزة العدل في الدماء والقصاص وترك إعطاء كل ذي حق حقه. والأوصاف تتداخل، لكن كل خاتمة أبرزت الجهة الغالبة في سياقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص234–235، تحت عنوان «مناسبة فواصل القرآن لمضمون آياتها»","url":""}]},{"id":"s5-268","number":268,"surah":5,"verses":[46],"references":[{"surah":5,"verses":[46]}],"verseLabel":"المائدة: 46","question":"ما بلاغة اختيار ﴿قفينا﴾ في قوله تعالى: ﴿وقفينا على آثارهم بعيسى ابن مريم﴾؟","answer":"التقفية تقفي الأثر وإتباع الشيء ما قبله، وهي هنا أقوى في تصوير الإتباع والإلحاق؛ لأنها تتعلق باتباع دين وشريعة سماوية، فناسبها التعبير بتقفي الآثار.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص246، تحت عنوان «(قفينا) و(أتبعنا)»","url":""}]},{"id":"s5-269","number":269,"surah":5,"verses":[46],"references":[{"surah":5,"verses":[46]}],"verseLabel":"المائدة: 46","question":"إلى من يعود الضمير في ﴿على آثارهم﴾؟","answer":"يعود إلى النبيين الذين يحكمون بالتوراة، فهم المذكورون في السياق السابق؛ والمعنى أتبعناهم بعيسى ابن مريم. فعبارة «على آثارهم» تدل على المتبوعين وتغني عن التصريح بهم مرة أخرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص241، تحت «حذف المفعول به للفعل وقفينا ودلالة عبارة على آثارهم على المحذوف»","url":""}]},{"id":"s5-270","number":270,"surah":5,"verses":[46],"references":[{"surah":5,"verses":[46]}],"verseLabel":"المائدة: 46","question":"ما دلالة إعادة وصف الإنجيل بالهدى في قوله تعالى: ﴿فيه هدى ونور﴾ ثم ﴿وهدى وموعظة﴾؟","answer":"جاء التكرير وتوالي الأحوال لزيادة التقرير؛ فبعد وصف الإنجيل بأنه مشتمل على الهدى جُعل كله هدى على سبيل المبالغة، وعُطف عليه وصف الموعظة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص243–244، تحت عنوان «دلالة العطف وتوالي الحال في قوله: ﴿وآتيناه الإنجيل﴾ ﴿ومصدقًا﴾ ﴿وهدى وموعظة﴾»","url":""}]},{"id":"s5-659","number":659,"surah":5,"verses":[46],"references":[{"surah":5,"verses":[46]}],"verseLabel":"المائدة: 46","question":"لماذا خُص المتقون بالهدى والموعظة في وصف الإنجيل؟","answer":"لأنهم المهتدون به والمنتفعون بمواعظه؛ فهم الذين يقبلون الحقائق ويطبقونها، فيستقيمون على الطريق ويتجنبون ما تضر عاقبته. فالتخصيص يبين أهل الانتفاع بالكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص244–245، تحت عنوان «تخصيص الهدى والموعظة بالمتقين في قوله: ﴿وهدى وموعظة للمتقين﴾»","url":""}]},{"id":"s5-271","number":271,"surah":5,"verses":[46],"references":[{"surah":5,"verses":[46]}],"verseLabel":"المائدة: 46","question":"ما دلالة قوله تعالى عن عيسى عليه السلام: ﴿مصدقًا لما بين يديه من التوراة﴾؟","answer":"أي مؤيدًا للتوراة السابقة عليه وشاهدًا بصدق أصلها، عاملًا بما لم ينسخ من أحكامها؛ فدعوة عيسى امتداد لأصل الوحي وليست نقضًا له.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص242–243، تحت «دلالة قوله ومصدقًا لما بين يدي من التوراة»","url":""}]},{"id":"s5-272","number":272,"surah":5,"verses":[46],"references":[{"surah":5,"verses":[46]},{"surah":57,"verses":[27]}],"verseLabel":"المائدة: 46؛ الحديد: 27","question":"ما سرّ ذكر ﴿برسلنا﴾ قبل عيسى عليه السلام في سورة الحديد، وعدم ذكره في الموضع المقابل من سورة المائدة؟","answer":"سياق الحديد يستعرض تتابع الرسل في تاريخ الأمم، فناسب قوله: ﴿ثم قفينا على آثارهم برسلنا وقفينا بعيسى ابن مريم﴾. أما المائدة فقد سبقت بذكر النبيين الذين حكموا بالتوراة ثم انتقلت مباشرة إلى عيسى، فكان ذكر ﴿برسلنا﴾ معلومًا من السياق ولا حاجة إلى إعادته.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص343–344، تحت عنوان «بيان المتشابه اللفظي بين هذه الآية وآية المائدة»","url":""}]},{"id":"s5-273","number":273,"surah":5,"verses":[46,48],"references":[{"surah":5,"verses":[46,48]}],"verseLabel":"المائدة: 46، 48","question":"كيف يجتمع تصديق القرآن للكتب السابقة مع نسخه بعض أحكامها؟","answer":"يصدق القرآن ما تقدمه من الوحي في أصول الحق والدعوة إلى الله والعدل والنهي عن المعاصي. ولا ينافي ذلك اختلاف بعض الأحكام تبعًا للعصور؛ فالحكم السابق كان حقًا في عصره، والتصديق به لا يقتضي بقاءه إلى الأبد بعد ورود الناسخ.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص265–266، تحت عنوان «دلالة قوله تعالى: ﴿مصدقًا لما بين يديه﴾ في بيان تصديق القرآن لما قبله»","url":""}]},{"id":"s5-274","number":274,"surah":5,"verses":[47],"references":[{"surah":5,"verses":[47]}],"verseLabel":"المائدة: 47","question":"ما دلالة صيغة الأمر في قوله تعالى: ﴿وليحكم أهل الإنجيل بما أنزل الله فيه﴾؟","answer":"على قراءة الأمر، تلزم العبارة أهل الإنجيل بالحكم والعمل بما أنزل الله فيه، ومنه دلائل رسالة النبي ﷺ ووجوب تصديقه واتباع ما قررته الشريعة. أما العمل بالأحكام التي نُسخت فليس حكمًا بما أنزل الله بعد نسخها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص250، تحت عنوان «دلالة ﴿وليحكم﴾، إما على تقدير حذف (قلنا)، وإما كونها جملة فعلية ابتدائية»","url":""}]},{"id":"s5-275","number":275,"surah":5,"verses":[44,45,46,47],"references":[{"surah":5,"verses":[44,45,46,47]}],"verseLabel":"المائدة: 44–47","question":"ما مناسبة ختم الآية الثالثة في سياق الحكم بقوله تعالى: ﴿فأولئك هم الفاسقون﴾ بعد ﴿الكافرون﴾ و﴿الظالمون﴾؟","answer":"من توجيهات المصدر أن الخاتمة بالكفر جاءت في سياق إنكار حكم الرجم، وبالظلم في سياق الحقوق المتعلقة بالنفوس ومجاوزتها، وبالفسق في وصف الخروج عن الطاعة بترك الحكم عمدًا مع اعتقاد حقيقته؛ فناسب اختلاف التعقيب اختلاف الجهة التي يبرزها السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص217، تحت عنوان «سر اختلاف التعقيب في الآيات الثلاث»","url":""}]},{"id":"s5-276","number":276,"surah":5,"verses":[48],"references":[{"surah":5,"verses":[48]}],"verseLabel":"المائدة: 48","question":"ما دلالة وصف القرآن بأنه ﴿مصدقًا لما بين يديه﴾؟","answer":"يشهد القرآن بصدق الوحي الذي تقدمه؛ فهو يوافقه في الدعوة إلى الحق والعدل بين الناس والنهي عن المعاصي والفواحش، وفي القصص والمواعيد. كما يحقق ما ورد في الكتب السابقة من الإخبار بمجيئه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص265–266، تحت عنوان «دلالة قوله تعالى: ﴿مصدقًا لما بين يديه﴾ في بيان تصديق القرآن لما قبله»","url":""}]},{"id":"s5-660","number":660,"surah":5,"verses":[48],"references":[{"surah":5,"verses":[48]}],"verseLabel":"المائدة: 48","question":"ما دلالة وصف القرآن بأنه ﴿مهيمنًا عليه﴾ بالنسبة إلى الكتب السابقة؟","answer":"هو شاهد وأمين وحافظ ورقيب عليها، يقر صدق ما وافقه مما ينقل عنها، ويكشف ما خالفه؛ فالهيمنة تتضمن الحفظ والارتقاب والحكم على ما تقدمه من الكتب.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص266–267، تحت عنوان «دلالة قوله تعالى: ﴿ومهيمنًا عليه﴾؛ للتعبير عن شهادته عما سبق من إرسالات»","url":""}]},{"id":"s5-277","number":277,"surah":5,"verses":[48],"references":[{"surah":5,"verses":[48]}],"verseLabel":"المائدة: 48","question":"ما دلالة إفراد ﴿الكتاب﴾ في قوله تعالى: ﴿لما بين يديه من الكتاب﴾ مع تعدد الكتب السابقة؟","answer":"أل في ﴿الكتاب﴾ للجنس؛ فالمراد جنس الكتاب السماوي السابق، وهو عنوان نوعي يشمل الكتب المتقدمة، مع استثناء القرآن من هذا العموم بدلالة السياق","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص264–265، تحت «دلالة الألف واللام في قوله الكتاب وأثرها في تجلية المعنى ودقته»","url":""}]},{"id":"s5-278","number":278,"surah":5,"verses":[42,48],"references":[{"surah":5,"verses":[42,48]}],"verseLabel":"المائدة: 42، 48","question":"ما وجه الأمر بقوله تعالى: ﴿فاحكم بينهم بما أنزل الله﴾ بعد التخيير في الآية 42 بين الحكم والإعراض؟","answer":"ذكر المصدر قولًا بأن الأمر نسخ التخيير، ونقل عن الجمهور أنه لا نسخ؛ فالتخيير في قبول الحكم بينهم، فإذا اختار النبي ﷺ الحكم وجب أن يحكم بما أنزل الله، مع النهي عن اتباع أهوائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص267، تحت عنوان «دلالة فعل الأمر على وجوب الحكم بما في القرآن بين أهل الأديان»","url":""}]},{"id":"s5-279","number":279,"surah":5,"verses":[48],"references":[{"surah":5,"verses":[48]}],"verseLabel":"المائدة: 48","question":"ما المقابلة التي تقيمها الآية بين أهوائهم وما جاء من الحق؟","answer":"تنهى عن الانحراف عما جاء من الحق باتباع أهوائهم؛ فالحكم مردّه إلى الوحي لا إلى رغبات الخصوم","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص268، تحت «دلالة أسلوب النهي عن اتباع الأهواء المضطربة»","url":""}]},{"id":"s5-280","number":280,"surah":5,"verses":[48],"references":[{"surah":5,"verses":[48]}],"verseLabel":"المائدة: 48","question":"ما الفرق بين ﴿شرعة﴾ و﴿منهاجًا﴾ في قوله تعالى: ﴿لكل جعلنا منكم شرعة ومنهاجًا﴾؟","answer":"من الأقوال المذكورة أن الشرعة والمنهاج متقاربان، والمراد بهما الدين للتأكيد. وقيل بينهما فرق: الشريعة هي ما أمر الله به عباده، والمنهاج الطريق الواضح الذي يؤدي إلى الشريعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص260، تحت عنوان «﴿شرعة﴾»","url":""}]},{"id":"s5-281","number":281,"surah":5,"verses":[48],"references":[{"surah":5,"verses":[48]}],"verseLabel":"المائدة: 48","question":"هل اختلاف الشرائع في قوله تعالى: ﴿لكل جعلنا منكم شرعة ومنهاجًا﴾ يعني اختلاف أصول الدين؟","answer":"الاختلاف يتعلق بفروع الشرائع وكيفيات العبادات، بحسب مصالح الأمم وحكمة الله في أزمانها؛ أما أصل الإيمان والتوحيد والقيم المشتركة فواحد. فتنوع الفروع لا ينافي وحدة أصول الدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص269، تحت عنوان «علة الجمع بين قوله: ﴿لكل جعلنا منكم شرعة ومنهاجًا﴾، وقوله: ﴿شرع لكم من الدين﴾»","url":""}]},{"id":"s5-282","number":282,"surah":5,"verses":[48],"references":[{"surah":5,"verses":[48]}],"verseLabel":"المائدة: 48","question":"ما دلالة قوله تعالى في اختلاف الشرائع: ﴿ليبلوكم في ما آتاكم﴾؟","answer":"أي ليختبر استجابتكم لما آتاكم من الشرائع المناسبة لأحوال الأمم وأزمانها: أتذعنون لها وتعملون بها عالمين بحكمة الله، أم تنحرفون عن الحق باتباع الهوى؟ فالاختلاف في الأحكام ميدان لامتحان الطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص271، تحت «تعلق المعنى بمحذوف يتطلبه السياق في قوله ولكن ليبلوكم»","url":""}]},{"id":"s5-283","number":283,"surah":5,"verses":[48],"references":[{"surah":5,"verses":[48]}],"verseLabel":"المائدة: 48","question":"ما دلالة قوله تعالى: ﴿فاستبقوا الخيرات﴾ دون: افعلوا الخيرات؟","answer":"الاستباق يصور المبادرة إلى الخيرات والمنافسة في بلوغها، كأن العاملين بها متسابقون يطلب كل منهم السبق إلى الغاية؛ وفيه تأكيد الترغيب في الإذعان للحق والعمل به.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص271–272، تحت عنوان «المجاز في لفظ الاستباق، وأثره في جلاء المعنى في قوله تعالى: ﴿فاستبقوا الخيرات﴾»","url":""}]},{"id":"s5-284","number":284,"surah":5,"verses":[48],"references":[{"surah":5,"verses":[48]}],"verseLabel":"المائدة: 48","question":"كيف يخدم قوله ﴿إلى الله مرجعكم جميعًا﴾ الأمر باستباق الخيرات؟","answer":"جاء تذكيرًا برجوع الجميع إلى الله ليجازيهم ويفصل بينهم فيما اختلفوا فيه؛ فهو تعليل يحث على المبادرة إلى الخيرات قبل يوم الجزاء، ويجمع الترغيب في الثواب والتحذير من العقاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص272–273، تحت «الاستئناف المسوق مساق التعليل لاستباق الخيرات»","url":""}]},{"id":"s5-285","number":285,"surah":5,"verses":[48,49],"references":[{"surah":5,"verses":[48,49]}],"verseLabel":"المائدة: 48–49","question":"ما مناسبة تكرار الأمر بالحكم بما أنزل الله في الآيتين 48 و49؟","answer":"جاء الأمر مؤكدًا الالتزام بالحكم بشريعة القرآن وترك اتباع أهوائهم؛ ومن وجوه العطف أنه متصل بإنزال الكتاب، أي أُنزل إليك الكتاب والحكم به. وذكر المصدر أيضًا أن الآية وردت في قضية أخرى، فالأمر يتجدد بتعدد الوقائع ولا يكون تكرارًا مجردًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص281–282، تحت عنوان «أثر وجوه العطف في تأكيد دلالات السياق في قوله: ﴿وأن احكم بينهم﴾ الآية»","url":""}]},{"id":"s5-286","number":286,"surah":5,"verses":[49],"references":[{"surah":5,"verses":[49]}],"verseLabel":"المائدة: 49","question":"ما دلالة قوله تعالى: ﴿واحذرهم أن يفتنوك عن بعض ما أنزل الله إليك﴾ وذكر ﴿بعض﴾؟","answer":"يحذر من أدنى تنازل عن الوحي؛ لأن صرف الحكم عن بعض ما أنزل الله فتنة ولو بقي أكثره معمولًا به، ولأنهم كانوا يحاولون استمالته في أحكام معينة توافق أهواءهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص282، تحت «ملاحظات ذات دلالة في تجلية المعنى في قوله واحذرهم أن يفتنوك»","url":""}]},{"id":"s5-287","number":287,"surah":5,"verses":[49],"references":[{"surah":5,"verses":[49]}],"verseLabel":"المائدة: 49","question":"ما دلالة قوله تعالى: ﴿فإن تولوا فاعلم أنما يريد الله أن يصيبهم ببعض ذنوبهم﴾؟","answer":"إذا أعرضوا عن حكم الله وأرادوا خلافه عرّضوا أنفسهم للعقاب، وهذا التولي بعض ذنوبهم الكثيرة. والتعبير بالبعض يهوّل شأن جرمهم، ويبين أن المجازاة على بعضه كافية في إهلاكهم، وقد ذكر المصدر عقوبة عاجلة في الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص282–283، تحت عنوان «دلالة الشرط والإبهام، وأثرهما في توضيح المعنى»","url":""}]},{"id":"s5-288","number":288,"surah":5,"verses":[49],"references":[{"surah":5,"verses":[49]}],"verseLabel":"المائدة: 49","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿وإن كثيرًا من الناس لفاسقون﴾؟","answer":"الخاتمة تقرر أن الإعراض عن حكم الله ليس حادثة نادرة، بل يقع من كثير من الناس خروجًا عن طاعته؛ وأكدت الجملة بـ﴿إن﴾ واللام تثبيتًا لهذه الحقيقة مع تجنب تعميمها على الجميع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص284، تحت «دلالة أسلوب الاعتراض التذييلي»","url":""}]},{"id":"s5-289","number":289,"surah":5,"verses":[50],"references":[{"surah":5,"verses":[50]}],"verseLabel":"المائدة: 50","question":"ما دلالة تسمية ما يطلبونه ﴿حكم الجاهلية﴾؟","answer":"كل حكم يُطلب اتباعًا للهوى والعصبية على خلاف وحي الله يلحق بحكم الجاهلية؛ فالجاهلية هنا وصف لمنهج الحكم الذي يجهل الحق أو يتجاهله، لا مجرد اسم لزمن مضى.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص287–288، تحت عنوان «﴿الجاهلية﴾»","url":""}]},{"id":"s5-290","number":290,"surah":5,"verses":[50],"references":[{"surah":5,"verses":[50]}],"verseLabel":"المائدة: 50","question":"ما دلالة الاستفهام في قوله تعالى: ﴿أفحكم الجاهلية يبغون﴾؟","answer":"الاستفهام للإنكار والتوبيخ والتعجيب من إعراضهم عن حكم الله الكامل وطلبهم حكمًا تصنعه الأهواء، وتقديم ﴿حكم الجاهلية﴾ يبرز فداحة المطلوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص289–290، تحت «استفهام إنكاري تعجبي من المشار إليهم»","url":""}]},{"id":"s5-291","number":291,"surah":5,"verses":[50],"references":[{"surah":5,"verses":[50]}],"verseLabel":"المائدة: 50","question":"ما دلالة قوله تعالى: ﴿ومن أحسن من الله حكمًا لقوم يوقنون﴾ وذكر الموقنين؟","answer":"الاستفهام ينفي أن يكون حكم أحسن من حكم الله، وخص الموقنين لأن يقينهم بكمال علمه وعدله وحكمته يجعلهم يدركون هذا الحسن ويذعنون له، بخلاف من تحجبه الأهواء.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص291، تحت عنوان «دلالة الاستفهام الإنكاري في قوله تعالى: ﴿ومن أحسن من الله حكمًا﴾»","url":""}]},{"id":"s5-292","number":292,"surah":5,"verses":[51],"references":[{"surah":5,"verses":[51]}],"verseLabel":"المائدة: 51","question":"ما دلالة النهي عن اتخاذ اليهود والنصارى ﴿أولياء﴾؟","answer":"يفسر المصدر الموالاة المنهي عنها بالمصافاة والانحياز والمناصرة التي تخل بالولاء الإيماني، ويذكر ضمن توجيهاته الولاية الكاملة المقترنة بالرضا بالمعتقد. ويفرق بينها وبين التعامل الذي لا تصاحبه مصافاة أو إخلال بالإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص298–299، تحت عنوان «الجناس الناقص في قوله: ﴿ومن يتولهم منكم فإنه منهم﴾»","url":""}]},{"id":"s5-293","number":293,"surah":5,"verses":[51],"references":[{"surah":5,"verses":[51]}],"verseLabel":"المائدة: 51","question":"ما دلالة قوله تعالى: ﴿بعضهم أولياء بعض﴾؟","answer":"من توجيهاته أن بعض كل فريق يوالي بعضًا من فريقه، لا أن العبارة تثبت بالضرورة موالاة اليهود للنصارى. وجاءت الجملة تعليلًا للنهي، وبيانًا لما يجمع كل فريق من الوفاق في اعتقاده وأعماله.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص297–298، تحت «دلالة الكناية والإجمال في قوله بعضهم أولياء بعض»","url":""}]}]);
